package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.AccountProgress;
import com.danieljglover.allinslayer.model.advisor.AccountProgress.State;
import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.Spellbook;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import lombok.Getter;

/** One requirement decision shared by recommendations and the account panel. */
public final class RequirementEvaluator
{
	private static final String SKILLS = "attack|strength|defence|ranged|prayer|magic|runecraft(?:ing)?|"
		+ "construction|hitpoints|agility|herblore|thieving|crafting|fletching|slayer|hunter|"
		+ "mining|smithing|fishing|cooking|firemaking|woodcutting|farming|sailing|combat";
	private static final Pattern SKILL_FIRST = Pattern.compile("(?i)^(" + SKILLS
		+ ")\\s*(?:level\\s*)?(?:>=|:|=|of|at least)?\\s*(\\d{1,3})\\+?$");
	private static final Pattern LEVEL_FIRST = Pattern.compile("(?i)^(?:level\\s*)?(\\d{1,3})"
		+ "\\+?\\s+(" + SKILLS + ")(?:\\s+level)?$");
	private static final Pattern SKILL_PURPOSE = Pattern.compile("(?i)^((?:level\\s*)?\\d{1,3}\\+?\\s+(?:"
		+ SKILLS + ")|(?:" + SKILLS + ")\\s+(?:level\\s*)?\\d{1,3}\\+?)"
		+ "\\s+(?:(?:is\\s+)?required\\s+)?(?:for|to|before)\\s+(.+)$");
	private static final Pattern EXTRA_CONDITION = Pattern.compile(
		"(?i)[0-9;,]|\\b(and|or|plus|with|without|unless|if|recommended|optional|boost|partial|quest|unlock)\\b");
	private static final Pattern BOOSTED_SKILL = Pattern.compile("(?i)^(\\d{1,3})\\s+(" + SKILLS
		+ ")\\s+with\\s+(.+?)\\s+boost$");
	private static final Pattern DIARY_OR_BOSS = Pattern.compile(
		"^(Medium|Hard) Wilderness Diary completed or (Vet'ion|Callisto|Venenatis) boss assignment$", Pattern.CASE_INSENSITIVE);
	private final RecommendationRequest request;
	private final String planningMonsterId;

	public RequirementEvaluator(RecommendationRequest request)
	{
		this(request, request.getMonsterId());
	}

	public RequirementEvaluator(RecommendationRequest request, String planningMonsterId)
	{
		this.request = request;
		this.planningMonsterId = planningMonsterId;
	}

	/** Assignment alternatives come from live state or an explicit preview, never a saved confirmation. */
	public static String confirmationRequirement(String requirement)
	{
		Matcher matcher = DIARY_OR_BOSS.matcher(requirement.trim());
		return matcher.matches() ? matcher.group(1) + " Wilderness Diary completed" : requirement;
	}

	@Getter
	public static final class Assessment
	{
		private final State state;
		private final String detail;
		private final boolean manual;
		private final boolean assumed;

		private Assessment(State state, String detail, boolean manual)
		{
			this(state, detail, manual, false);
		}

		private Assessment(State state, String detail, boolean manual, boolean assumed)
		{
			this.state = state;
			this.detail = detail;
			this.manual = manual;
			this.assumed = assumed;
		}

		public boolean canConfirm()
		{
			return state == State.UNKNOWN && manual;
		}
	}

	public Assessment assess(String requirement)
	{
		String text = requirement == null ? "" : requirement.trim();
		if (text.isEmpty())
		{
			return known(State.MET, "No requirement.");
		}
		Assessment result = automatic(text);
		String configured = request.getPlayer().getAccountProgress().getConfiguredRequirements().get(AccountProgress.key(text));
		if (result.canConfirm() && request.getPlayer().isLoggedIn() && configured != null)
		{
			return new Assessment(State.MET, configured, false);
		}
		if (result.canConfirm() && request.getPlayer().isLoggedIn()
			&& request.getPlayer().getConfirmedRequirements().stream()
				.anyMatch(value -> AccountProgress.key(value).equals(AccountProgress.key(text))))
		{
			return new Assessment(State.MET, "Manually confirmed for this account.", true);
		}
		return result;
	}

	public boolean isMet(String requirement)
	{
		return assess(requirement).getState() == State.MET;
	}

	void checkAll(List<String> requirements, List<String> blockers)
	{
		if (requirements != null)
		{
			for (String requirement : requirements)
			{
				String failure = failure(requirement);
				if (failure != null) { add(blockers, failure); }
			}
		}
	}

	String failure(String requirement)
	{
		Assessment assessment = assess(requirement);
		if (assessment.getState() == State.MET) { return null; }
		if (assessment.canConfirm()) { return "Confirm requirement: " + requirement; }
		return (assessment.getState() == State.UNMET ? "Requirement not met: " : "Cannot verify requirement: ")
			+ requirement + " (" + assessment.getDetail() + ")";
	}

	private Assessment automatic(String text)
	{
		String lower = AccountProgress.key(text);
		if (lower.equals("none") || lower.equals("none.") || lower.equals("no requirements"))
		{
			return known(State.MET, "No additional requirement.");
		}
		Matcher diaryOrBoss = DIARY_OR_BOSS.matcher(text);
		if (diaryOrBoss.matches())
		{
			Assessment diary = assess(confirmationRequirement(text));
			if (diary.getState() == State.MET) { return diary; }
			String bossId = diaryOrBoss.group(2).equalsIgnoreCase("Vet'ion") ? "vet-ion"
				: diaryOrBoss.group(2).toLowerCase(Locale.ROOT);
			if (request.isTaskPreview() && "boss".equals(request.getTaskId())
				&& bossId.equals(previewBossAssignment()))
			{
				return assumed("On-task preview: assumes the matching " + diaryOrBoss.group(2)
					+ " boss assignment for this access alternative; diary completion is not assumed.");
			}
			if (request.getPlayer().isLoggedIn() && request.isActiveTask() && request.getRemaining() > 0
				&& "boss".equals(request.getTaskId()) && request.getAllowedMonsterIds().contains(bossId))
			{
				return known(State.MET, "The matching boss assignment grants this access alternative.");
			}
			return diary;
		}
		if (lower.equals("task only") || lower.equals("task-only")
			|| lower.equals("on a slayer task") || lower.equals("active slayer task"))
		{
			if (request.isTaskPreview())
			{
				return assumed("On-task preview: assumes the selected Slayer assignment for task-only access; the detected task is unchanged.");
			}
			return known(!request.getPlayer().isLoggedIn() ? State.UNKNOWN
				: request.isActiveTask() && request.getRemaining() > 0 ? State.MET : State.UNMET,
				"Requires an active matching Slayer task.");
		}
		// Whole-name lookup precedes expression splitting: quest names and diary regions
		// can themselves contain 'and', commas, or '&'.
		State observed = request.getPlayer().getAccountProgress().getRequirements().get(lower);
		if (observed == null && lower.endsWith(" (partial)"))
		{
			String completed = lower.substring(0, lower.length() - " (partial)".length());
			// Completion proves a partial-progress gate. An unfinished quest still needs
			// its specific stage checked; do not infer that stage from IN_PROGRESS.
			if (request.getPlayer().getAccountProgress().getRequirements().get(completed) == State.MET)
			{
				return known(State.MET, "Completed quest also satisfies the partial-progress requirement.");
			}
		}
		if (observed != null)
		{
			return known(observed, observed == State.MET ? "Verified from current account progress."
				: observed == State.UNMET ? "Not completed or unlocked on this account."
				: "Current account progress is unavailable.");
		}
		Assessment skill = skill(text);
		if (skill != null) { return skill; }
		Matcher purpose = SKILL_PURPOSE.matcher(text);
		if (purpose.matches() && !EXTRA_CONDITION.matcher(purpose.group(2)).find())
		{
			// Pure level gates may include a location/purpose. Additional conditions remain
			// explicit; a numeric fragment alone cannot verify a whole preparation sentence.
			return skill(purpose.group(1));
		}
		Matcher boosted = BOOSTED_SKILL.matcher(text);
		if (boosted.matches())
		{
			Assessment base = skill(boosted.group(1) + " " + boosted.group(2));
			if (base.getState() != State.MET) { return base; }
			return new Assessment(State.UNKNOWN, base.getDetail() + " Confirm the required "
				+ boosted.group(3) + " boost is prepared.", true);
		}
		Spellbook requiredBook = requiredSpellbook(lower);
		if (requiredBook != null)
		{
			Spellbook currentBook = request.getPlayer().getSpellbook();
			if (currentBook == null)
			{
				return known(State.UNKNOWN, "Current spellbook is unavailable; requires " + requiredBook.getDisplayName() + ".");
			}
			if (currentBook != requiredBook)
			{
				return known(State.UNMET, "Requires " + requiredBook.getDisplayName() + "; currently " + currentBook.getDisplayName() + ".");
			}
			if (lower.equals(requiredBook.getDisplayName().toLowerCase(Locale.ROOT) + " spellbook selected"))
			{
				return known(State.MET, "Current spellbook: " + currentBook.getDisplayName() + ".");
			}
		}
		// Preserve the unknown remainder of a mixed preparation requirement. Known failed
		// clauses still block it, even if the whole sentence has a saved confirmation.
		// Punctuation separates requirements: "quest; mask or helmet" requires the
		// quest whichever head item is chosen. Named facts retain their own punctuation.
		List<String> clauses = splitClauses(lower, "\\s*;\\s*|\\s*,(?!\\s*(?:or|and)\\b)\\s*");
		if (clauses.size() > 1) { return combine(clauses, true); }
		List<String> alternatives = splitClauses(lower, "\\s*,?\\s+or\\s+");
		if (alternatives.size() > 1) { return combine(alternatives, false); }
		clauses = splitClauses(lower, "\\s*,?\\s+and\\s+|\\s+&\\s+");
		if (clauses.size() > 1) { return combine(clauses, true); }
		if (lower.startsWith("quest:"))
		{
			return known(State.UNKNOWN, "This quest's current progress is unavailable.");
		}
		return new Assessment(State.UNKNOWN, request.getPlayer().isLoggedIn()
			? "This requirement has no verified client-state check; confirm it manually if completed."
			: "Log in to check current account progress.", request.getPlayer().isLoggedIn());
	}

	private List<String> splitClauses(String text, String delimiter)
	{
		List<String> clauses = new ArrayList<>();
		Matcher matcher = Pattern.compile(delimiter).matcher(text);
		int start = 0;
		while (matcher.find())
		{
			if (!insideFact(text, matcher.start(), matcher.end()))
			{
				clauses.add(text.substring(start, matcher.start()).trim());
				start = matcher.end();
			}
		}
		clauses.add(text.substring(start).trim());
		return clauses;
	}

	private boolean insideFact(String text, int start, int end)
	{
		for (String name : request.getPlayer().getAccountProgress().getRequirements().keySet())
		{
			if (name.isEmpty()) { continue; }
			for (int at = text.indexOf(name); at >= 0 && at < end; at = text.indexOf(name, at + 1))
			{
				int after = at + name.length();
				if (at <= start && after >= end
					&& (at == 0 || !Character.isLetterOrDigit(text.charAt(at - 1)))
					&& (after == text.length() || !Character.isLetterOrDigit(text.charAt(after))))
				{
					return true;
				}
			}
		}
		return false;
	}

	private Assessment combine(List<String> clauses, boolean all)
	{
		List<Assessment> results = new ArrayList<>();
		for (String clause : clauses) { results.add(assess(clause)); }
		if (all)
		{
			for (Assessment result : results)
			{
				if (result.state == State.UNMET) { return result; }
			}
			if (results.stream().allMatch(result -> result.state == State.MET))
			{
				boolean assumed = results.stream().anyMatch(result -> result.assumed);
				String detail = assumed ? results.stream().filter(result -> result.assumed)
					.map(Assessment::getDetail).distinct().collect(Collectors.joining(" "))
					+ " Other required conditions are satisfied." : "All required conditions are satisfied.";
				return new Assessment(State.MET, detail,
					results.stream().anyMatch(result -> result.manual),
					assumed);
			}
			boolean manual = results.stream().filter(result -> result.state == State.UNKNOWN)
				.allMatch(Assessment::canConfirm);
			return new Assessment(State.UNKNOWN, manual ? "Remaining conditions need manual confirmation."
				: "Some required account progress is unavailable.", manual);
		}
		for (Assessment result : results)
		{
			if (result.state == State.MET && !result.manual) { return result; }
		}
		for (Assessment result : results)
		{
			if (result.state == State.MET) { return result; }
		}
		if (results.stream().allMatch(result -> result.state == State.UNMET))
		{
			return known(State.UNMET, "None of the alternative requirements is met.");
		}
		boolean manual = results.stream().anyMatch(Assessment::canConfirm);
		return new Assessment(State.UNKNOWN, manual ? "An alternative needs manual confirmation."
			: "Account progress for an alternative is unavailable.", manual);
	}

	private Assessment skill(String text)
	{
		Matcher first = SKILL_FIRST.matcher(text);
		Matcher second = LEVEL_FIRST.matcher(text);
		String skill;
		int minimum;
		if (first.matches())
		{
			skill = first.group(1);
			minimum = Integer.parseInt(first.group(2));
		}
		else if (second.matches())
		{
			skill = second.group(2);
			minimum = Integer.parseInt(second.group(1));
		}
		else { return null; }
		skill = skill.toUpperCase(Locale.ROOT).replace("RUNECRAFTING", "RUNECRAFT");
		Integer actual = request.getPlayer().getLevels().get(skill);
		return known(actual == null ? State.UNKNOWN : actual >= minimum ? State.MET : State.UNMET,
			actual == null ? "Current " + skill + " level is unavailable; requires " + minimum + "."
				: "Current " + skill + " level " + actual + "; requires " + minimum + ".");
	}

	private static Spellbook requiredSpellbook(String requirement)
	{
		switch (requirement)
		{
			case "standard spellbook selected": return Spellbook.STANDARD;
			case "ancient magicks spellbook selected": return Spellbook.ANCIENT;
			case "lunar spellbook selected": return Spellbook.LUNAR;
			case "arceuus spellbook selected":
			case "arceuus spellbook with dark demonbane and mark of darkness selected":
			case "slayer 50; 65 magic; arceuus spellbook; ensouled bloodveld head":
			case "expert reanimation on arceuus spellbook; ensouled dagannoth head":
				return Spellbook.ARCEUUS;
			default: return null;
		}
	}

	void level(String skill, int minimum, List<String> blockers)
	{
		if (minimum > 0)
		{
			String failure = failure(skill + " >= " + minimum);
			if (failure != null) { add(blockers, failure); }
		}
	}

	private static Assessment known(State state, String detail)
	{
		return new Assessment(state, detail, false);
	}

	private static Assessment assumed(String detail)
	{
		return new Assessment(State.MET, detail, false, true);
	}

	private String previewBossAssignment()
	{
		// These concrete demi-boss variants count for their matching boss assignment.
		if ("calvar-ion".equals(planningMonsterId)) { return "vet-ion"; }
		if ("artio".equals(planningMonsterId)) { return "callisto"; }
		if ("spindel".equals(planningMonsterId)) { return "venenatis"; }
		return planningMonsterId;
	}

	private static void add(List<String> values, String value)
	{
		if (!values.contains(value)) { values.add(value); }
	}
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.DeathContext;
import com.danieljglover.allinslayer.model.advisor.DeathRule;
import com.danieljglover.allinslayer.model.advisor.ItemValue;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Choice;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Location;
import com.danieljglover.allinslayer.model.advisor.WildernessArea;
import com.danieljglover.allinslayer.model.advisor.WildernessRisk;
import com.danieljglover.allinslayer.model.advisor.WildernessRisk.ItemLoss;
import com.danieljglover.allinslayer.model.advisor.WildernessRisk.Scenario;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import static com.danieljglover.allinslayer.model.advisor.WildernessRisk.saturatedAdd;
import static com.danieljglover.allinslayer.model.advisor.WildernessRisk.saturatedMultiply;

/** Pure PvP death estimates for an entire trip; no client access or item-family normalization. */
public final class WildernessRiskCalculator
{
    private static final int REVENANT_ETHER = 21820;
    private final SlayerCatalogue catalogue;
    private final PlayerSnapshot player;
    private final Location location;
    private final WildernessArea area;
    private final int plannedEtherCharges;

    public WildernessRiskCalculator(SlayerCatalogue catalogue, PlayerSnapshot player, Location location)
    {
        this(catalogue, player, location, 0);
    }

    public WildernessRiskCalculator(SlayerCatalogue catalogue, PlayerSnapshot player, Location location,
        int plannedEtherCharges)
    {
        this.catalogue = catalogue;
        this.player = player;
        this.location = location;
        this.area = catalogue.getWildernessAreas().get(location.getId());
        this.plannedEtherCharges = Math.max(0, Math.min(16000, plannedEtherCharges));
    }

    public boolean applies()
    {
        return location.isWilderness() || area != null && area.isWildernessTravel();
    }

    public WildernessRisk assess(Map<String, Choice> equipment, List<Choice> inventory, long budget)
    {
        Map<Integer, Integer> planned = quantities(equipment, inventory);
        Map<Integer, Integer> pouch = plannedPouchContents(inventory);
        boolean emptyBag = plansEmptyBag(inventory);
        boolean missing = inventory.stream().anyMatch(c -> c.getMissing() > 0)
            || equipment.values().stream().anyMatch(c -> c.getMissing() > 0);
        List<Scenario> plans = scenarios(planned, false, missing, pouch, emptyBag);
        List<Scenario> carried = scenarios(player.getRiskCarried(), true, false, null, false);
        int etherTarget = usesPlannedEther(planned) ? plannedEtherCharges : 0;
        List<String> notes = new ArrayList<>();
        notes.add("PvP death at this destination or on its Wilderness route. Equipment, ammunition, inventory and switches share the protected-item allowance; bank items are not at risk.");
        if (player.getDeathContext().isKnown())
        {
            DeathContext observed = player.getDeathContext();
            notes.add("Observed account: " + (observed.isSkulled() ? "skulled" : "unskulled")
                + "; Protect Item " + (observed.isProtectItemActive() ? "active" : "inactive")
                + (observed.isHighRisk() ? "; high-risk world." : "."));
        }
        notes.add("The baseline does not rely on Protect Item. The additional-item scenario requires the prayer to remain active at death; loot or equipment changes can change which item is protected.");
        if (!pouch.isEmpty())
        {
            notes.add("Planned rune pouch losses use the displayed configuration, not its observed contents. Set that configuration before departure; extra runes increase the loss. Pouch runes are always exposed and do not consume protected-item slots. Actual carried losses retain the observed contents separately.");
        }
        if (emptyBag)
        {
            notes.add("Preparation required: empty the looting bag at a bank before departure. Planned risk uses this empty target, not observed contents. Future loot adds loss; actual carried bag contents remain separately observed or unverified.");
        }
        if (etherTarget > 0)
        {
            notes.add("Planned loss assumes each Wilderness weapon holds " + etherTarget
                + " usable charges (" + (1000 + etherTarget) + " total ether including activation). Planned losses use this target, not observed loaded charges; carrying more ether raises the loss.");
            notes.add("The charge target needs owned loose ether for any shortfall after freshly observed loaded charges, plus any ether packed separately. Activation ether is already present in the charged weapon form. Unverified loaded charges do not count as preparation resources.");
        }
        if (area == null || area.getMaxLevel() < 0)
        {
            notes.add("Wilderness depth is not verified for this location. Above-level-20 death rules are used conservatively.");
        }
        else
        {
            notes.add("Assessed Wilderness levels " + area.getMinLevel() + "-" + area.getMaxLevel()
                + "; the deepest level governs untradeable losses, including travel where documented.");
        }
        if (area != null && area.isPvmUsesPvpRules())
        {
            notes.add("This location also applies PvP-style item losses to monster deaths.");
        }
        else
        {
            notes.add("A monster death without recent player damage normally uses a gravestone. These totals model a PK death, not gravestone reclaim fees.");
        }
        if (area != null && area.getEntryFee() > 0)
        {
            notes.add("Includes the full " + area.getEntryFee() + " gp entry deposit at risk; the current paid balance and kill-based reductions are not observed.");
        }
        notes.add("Loss values use RuneLite's cached prices; protection uses official game values and reviewed overrides. Unpriced items and hidden charges keep an estimate incomplete. The game's Items Kept on Death screen remains authoritative.");
        return new WildernessRisk(location.getName(), budget, plans, carried, notes, etherTarget);
    }

    public Scenario baseline(Map<Integer, Integer> items)
    {
        return calculate(items, false, false, player.getDeathContext().isSkulled(), false, "Baseline");
    }

    public Scenario baseline(Map<String, Choice> equipment, List<Choice> inventory)
    {
        boolean missing = inventory.stream().anyMatch(choice -> choice.getMissing() > 0)
            || equipment.values().stream().anyMatch(choice -> choice.getMissing() > 0);
        return calculate(quantities(equipment, inventory), false, missing,
            player.getDeathContext().isSkulled(), false, "Baseline", plannedPouchContents(inventory), plansEmptyBag(inventory));
    }

    private List<Scenario> scenarios(Map<Integer, Integer> items, boolean actual, boolean missing,
        Map<Integer, Integer> plannedPouch, boolean plannedEmptyBag)
    {
        DeathContext context = player.getDeathContext();
        if (context.isHighRisk() || context.isUltimateIronman())
        {
            return Collections.singletonList(calculate(items, actual, missing, true, false,
                context.isHighRisk() ? "High-risk world: no ordinary items protected"
                    : "Ultimate Ironman: no ordinary items protected", plannedPouch, plannedEmptyBag));
        }
        List<Scenario> result = new ArrayList<>();
        boolean skull = context.isSkulled();
        result.add(calculate(items, actual, missing, skull, false,
            skull ? "Baseline: skulled, no Protect Item" : "Baseline: unskulled, no Protect Item", plannedPouch, plannedEmptyBag));
        result.add(calculate(items, actual, missing, skull, true,
            skull ? "Conditional: skulled + Protect Item" : "Conditional: unskulled + Protect Item", plannedPouch, plannedEmptyBag));
        result.add(calculate(items, actual, missing, !skull, false,
            skull ? "Comparison: unskulled" : "Comparison: skulled", plannedPouch, plannedEmptyBag));
        result.add(calculate(items, actual, missing, !skull, true,
            skull ? "Comparison: unskulled + Protect Item" : "Comparison: skulled + Protect Item", plannedPouch, plannedEmptyBag));
        return result;
    }

    public Scenario calculate(Map<Integer, Integer> quantities, boolean actual, boolean missing,
        boolean skulled, boolean protectItem, String name)
    {
        return calculate(quantities, actual, missing, skulled, protectItem, name, null, false);
    }

    private Scenario calculate(Map<Integer, Integer> quantities, boolean actual, boolean missing,
        boolean skulled, boolean protectItem, String name, Map<Integer, Integer> plannedPouch, boolean plannedEmptyBag)
    {
        DeathContext context = player.getDeathContext();
        int slots = context.isHighRisk() || context.isUltimateIronman() ? 0
            : (skulled ? 0 : 3) + (protectItem ? 1 : 0);
        Set<String> warnings = new LinkedHashSet<>();
        if (!context.isKnown()) { warnings.add("Account skull/world restrictions are unavailable; protection is provisional."); }
        if (context.isUltimateIronman())
        {
            warnings.add("Ultimate Ironman item-loss exceptions are not fully modelled; this is not a verified loss total.");
        }
        if (protectItem && player.getLevels().getOrDefault("PRAYER", 0) < 25)
        {
            warnings.add("Protect Item requires Prayer level 25; this conditional scenario is unavailable at the observed level.");
        }
        if (missing) { warnings.add("The plan has missing or unresolved items; their full risk cannot be verified."); }
        if (!actual && usesPlannedEther(quantities))
        {
            checkEtherResources(quantities, warnings);
        }
        List<Integer> order = new ArrayList<>();
        quantities.forEach((id, count) -> {
            if (id > 0 && count != null && count > 0) { order.add(id); }
        });
        order.sort(Comparator.comparingLong((Integer id) -> protectionValue(id)).reversed().thenComparingInt(id -> id));
        Map<Integer, Integer> protectedCounts = new LinkedHashMap<>();
        int remaining = slots;
        long boundary = -1;
        for (int id : order)
        {
            DeathRule rule = rule(id);
            if (!rule.isProtectable()) { continue; }
            long value = protectionValue(id);
            if (value < 0) { warnings.add("Protection value unavailable for " + itemName(id) + "."); }
            int count = quantities.get(id);
            int kept = Math.min(count, remaining);
            protectedCounts.put(id, kept);
            remaining -= kept;
            if (kept > 0) { boundary = value; }
            if (kept < count && boundary >= 0 && value == boundary && slots > 0)
            {
                // Equal values across distinct IDs can have different break/convert outcomes.
                boolean otherId = protectedCounts.entrySet().stream().anyMatch(e -> e.getKey() != id
                    && e.getValue() > 0 && protectionValue(e.getKey()) == value);
                if (otherId) { warnings.add("Equal protection values cross the kept-item boundary; the exact tied item is not verified."); }
            }
        }
        List<ItemLoss> losses = new ArrayList<>();
        for (int id : order)
        {
            losses.add(outcome(id, quantities.get(id), protectedCounts.getOrDefault(id, 0), actual, plannedEmptyBag, warnings));
        }
        addContents(quantities, actual, plannedPouch, plannedEmptyBag, losses, warnings);
        long lostValue = 0;
        long repairs = 0;
        int permanent = 0;
        for (ItemLoss loss : losses)
        {
            lostValue = saturatedAdd(lostValue, loss.getLostValue());
            repairs = saturatedAdd(repairs, loss.getRepairCost());
            if (loss.isPermanent()) { permanent += loss.getQuantity() - loss.getProtectedQuantity(); }
        }
        return new Scenario(name, slots, lostValue, repairs, area == null ? 0 : area.getEntryFee(),
            permanent, warnings.isEmpty() && losses.stream().allMatch(ItemLoss::isKnown), losses, new ArrayList<>(warnings));
    }

    private ItemLoss outcome(int id, int quantity, int kept, boolean actual, boolean plannedEmptyBag, Set<String> warnings)
    {
        ItemValue value = player.getItemValues().get(id);
        DeathRule rule = rule(id);
        int exposed = quantity - kept;
        long lost = saturatedMultiply(rule.getAlwaysLostValue(), quantity);
        long repair = 0;
        boolean known = rule.getKind() != DeathRule.Kind.UNKNOWN;
        long alwaysComponents = componentValue(rule.getAlwaysLostItems());
        known &= alwaysComponents >= 0;
        lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, alwaysComponents), quantity));
        boolean permanent = false;
        String outcome = exposed == 0 ? "Protected" : "Lost";
        String detail = rule.getNote() == null ? "" : rule.getNote();
        if (!actual && plannedEmptyBag && "LOOTING_BAG".equals(rule.getContentsType()))
        {
            detail = "Preparation target: empty the bag at a bank before departure. Future loot adds loss; current contents are assessed separately. " + detail;
        }
        boolean etherWeapon = "ETHER_WEAPON".equals(rule.getContentsType());
        boolean etherTarget = etherWeapon && !actual && plannedEtherCharges > 0 && applies();
        if (etherTarget)
        {
            long etherPrice = price(REVENANT_ETHER);
            known &= etherPrice >= 0;
            lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, etherPrice),
                saturatedMultiply(plannedEtherCharges, quantity)));
            detail = "Planned loss assumes " + plannedEtherCharges + " usable charges plus 1,000 activation ether per weapon, all lost even when protected. Actual carried loss uses an observed balance when available.";
        }
        else if (etherWeapon)
        {
            com.danieljglover.allinslayer.model.advisor.ChargeObservation observed = actual && quantity == 1
                ? player.getPreparation().getCharges().get(id) : null;
            if (observed != null && observed.isObserved() && observed.getCharges() >= 0)
            {
                long etherPrice = price(REVENANT_ETHER);
                known &= etherPrice >= 0;
                lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, etherPrice), observed.getCharges()));
                detail = "Latest carried Check: " + observed.getCharges()
                    + " usable charges plus 1,000 activation ether, all lost even when protected.";
            }
            else
            {
                known = false;
                warnings.add(itemName(id) + ": loaded ether is unverified; the 1,000 activation ether is only the minimum loss.");
            }
        }
        else if (value != null && value.isChargesUnknown())
        {
            if (exposed == 0 && rule.isChargesKeptWhenProtected())
            {
                detail = "Stored charges are retained while this item remains protected. " + detail;
            }
            else
            {
                known = false;
                warnings.add(itemName(id) + ": stored charges or contents are not fully valued.");
            }
        }
        if (exposed > 0)
        {
            switch (rule.getKind())
            {
                case KEEP:
                    outcome = "Kept";
                    break;
                case REPAIR:
                    outcome = "Kept broken";
                    known &= rule.isRepairCostKnown();
                    repair = saturatedMultiply(rule.getRepairCost(), exposed);
                    break;
                case LOCKABLE:
                    if (aboveTwenty() && !rule.isLocked())
                    {
                        outcome = "Permanently lost";
                        permanent = true;
                        detail = "Unlocked untradeable above level 20. " + detail;
                    }
                    else
                    {
                        outcome = aboveTwenty() ? "Kept mangled" : "Kept broken";
                        known &= aboveTwenty() || rule.isRepairCostKnown();
                        repair = saturatedMultiply(aboveTwenty() ? 500000 : rule.getRepairCost(), exposed);
                        if (rule.isLocked()) { detail = "Trouver lock retained. " + detail; }
                    }
                    break;
                case POUCH:
                    outcome = rule.isLocked() ? "Pouch kept; contents lost" : "Pouch lost";
                    if (!rule.isLocked())
                    {
                        if (rule.getReplacementItems().isEmpty())
                        {
                            long price = price(id);
                            known &= price >= 0;
                            lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, price), exposed));
                        }
                        permanent = rule.isPermanentLoss();
                    }
                    break;
                case CONVERT:
                    outcome = "Converted / components lost";
                    permanent = rule.isPermanentLoss();
                    break;
                case ALWAYS_LOST:
                    outcome = "Always lost";
                    permanent = rule.isPermanentLoss();
                    // Reviewed replacement components already price the item itself. A looting
                    // bag has no gp reclaim fee; other containers still need their own valuation.
                    if (rule.getReplacementItems().isEmpty() && !"LOOTING_BAG".equals(rule.getContentsType()))
                    {
                        long price = price(id);
                        known &= price >= 0;
                        lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, price), exposed));
                    }
                    break;
                case DROP:
                    long price = price(id);
                    known &= price >= 0;
                    lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, price), exposed));
                    break;
                default:
                    outcome = "Unknown death rule";
                    known = false;
                    long estimate = price(id);
                    lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, estimate), exposed));
            }
            if (!rule.getReplacementItems().isEmpty())
            {
                long components = componentValue(rule.getReplacementItems());
                known &= components >= 0;
                lost = saturatedAdd(lost, saturatedMultiply(Math.max(0, components), exposed));
            }
            if (repair > 0 && !(rule.getKind() == DeathRule.Kind.LOCKABLE && aboveTwenty()))
            {
                long components = componentValue(rule.getRepairCostItems());
                known &= components >= 0;
                repair = saturatedAdd(repair, saturatedMultiply(Math.max(0, components), exposed));
            }
        }
        if (exposed == 0 && (lost > 0 || rule.isContentsLost()))
        {
            outcome = "Protected item; additional losses";
        }
        if (kept > 0 && exposed > 0) { detail = kept + " protected; " + exposed + " exposed. " + detail; }
        if (!known) { warnings.add(itemName(id) + ": loss estimate is incomplete."); }
        return new ItemLoss(id, itemName(id), quantity, kept, protectionValue(id), outcome,
            lost, repair, permanent, known, detail.trim());
    }

    private void addContents(Map<Integer, Integer> items, boolean actual, Map<Integer, Integer> plannedPouch,
        boolean plannedEmptyBag, List<ItemLoss> losses, Set<String> warnings)
    {
        boolean pouch = items.keySet().stream().anyMatch(id -> rule(id).getKind() == DeathRule.Kind.POUCH);
        boolean bag = items.keySet().stream().anyMatch(id -> "LOOTING_BAG".equals(rule(id).getContentsType()));
        boolean quiver = items.keySet().stream().anyMatch(id -> "QUIVER".equals(rule(id).getContentsType()));
        for (int id : items.keySet())
        {
            DeathRule rule = rule(id);
            if (rule.isContentsLost() && (rule.getContentsType() == null || rule.getContentsType().isEmpty()))
            {
                warnings.add(itemName(id) + ": contents or charges can be lost independently of item protection and are not fully observed.");
            }
        }
        DeathContext context = player.getDeathContext();
        if (quiver)
        {
            if (context.isQuiverContentsKnown())
            {
                contents(context.getQuiverContents(), "Quiver", losses, warnings);
            }
            warnings.add("Quiver ammunition protection is not verified; any observed ammunition is shown as exposed. Hidden ammunition or sunfire charges may add to this estimate.");
        }
        if (!actual && plannedPouch != null && !plannedPouch.isEmpty())
        {
            if (!pouch)
            {
                warnings.add("The rune pouch configuration has no physical pouch in the plan.");
            }
            plannedPouch.forEach((id, quantity) ->
            {
                long required = (long) quantity + items.getOrDefault(id, 0);
                if (required > player.getOwned().getOrDefault(id, 0))
                {
                    warnings.add("Rune pouch preparation needs " + required + " " + itemName(id)
                        + " including any loose runes; observed usable stock is insufficient.");
                }
            });
            contents(plannedPouch, "Planned rune pouch", losses, warnings);
        }
        else if (pouch)
        {
            boolean carriedPouch = player.getRiskCarried().keySet().stream()
                .anyMatch(id -> rule(id).getKind() == DeathRule.Kind.POUCH && items.containsKey(id));
            if (context.isPouchContentsKnown() && (actual || carriedPouch))
            {
                contents(context.getPouchContents(), "Rune pouch", losses, warnings);
            }
            else { warnings.add("Rune pouch contents are unverified; runes are not protected by its lock."); }
        }
        if (bag && (actual || !plannedEmptyBag))
        {
            // Only an explicit planned-empty target can replace observed contents. The actual
            // carried assessment and legacy map-only comparisons retain their known/unknown state.
            if (context.isLootingBagContentsKnown())
            {
                contents(context.getLootingBagContents(), "Looting bag", losses, warnings);
            }
            else { warnings.add("Looting bag contents are unverified and are outside normal item protection."); }
        }
    }

    private boolean usesPlannedEther(Map<Integer, Integer> items)
    {
        return plannedEtherCharges > 0 && applies() && items.entrySet().stream()
            .anyMatch(entry -> entry.getValue() != null && entry.getValue() > 0
                && "ETHER_WEAPON".equals(rule(entry.getKey()).getContentsType()));
    }

    private void checkEtherResources(Map<Integer, Integer> items, Set<String> warnings)
    {
        long target = 0;
        for (Map.Entry<Integer, Integer> entry : items.entrySet())
        {
            if (entry.getValue() != null && entry.getValue() > 0
                && "ETHER_WEAPON".equals(rule(entry.getKey()).getContentsType()))
            {
                com.danieljglover.allinslayer.model.advisor.ChargeObservation observed = player.getPreparation()
                    .getCharges().get(entry.getKey());
                long required = saturatedMultiply(entry.getValue(), plannedEtherCharges);
                // One observation belongs to one uniquely carried item, never every banked copy.
                if (observed != null && observed.isObserved() && observed.getCharges() >= 0)
                {
                    required -= Math.min(plannedEtherCharges, observed.getCharges());
                }
                target = saturatedAdd(target, required);
            }
        }
        long packed = Math.max(0, items.getOrDefault(REVENANT_ETHER, 0));
        long required = saturatedAdd(target, packed);
        long owned = Math.max(0, player.getOwned().getOrDefault(REVENANT_ETHER, 0));
        if (owned < required)
        {
            warnings.add("Ether preparation needs " + target + " loose ether for weapon charges"
                + (packed > 0 ? " plus " + packed + " packed separately" : "")
                + "; only " + owned + " loose ether is observed. Unverified loaded charges are not counted as preparation resources.");
        }
    }

    private void contents(Map<Integer, Integer> items, String container, List<ItemLoss> losses, Set<String> warnings)
    {
        items.forEach((id, quantity) -> {
            long price = price(id);
            boolean known = price >= 0;
            if (!known) { warnings.add(container + ": value unavailable for " + itemName(id) + "."); }
            losses.add(new ItemLoss(id, itemName(id), quantity, 0, 0, "Contents lost",
                saturatedMultiply(Math.max(0, price), quantity), 0, false, known,
                container + ": contents do not use protected slots."));
        });
    }

    public long protectionValue(int id)
    {
        DeathRule rule = catalogue.getDeathRules().get(id);
        if (rule != null && rule.getProtectionValue() >= 0) { return rule.getProtectionValue(); }
        ItemValue value = player.getItemValues().get(id);
        return value == null ? -1 : value.getProtectionValue();
    }

    public long price(int id)
    {
        ItemValue value = player.getItemValues().get(id);
        return value == null ? -1 : value.getMarketPrice();
    }

    private long componentValue(Map<Integer, Integer> components)
    {
        long total = 0;
        for (Map.Entry<Integer, Integer> component : components.entrySet())
        {
            long value = price(component.getKey());
            if (value < 0) { return -1; }
            total = saturatedAdd(total, saturatedMultiply(value, component.getValue()));
        }
        return total;
    }

    private DeathRule rule(int id)
    {
        DeathRule rule = catalogue.getDeathRules().get(id);
        if (rule != null) { return rule; }
        ItemValue value = player.getItemValues().get(id);
        DeathRule fallback = new DeathRule();
        fallback.setKind(value != null && value.isTradeable() ? DeathRule.Kind.DROP : DeathRule.Kind.UNKNOWN);
        return fallback;
    }

    private boolean aboveTwenty() { return area == null || area.getMaxLevel() < 0 || area.getMaxLevel() > 20; }

    private String itemName(int id)
    {
        ItemValue value = player.getItemValues().get(id);
        return value == null ? "Item " + id : value.getName();
    }

    public static Map<Integer, Integer> quantities(Map<String, Choice> equipment, List<Choice> inventory)
    {
        Map<Integer, Integer> result = new LinkedHashMap<>();
        List<Choice> all = new ArrayList<>(equipment.values());
        all.addAll(inventory);
        for (Choice choice : all)
        {
            if (!"RUNE POUCH".equals(choice.getSlot()) && choice.getItemId() > 0 && choice.getQuantity() > 0)
            {
                result.merge(choice.getItemId(), choice.getQuantity(), (a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
            }
        }
        return result;
    }

    private static Map<Integer, Integer> plannedPouchContents(List<Choice> inventory)
    {
        Map<Integer, Integer> result = new LinkedHashMap<>();
        for (Choice choice : inventory)
        {
            if ("RUNE POUCH".equals(choice.getSlot()) && choice.getItemId() > 0 && choice.getQuantity() > 0)
            {
                result.merge(choice.getItemId(), choice.getQuantity(),
                    (a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b));
            }
        }
        return result;
    }

    private boolean plansEmptyBag(List<Choice> inventory)
    {
        return inventory.stream().anyMatch(choice -> "LOOTING BAG".equals(choice.getSlot())
            && choice.getQuantity() > 0 && "LOOTING_BAG".equals(rule(choice.getItemId()).getContentsType()));
    }
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.ItemStats;
import java.util.Locale;

/** Static ammunition rules, checked against the Wiki ammunition and weapon tables. */
final class EquipmentCompatibility
{
	private EquipmentCompatibility()
	{
	}

	static boolean needsAmmo(ItemStats weapon)
	{
		if (weapon == null)
		{
			return false;
		}
		String name = lower(weapon.getName());
		return !selfSupplied(name) && (name.contains("bow") || name.contains("ballista")
			|| name.contains("atlatl") || name.contains("salamander") || name.contains("swamp lizard")
			|| name.contains("seercull"));
	}

	static boolean compatible(ItemStats weapon, ItemStats ammo)
	{
		if (ammo == null)
		{
			return !needsAmmo(weapon);
		}
		String ammunition = lower(ammo.getName());
		if (weapon == null || !needsAmmo(weapon))
		{
			return ammunition.contains("blessing");
		}
		String name = lower(weapon.getName());
		if (name.contains("karil"))
		{
			return ammunition.contains("bolt rack");
		}
		if (name.contains("sunlight crossbow"))
		{
			return ammunition.contains("antler bolt");
		}
		if (name.contains("hunters'") || name.contains("hunter's"))
		{
			return ammunition.contains("kebbit bolt");
		}
		if (name.contains("crossbow"))
		{
			if (name.equals("crossbow") || name.contains("phoenix"))
			{
				return ammunition.contains("bronze bolt") && !ammunition.contains("unf");
			}
			if (name.contains("dorgeshuun") && ammunition.contains("bone bolt"))
			{
				return true;
			}
			int tier = boltTier(ammunition);
			return tier > 0 && tier <= crossbowTier(name)
				&& !(name.contains("dorgeshuun") && ammunition.contains("silver"));
		}
		if (name.contains("ballista"))
		{
			return ammunition.contains("javelin") && !ammunition.contains("morrigan");
		}
		if (name.contains("atlatl"))
		{
			return ammunition.contains("atlatl dart");
		}
		if (name.contains("swamp lizard"))
		{
			return ammunition.equals("guam tar");
		}
		if (name.contains("salamander"))
		{
			return name.contains("orange") && ammunition.equals("marrentill tar")
				|| name.contains("red") && ammunition.equals("tarromin tar")
				|| name.contains("black") && ammunition.equals("harralander tar")
				|| name.contains("tecu") && ammunition.equals("irit tar");
		}
		if (name.contains("training bow"))
		{
			return ammunition.contains("training arrow");
		}
		if (name.contains("ogre bow"))
		{
			if (ammunition.contains("ogre arrow"))
			{
				return true;
			}
			return ammunition.contains("brutal") && (name.contains("comp")
				|| materialTier(ammunition) <= 4 && materialTier(ammunition) > 0);
		}
		int tier = arrowTier(ammunition);
		return tier > 0 && tier <= bowTier(name);
	}

	static boolean chargeBearing(ItemStats weapon)
	{
		if (weapon == null)
		{
			return false;
		}
		String name = lower(weapon.getName());
		return selfSupplied(name) || name.contains("trident") || name.contains("sanguinesti")
			|| name.contains("tumeken") || name.contains("sceptre") || name.contains("warped sceptre")
			|| name.contains("arclight") || name.contains("scythe") || name.contains("venator")
			|| name.contains("chainmace");
	}

	private static boolean selfSupplied(String name)
	{
		return name.contains("crystal bow") || name.contains("faerdhinen")
			|| name.contains("craw's bow") || name.contains("webweaver") || name.contains("starter bow")
			|| name.contains("blowpipe");
	}

	private static int crossbowTier(String name)
	{
		if (name.contains("dragon") || name.contains("armadyl") || name.contains("zaryte"))
		{
			return 8;
		}
		if (name.contains("rune"))
		{
			return 7;
		}
		if (name.contains("dorgeshuun"))
		{
			return 3;
		}
		if (name.contains("blurite"))
		{
			return 2;
		}
		if (name.contains("adamant"))
		{
			return 6;
		}
		if (name.contains("mithril"))
		{
			return 5;
		}
		if (name.contains("steel"))
		{
			return 4;
		}
		if (name.contains("iron"))
		{
			return 3;
		}
		return name.equals("crossbow") || name.contains("phoenix") || name.contains("bronze") ? 1 : 0;
	}

	private static int boltTier(String name)
	{
		if (!name.contains("bolt") || name.contains("unfinished") || name.contains("unf")
			|| name.contains("tips") || name.contains("antler") || name.contains("kebbit"))
		{
			return 0;
		}
		if (name.contains("dragon bolts"))
		{
			return 8;
		}
		if (name.contains("runite") || name.contains("dragonstone") || name.contains("onyx")
			|| name.contains("broad"))
		{
			return 7;
		}
		if (name.contains("adamant") || name.contains("ruby") || name.contains("diamond"))
		{
			return 6;
		}
		if (name.contains("mithril") || name.contains("sapphire") || name.contains("emerald"))
		{
			return 5;
		}
		if (name.contains("steel") || name.contains("topaz"))
		{
			return 4;
		}
		if (name.contains("iron") || name.contains("pearl") || name.contains("silver"))
		{
			return 3;
		}
		if (name.contains("blurite") || name.contains("jade"))
		{
			return 2;
		}
		return name.contains("bronze") || name.contains("opal") ? 1 : 0;
	}

	private static int bowTier(String name)
	{
		if (name.contains("dark bow") || name.contains("twisted") || name.contains("3rd age")
			|| name.contains("venator") || name.contains("scorching"))
		{
			return 8;
		}
		if (name.contains("magic") || name.contains("seercull") || name.contains("bone shortbow"))
		{
			return 7;
		}
		if (name.contains("yew"))
		{
			return 6;
		}
		if (name.contains("maple"))
		{
			return 5;
		}
		if (name.contains("willow"))
		{
			return 4;
		}
		if (name.contains("oak"))
		{
			return 3;
		}
		return name.equals("shortbow") || name.equals("longbow") || name.equals("rain bow")
			|| name.contains("cursed goblin") ? 2 : 0;
	}

	private static int arrowTier(String name)
	{
		if (!name.contains("arrow") || name.contains("head") || name.contains("shaft")
			|| name.contains("fire") || name.contains("training") || name.contains("ogre"))
		{
			return 0;
		}
		if (name.contains("broad"))
		{
			return 7;
		}
		if (name.contains("ice arrow"))
		{
			return 6;
		}
		return materialTier(name);
	}

	private static int materialTier(String name)
	{
		String[] materials = {"bronze", "iron", "steel", "mithril", "adamant", "rune", "amethyst", "dragon"};
		for (int index = materials.length - 1; index >= 0; index--)
		{
			if (name.contains(materials[index]))
			{
				return index + 1;
			}
		}
		return 0;
	}

	private static String lower(String value)
	{
		return value.toLowerCase(Locale.ROOT);
	}
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.Spellbook;
import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Choice;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Method;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Supply;
import com.danieljglover.allinslayer.model.advisor.TripPreparationData;
import com.danieljglover.allinslayer.model.advisor.TripPreparationData.Spell;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import lombok.Value;

/** Resolves bundled spell guidance into preparations without changing client spell or item state. */
public final class SpellPlanner
{
    private static final Pattern SPACE = Pattern.compile("\\s+");
    private static volatile SpellIndex cachedIndex;
    private final TripPreparationData data;
    private final RecommendationRequest request;
    private final RequirementEvaluator requirements;
    private final SpellIndex index;
    private final Map<String, String> requirementFailures = new LinkedHashMap<>();

    public SpellPlanner(TripPreparationData data, RecommendationRequest request)
    {
        this.data = data;
        this.request = request;
        this.requirements = new RequirementEvaluator(request);
        this.index = index(data);
    }

    @Value
    public static class CastingPlan
    {
        boolean managed;
        List<Supply> supplies;
        List<String> blockers;
        List<String> notes;

        private CastingPlan(boolean managed, List<Supply> supplies, List<String> blockers, List<String> notes)
        {
            this.managed = managed;
            this.supplies = Collections.unmodifiableList(new ArrayList<>(supplies));
            this.blockers = Collections.unmodifiableList(new ArrayList<>(blockers));
            this.notes = Collections.unmodifiableList(new ArrayList<>(notes));
        }
    }

    public CastingPlan plan(Method method, Map<String, Choice> equipment, boolean allowBlighted)
    {
        List<Supply> supplies = new ArrayList<>();
        List<String> blockers = new ArrayList<>();
        List<String> notes = new ArrayList<>();
        Set<Spell> selected = new LinkedHashSet<>();
        String title = normal(method.getId() + " " + method.getName());
        String guidance = normal(method.getSummary() + " " + String.join(" ", method.getGuidance()));
        String documented = title + " " + guidance + " " + normal(String.join(" ", method.getRequirements()));
        boolean magic = "MAGIC".equalsIgnoreCase(method.getStyle());
        boolean freezeRequired = method.getRequirements().stream().anyMatch(SpellPlanner::freezeRequirement);
        List<Spell> named = namedSpells(title).stream().filter(Spell::isOffensive).collect(Collectors.toList());
        Spell primary = named.isEmpty() ? null : named.get(0);
        if (primary == null)
        {
            // Keep the authored baseline unless the method explicitly offers area-spell alternatives.
            for (String line : method.getGuidance())
            {
                if (line.startsWith("Spell preparation baseline:"))
                {
                    List<Spell> baseline = namedSpells(normal(line.split(";", 2)[0]));
                    if (!baseline.isEmpty()) { primary = baseline.get(0); break; }
                }
            }
        }
        Choice weapon = equipment.get("WEAPON");
        String powered = weapon == null ? null : data.getPoweredWeapons().get(weapon.getItemId());
        if (primary == null)
        {
            for (String line : method.getRequirements())
            {
                String text = normal(line);
                if (optional(text)) { continue; }
                List<Spell> fixed = namedSpells(text).stream().filter(Spell::isOffensive)
                    .filter(s -> explicitCastingRequirement(text, s)).collect(Collectors.toList());
                if (!fixed.isEmpty())
                {
                    primary = fixed.size() > 1 && (text.contains(" or ") || text.contains(" / "))
                        ? fixed.stream().filter(s -> problems(s, equipment).isEmpty()).findFirst().orElse(fixed.get(0))
                        : fixed.get(0);
                    break;
                }
            }
        }
        Spell areaAlternative = fundedAreaAlternative(method, title, named, primary, equipment, allowBlighted);
        if (areaAlternative != null)
        {
            primary = areaAlternative;
            notes.add("Selected " + primary.getName() + " from the guide's burst/barrage alternatives: "
                + "the highest Magic level currently usable and funded for " + data.getCombatCasts() + " casts.");
        }
        if (primary != null) { selected.add(primary); }
        else if (magic && powered != null)
        {
            checkCharges(blockers, weapon, powered);
            notes.add("Use " + weapon.getName() + "'s built-in attack. Confirm at least "
                + data.getCombatCasts() + " loaded charges; loose runes are not loaded charges.");
        }
        else if (magic)
        {
            primary = compatibleDefault(method, equipment, documented, allowBlighted);
            if (primary == null)
            {
                blockers.add("No verified offensive spell is usable with the current Magic level, spellbook and required weapon.");
            }
            else
            {
                selected.add(primary);
                notes.add("Spell planning assumption: " + primary.getName()
                    + ". The guide does not fix a single spell; this is a compatible preparation, not a measured damage ranking.");
            }
        }

        // Exact requirements are stronger than incidental mentions of optional guide alternatives.
        for (String line : method.getRequirements())
        {
            String text = normal(line);
            if (optional(text)) { continue; }
            List<Spell> required = namedSpells(text).stream()
                .filter(s -> !s.isOffensive() || powered == null || explicitCastingRequirement(text, s))
                .collect(Collectors.toList());
            if (required.size() > 1 && (text.contains(" or ") || text.contains(" / ")))
            {
                selected.add(required.stream().filter(s -> problems(s, equipment).isEmpty())
                    .findFirst().orElse(required.get(0)));
            }
            else { selected.addAll(required); }
        }
        for (String line : method.getGuidance())
        {
            String text = normal(line);
            if (text.startsWith("spell preparation baseline") || optional(text)) { continue; }
            for (Spell spell : namedSpells(text))
            {
                if (!spell.isOffensive() && !"PVP_ONLY".equals(spell.getFamily())
                    && (text.contains("required") || text.contains("must ") || text.contains("cast ")
                        || text.contains("use ") || "Mark of Darkness".equals(spell.getName())))
                {
                    selected.add(spell);
                }
            }
        }
        // A powered/ranged freeze method still needs its documented binding spell, independently
        // of the damage weapon. An explicit named spell above retains its exact requirements.
        boolean hasFreeze = selected.stream().anyMatch(s -> "ICE".equals(s.getFamily()) || "BIND".equals(s.getFamily()));
        if (!hasFreeze && (freezeRequired || primary == null && (documented.contains("freez") || documented.contains("entangle"))))
        {
            List<Spell> freezes = namedSpells(documented).stream()
                .filter(s -> "ICE".equals(s.getFamily()) || "BIND".equals(s.getFamily()))
                .sorted(Comparator.comparingInt(Spell::getMagicLevel).reversed()).collect(Collectors.toList());
            Spell freeze = freezes.stream().filter(s -> problems(s, equipment).isEmpty()).findFirst().orElse(null);
            if (freeze == null && freezeRequired)
            {
                freeze = data.getSpells().values().stream()
                    .filter(s -> "ICE".equals(s.getFamily()) || "BIND".equals(s.getFamily()))
                    .filter(s -> problems(s, equipment).isEmpty())
                    .max(Comparator.comparingInt(Spell::getMagicLevel)).orElse(null);
            }
            if (freeze != null) { selected.add(freeze); }
            else if (!freezes.isEmpty()) { selected.add(freezes.get(0)); }
            else if (freezeRequired) { blockers.add("No verified freezing or binding spell is usable with the current Magic level and spellbook."); }
        }
        boolean managed = magic || freezeRequired || !selected.isEmpty();
        Map<Integer, Integer> remaining = new LinkedHashMap<>(request.getPlayer().getOwned());
        for (Spell spell : selected)
        {
            List<String> issues = problems(spell, equipment);
            if (!issues.isEmpty()) { blockers.addAll(issues); continue; }
            if ("IBAN".equals(spell.getFamily()) && weapon != null)
            {
                if (weapon.getItemId() == 1409 && data.getCombatCasts() > 120)
                {
                    blockers.add("Iban's regular staff holds 120 NPC casts; the " + data.getCombatCasts()
                        + "-cast target requires an upgraded staff or a smaller target.");
                    continue;
                }
                String chargeCheck = "Iban's staff charges prepared for this trip";
                checkCharges(blockers, weapon, chargeCheck);
            }
            if ("SLAYER_DART".equals(spell.getFamily()) && weapon != null && weapon.getItemId() == 21255)
            {
                String chargeCheck = "Slayer's staff enchantment charges prepared for this trip";
                checkCharges(blockers, weapon, chargeCheck);
            }
            List<Supply> next = suppliesFor(spell, data.getCombatCasts(), equipment, allowBlighted, remaining);
            supplies.addAll(next);
            for (Supply supply : next)
            {
                remaining.computeIfPresent(supply.getItemIds().get(0), (id, quantity) -> Math.max(0, quantity - supply.getQuantity()));
            }
            notes.add("Pack up to " + data.getCombatCasts() + " casts of " + spell.getName()
                + (spell.isOffensive() ? "." : " as a conservative support-spell allowance.")
                + " Rune-saving chance is not assumed.");
        }
        if (managed)
        {
            notes.add("Spellbook and requirements use current account state. Rune pouch packing, loading charges and choosing autocast/manual casting are preparation steps; this plugin does not perform them.");
        }
        return new CastingPlan(managed, aggregate(supplies), distinct(blockers), notes);
    }

    public List<String> problems(Spell spell, Map<String, Choice> equipment)
    {
        List<String> result = new ArrayList<>();
        if (spell == null) { return Collections.singletonList("Spell has no reviewed preparation data."); }
        String magic = "Magic " + spell.getMagicLevel();
        addFailure(result, magic);
        try
        {
            Spellbook required = Spellbook.valueOf(spell.getSpellbook().toUpperCase(Locale.ROOT));
            addFailure(result, required.getDisplayName() + " spellbook selected");
        }
        catch (IllegalArgumentException ex) { result.add("Spellbook is unverified for " + spell.getName() + "."); }
        for (String requirement : spell.getRequirements())
        {
            addFailure(result, requirement);
        }
        if (!spell.getWeaponIds().isEmpty())
        {
            Choice weapon = equipment.get("WEAPON");
            if (weapon == null || weapon.getMissing() > 0 || !spell.getWeaponIds().contains(weapon.getItemId()))
            {
                result.add(spell.getName() + " requires a compatible equipped casting weapon.");
            }
        }
        return distinct(result);
    }

    public List<Supply> suppliesFor(Spell spell, int casts, Map<String, Choice> equipment, boolean allowBlighted)
    {
        return suppliesFor(spell, casts, equipment, allowBlighted, request.getPlayer().getOwned());
    }

    public List<Supply> suppliesFor(Spell spell, int casts, Map<String, Choice> equipment, boolean allowBlighted,
        Map<Integer, Integer> available)
    {
        if (casts <= 0 || !problems(spell, equipment).isEmpty()) { return Collections.emptyList(); }
        if (allowBlighted && spell.getSackItemId() > 0
            && available.getOrDefault(spell.getSackItemId(), 0) >= casts)
        {
            return Collections.singletonList(supply(spell.getSackItemId(), sackName(spell.getSackItemId()), casts));
        }
        Map<String, Integer> perCast = new LinkedHashMap<>(spell.getRunes());
        for (Choice choice : equipment.values())
        {
            if (choice.getMissing() == 0 && choice.getQuantity() > 0)
            {
                for (String rune : data.getInfiniteRunes().getOrDefault(choice.getItemId(), Collections.emptyList()))
                {
                    perCast.remove(rune);
                }
            }
        }
        List<Supply> supplies = new ArrayList<>();
        // A combination rune can supply both components of the SAME cast. Work per cast, then
        // multiply, so Blood/Ice or offence/teleport demand cannot spend the same unit twice.
        while (true)
        {
            Integer selected = null;
            int selectedQuantity = 0;
            for (Map.Entry<Integer, List<String>> combo : data.getCombinationRunes().entrySet())
            {
                if (combo.getValue().size() != 2 || !perCast.keySet().containsAll(combo.getValue())) { continue; }
                int quantity = multiply(Math.max(perCast.get(combo.getValue().get(0)), perCast.get(combo.getValue().get(1))), casts);
                if (available.getOrDefault(combo.getKey(), 0) < quantity) { continue; }
                if (selected == null || quantity < selectedQuantity)
                {
                    selected = combo.getKey(); selectedQuantity = quantity;
                }
            }
            if (selected == null) { break; }
            supplies.add(supply(selected, runeName(selected), selectedQuantity));
            data.getCombinationRunes().get(selected).forEach(perCast::remove);
        }
        perCast.forEach((name, quantity) ->
        {
            Integer itemId = data.getRuneIds().get(name);
            int total = multiply(quantity, casts);
            if (itemId != null)
            {
                // A one-component substitution does not save a slot, but can fund a spell
                // when the owned stock contains combination runes instead of the basic rune.
                if (available.getOrDefault(itemId, 0) < total)
                {
                    for (Map.Entry<Integer, List<String>> combo : data.getCombinationRunes().entrySet())
                    {
                        int reserved = supplies.stream().filter(s -> s.getItemIds().contains(combo.getKey()))
                            .mapToInt(Supply::getQuantity).sum();
                        if (combo.getValue().contains(name)
                            && (long) available.getOrDefault(combo.getKey(), 0) - reserved >= total)
                        {
                            supplies.add(supply(combo.getKey(), runeName(combo.getKey()), total));
                            return;
                        }
                    }
                }
                supplies.add(supply(itemId, name, total));
            }
        });
        return aggregate(supplies);
    }

    private Spell compatibleDefault(Method method, Map<String, Choice> equipment, String documented, boolean allowBlighted)
    {
        Set<String> families = new LinkedHashSet<>();
        for (String family : new String[] {"WIND", "WATER", "EARTH", "FIRE", "ICE", "BLOOD", "SMOKE", "SHADOW", "DEMONBANE", "GRASP"})
        {
            if (Pattern.compile("\\b" + family.toLowerCase(Locale.ROOT) + "\\s+(?:spells?|magic|barrage|burst|surge|wave|blitz|rush)\\b").matcher(documented).find()
                || family.equals("DEMONBANE") && documented.contains("demonbane")) { families.add(family); }
        }
        Spellbook book = request.getPlayer().getSpellbook();
        if (families.isEmpty())
        {
            if (book == Spellbook.STANDARD) { families.addAll(java.util.Arrays.asList("WIND", "WATER", "EARTH", "FIRE")); }
            else if (book == Spellbook.ANCIENT) { families.add("ICE"); }
            else if (book == Spellbook.ARCEUUS) { families.add("GRASP"); }
        }
        List<Spell> candidates = data.getSpells().values().stream().filter(Spell::isOffensive)
            .filter(s -> families.contains(s.getFamily()))
            .filter(s -> !"ANCIENT".equals(s.getSpellbook()) || method.isBarrage()
                || !s.getName().endsWith("Barrage") && !s.getName().endsWith("Burst"))
            .filter(s -> problems(s, equipment).isEmpty())
            .sorted(Comparator.comparingInt(Spell::getMagicLevel).reversed()).collect(Collectors.toList());
        return candidates.stream().filter(s -> suppliesFor(s, data.getCombatCasts(), equipment, allowBlighted).stream()
                .allMatch(supply -> request.getPlayer().getOwned().getOrDefault(supply.getItemIds().get(0), 0) >= supply.getQuantity()))
            .findFirst().orElse(candidates.isEmpty() ? null : candidates.get(0));
    }

    private Spell fundedAreaAlternative(Method method, String title, List<Spell> named, Spell baseline,
        Map<String, Choice> equipment, boolean allowBlighted)
    {
        if (!"MAGIC".equalsIgnoreCase(method.getStyle()) || baseline == null
            || !title.contains("burst") || !title.contains("barrage") || named.size() == 1)
        {
            return null;
        }
        // A fixed spell requirement remains binding, even if another section mentions alternatives.
        if (method.getRequirements().stream().filter(line -> !optional(normal(line)))
            .anyMatch(line -> namedSpells(normal(line)).stream().anyMatch(Spell::isOffensive)))
        {
            return null;
        }
        return data.getSpells().values().stream()
            .filter(Spell::isOffensive)
            .filter(spell -> "ANCIENT".equals(spell.getSpellbook()))
            .filter(spell -> spell.getName().endsWith("Burst") || spell.getName().endsWith("Barrage"))
            .filter(spell -> named.isEmpty() ? baseline.getFamily().equals(spell.getFamily()) : named.contains(spell))
            .filter(spell -> problems(spell, equipment).isEmpty())
            .sorted(Comparator.comparingInt(Spell::getMagicLevel).reversed())
            .filter(spell -> suppliesFor(spell, data.getCombatCasts(), equipment, allowBlighted).stream()
                .allMatch(supply -> request.getPlayer().getOwned().getOrDefault(supply.getItemIds().get(0), 0)
                    >= supply.getQuantity()))
            .findFirst().orElse(null);
    }

    private List<Spell> namedSpells(String text)
    {
        List<Spell> result = new ArrayList<>();
        for (IndexedSpell indexed : index.spells)
        {
            Spell spell = indexed.spell;
            String name = indexed.name;
            if (!text.contains(name)) { continue; }
            if ("charge".equals(name) && !text.contains("charge spell") && !text.equals("charge")) { continue; }
            Matcher matcher = indexed.pattern.matcher(text);
            if (matcher.find()) { result.add(spell); }
        }
        result.sort(Comparator.comparingInt(s -> text.indexOf(normal(s.getName()))));
        return result;
    }

    private static String normal(String value)
    {
        return value == null ? "" : SPACE.matcher(value.toLowerCase(Locale.ROOT).replace('-', ' ').replace('_', ' ')).replaceAll(" ").trim();
    }

    private static boolean optional(String text)
    {
        return text.contains("optional") || text.contains("consider ") || text.contains("may ")
            || text.contains("can ") || text.contains("alternatively") || text.contains("for example");
    }

    private static boolean explicitCastingRequirement(String text, Spell spell)
    {
        String name = normal(spell.getName());
        return text.equals(name) || text.startsWith(name + " selected") || text.startsWith(name + " required")
            || text.startsWith("cast " + name) || text.startsWith("casting " + name)
            || text.equals("arceuus spellbook with dark demonbane and mark of darkness selected");
    }

    private void checkCharges(List<String> blockers, Choice weapon, String requirement)
    {
        com.danieljglover.allinslayer.model.advisor.ChargeObservation observed = request.getPlayer()
            .getPreparation().getCharges().get(weapon.getItemId());
        if (observed == null || !observed.isObserved())
        {
            addFailure(blockers, requirement + " (at least " + data.getCombatCasts() + " charges)");
        }
        else if (observed.getCharges() < data.getCombatCasts())
        {
            blockers.add(weapon.getName() + " has " + observed.getCharges() + " observed charges; needs at least "
                + data.getCombatCasts() + " for this trip.");
        }
    }

    private void addFailure(List<String> target, String requirement)
    {
        if (!requirementFailures.containsKey(requirement))
        {
            requirementFailures.put(requirement, requirements.failure(requirement));
        }
        String failure = requirementFailures.get(requirement);
        if (failure != null) { target.add(failure); }
    }

    /** These exact combined preparations are checked component-by-component by this planner. */
    public boolean managesRequirement(String requirement)
    {
        return freezeRequirement(requirement)
            || "Arceuus spellbook with Dark Demonbane and Mark of Darkness selected".equals(requirement)
            || "Magic Dart selected with sufficient mind and death runes".equals(requirement)
            || "Magic setup prepared: compatible spellbook and sufficient runes, or a charged powered staff".equals(requirement);
    }

    private static boolean freezeRequirement(String requirement)
    {
        return "Freeze spell and sufficient runes prepared for Callisto".equals(requirement)
            || "Freeze spell and sufficient runes prepared for Artio".equals(requirement)
            || "Guardian freeze spell and sufficient runes prepared for Scorpia".equals(requirement);
    }

    public boolean hasDocumentedBarrageSpell(Method method)
    {
        String source = normal(method.getId() + " " + method.getName());
        for (String line : method.getGuidance())
        {
            if (line.startsWith("Spell preparation baseline:")) { source += " " + normal(line.split(";", 2)[0]); }
        }
        return namedSpells(source).stream().anyMatch(s -> "ANCIENT".equals(s.getSpellbook())
            && (s.getName().endsWith("Barrage") || s.getName().endsWith("Burst")) && !s.getRunes().isEmpty());
    }

    private static SpellIndex index(TripPreparationData data)
    {
        SpellIndex existing = cachedIndex;
        if (existing != null && existing.data == data) { return existing; }
        synchronized (SpellPlanner.class)
        {
            if (cachedIndex == null || cachedIndex.data != data) { cachedIndex = new SpellIndex(data); }
            return cachedIndex;
        }
    }

    private static final class SpellIndex
    {
        private final TripPreparationData data;
        private final List<IndexedSpell> spells = new ArrayList<>();

        private SpellIndex(TripPreparationData data)
        {
            this.data = data;
            data.getSpells().values().forEach(spell -> spells.add(new IndexedSpell(spell)));
        }
    }

    private static final class IndexedSpell
    {
        private final Spell spell;
        private final String name;
        private final Pattern pattern;

        private IndexedSpell(Spell spell)
        {
            this.spell = spell;
            this.name = normal(spell.getName());
            this.pattern = Pattern.compile("(?<![a-z])" + Pattern.quote(name) + "(?![a-z])");
        }
    }

    private static int multiply(int quantity, int casts)
    {
        return (int) Math.min(Integer.MAX_VALUE, (long) quantity * casts);
    }

    private static Supply supply(int id, String name, int quantity)
    {
        Supply result = new Supply();
        result.setName(name); result.setItemIds(Collections.singletonList(id));
        result.setQuantity(quantity); result.setRequired(true); result.setStackable(true);
        return result;
    }

    private String runeName(int id)
    {
        return data.getRuneIds().entrySet().stream().filter(e -> e.getValue() == id)
            .map(Map.Entry::getKey).findFirst().orElse("Rune " + id);
    }

    private static String sackName(int id)
    {
        if (id == 24607) { return "Blighted ancient ice sack"; }
        if (id == 26705) { return "Blighted surge sack"; }
        if (id == 24613) { return "Blighted entangle sack"; }
        if (id == 24621) { return "Blighted vengeance sack"; }
        return "Spell sack " + id;
    }

    private static List<Supply> aggregate(List<Supply> input)
    {
        Map<Integer, Supply> result = new LinkedHashMap<>();
        for (Supply supply : input)
        {
            int id = supply.getItemIds().get(0);
            Supply previous = result.get(id);
            if (previous == null) { result.put(id, supply); }
            else { previous.setQuantity((int) Math.min(Integer.MAX_VALUE, (long) previous.getQuantity() + supply.getQuantity())); }
        }
        return new ArrayList<>(result.values());
    }

    private static List<String> distinct(List<String> input)
    {
        return new ArrayList<>(new LinkedHashSet<>(input));
    }
}

package com.danieljglover.allinslayer.loadout.advisor;

