import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/** Starts from Wiki priorities, then compares compatible head/amulet conditional bonuses. */
final class EquipmentPlanner
{
	static final List<String> SLOTS = Collections.unmodifiableList(Arrays.asList(
		"HEAD", "CAPE", "AMULET", "WEAPON", "BODY", "SHIELD", "LEGS", "HANDS", "FEET", "RING", "AMMO"));
	private static final List<String> SEARCH_ORDER = Arrays.asList(
		"WEAPON", "HEAD", "BODY", "LEGS", "SHIELD", "AMMO", "CAPE", "AMULET", "HANDS", "FEET", "RING");
	private static final List<String> RISK_SEARCH_ORDER = Arrays.asList(
		"HEAD", "BODY", "LEGS", "SHIELD", "AMMO", "CAPE", "AMULET", "HANDS", "FEET", "RING", "WEAPON");
	private static final int SEARCH_LIMIT = 25000;
	private final SlayerCatalogue catalogue;
	private final RecommendationRequest request;
	private final PlayerSnapshot player;
	private final RequirementEvaluator requirements;
	private final Method method;
	private final Location location;
	private final WildernessRiskCalculator riskCalculator;
	private final PreparationWork work;
	private final ConditionalBonuses bonuses;
	private final Map<String, List<Candidate>> domains = new LinkedHashMap<>();
	private final List<List<Integer>> mandatory = new ArrayList<>();
	private final List<Integer> primaryAmmo = new ArrayList<>();
	private final List<Supply> gearRequirements = new ArrayList<>();
	private final Map<Integer, List<String>> usability = new HashMap<>();
	private int visited;

	EquipmentPlanner(SlayerCatalogue catalogue, RecommendationRequest request, Task task,
		Monster monster, Location location, Method method)
	{
		this(catalogue, request, task, monster, location, method, new PreparationWork(() -> false));
	}

	EquipmentPlanner(SlayerCatalogue catalogue, RecommendationRequest request, Task task,
		Monster monster, Location location, Method method, PreparationWork work)
	{
		this.work = work;
		this.catalogue = catalogue;
		this.request = request;
		this.player = request.getPlayer();
		this.requirements = new RequirementEvaluator(request);
		this.method = method;
		this.location = location;
		this.riskCalculator = new WildernessRiskCalculator(catalogue, player, location, request.getPlannedEtherCharges());
		this.bonuses = new ConditionalBonuses(catalogue, request, task, monster, location, method);
	}

	Map<String, Choice> plan(List<Supply> required, List<String> blockers, List<String> explanations)
	{
		createDomains();
		for (Supply supply : required)
		{
			boolean ammunition = isAmmunition(supply);
			boolean protectiveGear = hasGearAlternative(supply);
			if (!supply.isRequired() || supply.getItemIds().isEmpty()
				|| !protectiveGear && !(ammunition && "RANGED".equalsIgnoreCase(method.getStyle())))
			{
				continue;
			}
			if (protectiveGear && hasOwnedInventoryAlternative(supply))
			{
				explanations.add(supply.getName()
					+ ": sufficient usable owned supplies can replace equipped protection; the inventory plan must include them when that protection is not equipped.");
				continue;
			}
			if (ammunition)
			{
				primaryAmmo.addAll(supply.getItemIds());
			}
			else
			{
				gearRequirements.add(supply);
			}
			List<Integer> usableIds = new ArrayList<>();
			for (Integer id : supply.getItemIds())
			{
				if (!isGearItem(id) && !(ammunition && "AMMO".equals(itemSlot(id))))
				{
					continue;
				}
				ItemStats stats = player.getItems().get(id);
				if (stats != null && usable(id) && owned(id))
				{
					boolean rejectedWikiOption = method.getEquipment().values().stream().flatMap(List::stream)
						.anyMatch(option -> option.getItemIds().contains(id))
						&& domains.values().stream().flatMap(List::stream)
							.noneMatch(candidate -> candidate.stats.getId() == id);
					if (rejectedWikiOption)
					{
						continue;
					}
					usableIds.add(id);
					addCandidate(stats.getSlot(), new Candidate(stats, "Required", null), true);
				}
			}
			if (usableIds.isEmpty())
			{
				blockers.add("Required equipment unavailable: " + supply.getName() + ".");
				addRelevantRequirements(supply.getItemIds().stream()
					.filter(id -> SLOTS.contains(itemSlot(id))).collect(Collectors.toList()), blockers);
			}
			else if (!ammunition)
			{
				mandatory.add(usableIds);
			}
		}
		// Empty slots are permitted, but never satisfy mandatory protective gear or a weapon.
		domains.values().forEach(options -> options.add(Candidate.EMPTY));
		Map<String, Candidate> selected = new LinkedHashMap<>();
		if (!search(0, selected))
		{
			blockers.add(visited >= SEARCH_LIMIT
				? "Could not verify a complete compatible loadout within the search limit; narrow the method or gear options."
				: "Owned equipment cannot satisfy all mandatory gear, companion, shield and ammunition constraints together.");
			selected.clear();
			for (String slot : SEARCH_ORDER)
			{
				Candidate candidate = domains.get(slot).get(0);
				if ("SHIELD".equals(slot) && stats(selected, "WEAPON") != null
					&& stats(selected, "WEAPON").isTwoHanded())
				{
					candidate = Candidate.EMPTY;
				}
				if ("AMMO".equals(slot))
				{
					candidate = domains.get(slot).stream().filter(c ->
						EquipmentCompatibility.compatible(stats(selected, "WEAPON"), c.stats))
						.findFirst().orElse(Candidate.EMPTY);
				}
				selected.put(slot, candidate);
			}
		}
		else
		{
			compareConditionalPairs(selected, explanations);
			if (riskCalculator.applies())
			{
				optimiseWilderness(selected, required, explanations);
			}
		}
		bonuses.explain(stats(selected, "HEAD"), stats(selected, "AMULET"), stats(selected, "WEAPON"), explanations);
		Map<String, Choice> result = new LinkedHashMap<>();
		for (String slot : SLOTS)
		{
			Candidate candidate = selected.getOrDefault(slot, Candidate.EMPTY);
			if (candidate.stats == null)
			{
				String reason = "Wilderness budget".equals(candidate.origin) ? "Empty - Wilderness budget"
					: "SHIELD".equals(slot) && stats(selected, "WEAPON") != null
					&& stats(selected, "WEAPON").isTwoHanded() ? "Empty - two-handed weapon" : "Empty";
				result.put(slot, new Choice(0, 0, 0, 0, 0, slot, reason, "Owned fallback", false));
				if ("WEAPON".equals(slot))
				{
					blockers.add("No owned usable weapon fits this method.");
				}
				else if ("Wilderness budget".equals(candidate.origin))
				{
					explanations.add(slot + ": left empty to meet the Wilderness loss budget; no mandatory protection is removed.");
				}
				else if (!"AMMO".equals(slot) && !"SHIELD".equals(slot))
				{
					explanations.add(slot + ": no owned usable option; left empty.");
				}
				addSlotRequirements(slot, explanations);
				continue;
			}
			ItemStats item = candidate.stats;
			int target = targetQuantity(slot, item, stats(selected, "WEAPON"), required);
			int carried = Math.min(target, player.getCarried().getOrDefault(item.getId(), 0));
			boolean requiredGear = gearRequirements.stream().anyMatch(s -> s.getItemIds().contains(item.getId()));
			result.put(slot, new Choice(item.getId(), target, carried, target - carried, 0,
				slot, item.getName(), candidate.origin, requiredGear || "WEAPON".equals(slot),
				"HEAD".equals(slot) ? headChoiceExplanation(selected) : ""));
			if (!"Wiki".equals(candidate.origin))
			{
				explanations.add(slot + ": " + item.getName() + " - " + candidate.origin
					+ ("Owned fallback".equals(candidate.origin)
						? "; highest compatible owned stat preference after Wiki options."
						: "Bonus comparison".equals(candidate.origin) ? "; selected with the amulet/head slot after applying eligible, non-stacking boosts."
						: "Wilderness budget".equals(candidate.origin) ? "; selected after assessing the full trip death risk."
						: "; earlier options were unavailable or incompatible."));
			}
			if (candidate.option != null && !candidate.option.getRequires().isEmpty())
			{
				explanations.add(item.getName() + ": required companion equipment is included in this setup.");
			}
		}
		ItemStats weapon = stats(selected, "WEAPON");
		if (!EquipmentCompatibility.compatible(weapon, stats(selected, "AMMO")))
		{
			blockers.add("No owned compatible ammunition is available for " + weapon.getName() + ".");
		}
		for (Supply supply : gearRequirements)
		{
			if (result.values().stream().noneMatch(c -> supply.getItemIds().contains(c.getItemId())))
			{
				add(blockers, "Must equip required protection or method item: " + supply.getName() + ".");
			}
		}
		if (EquipmentCompatibility.chargeBearing(weapon))
		{
			explanations.add("Check " + weapon.getName() + " charges and loaded ammunition before leaving; item ownership does not reveal internal charge quantities.");
		}
		if (!request.isActiveTask())
		{
			explanations.add("Catalogue on-task preview: eligible Slayer bonuses assume the selected task and target. Your detected assignment is unchanged.");
		}
		return result;
	}

	private String headChoiceExplanation(Map<String, Candidate> selected)
	{
		ItemStats head = stats(selected, "HEAD");
		ItemStats amulet = stats(selected, "AMULET");
		if (request.isTaskPreview() && bonuses.effect(head).isSlayer() && bonuses.applicable(head) > 1
			&& bonuses.applicable(amulet) <= 1)
		{
			return "On-task preview: this Slayer headgear's task boost is included for the selected monster. Your detected assignment is unchanged.";
		}
		boolean slayerAlternative = domains.get("HEAD").stream()
			.anyMatch(candidate -> bonuses.effect(candidate.stats).isSlayer() && bonuses.applicable(candidate.stats) > 1);
		if (slayerAlternative && !bonuses.effect(head).isSlayer() && bonuses.applicable(amulet) > 1)
		{
			return "Slayer headgear is still available. " + amulet.getName()
				+ " supplies this setup's undead boost; Slayer helmet and Black mask boosts do not stack with it. "
				+ "The head slot is compared using equipment stats and, in the Wilderness, loss constraints.";
		}
		return "";
	}


	private int targetQuantity(String slot, ItemStats item, ItemStats weapon, List<Supply> required)
	{
		int target = "AMMO".equals(slot) && EquipmentCompatibility.needsAmmo(weapon)
			|| "WEAPON".equals(slot) && item.isStackable()
			? Math.min(player.getOwned().getOrDefault(item.getId(), 0), 1000) : 1;
		if (item.isStackable())
		{
			int minimum = required.stream().filter(s -> s.isRequired() && s.getItemIds().contains(item.getId()))
				.mapToInt(Supply::getQuantity).max().orElse(1);
			target = Math.min(player.getOwned().getOrDefault(item.getId(), 0), Math.max(target, minimum));
		}
		return target;
	}

	private Map<String, Choice> previewChoices(Map<String, Candidate> selected, List<Supply> required)
	{
		Map<String, Choice> choices = new LinkedHashMap<>();
		selected.forEach((slot, candidate) -> {
			if (candidate.stats != null)
			{
				int id = candidate.stats.getId();
				int quantity = targetQuantity(slot, candidate.stats, stats(selected, "WEAPON"), required);
				int carried = Math.min(quantity, player.getCarried().getOrDefault(id, 0));
				choices.put(slot, new Choice(id, quantity, carried, quantity - carried, 0,
					slot, candidate.stats.getName(), candidate.origin, "WEAPON".equals(slot)));
			}
		});
		return choices;
	}

	private RiskPreference riskPreference(Map<String, Candidate> selected, List<Supply> required)
	{
		work.checkCancelled();
		Map<String, Choice> equipment = previewChoices(selected, required);
		List<String> inventoryProblems = new ArrayList<>();
		List<Choice> inventory = new SupplyPlanner(request, this, equipment).plan(method, location,
			required, equipment, inventoryProblems, new ArrayList<>());
		com.danieljglover.allinslayer.model.advisor.WildernessRisk.Scenario risk = riskCalculator.baseline(equipment, inventory);
		int unknown = (int) risk.getItems().stream().filter(item -> !item.isKnown()).count();
		if (!risk.isComplete()) { unknown++; }
		double preference = bonusScore(selected);
		for (Map.Entry<String, Candidate> entry : selected.entrySet())
		{
			// Wiki order remains the method's weapon/set preference; stats rank compatible downgrades.
			preference -= 8 * Math.max(0, domains.get(entry.getKey()).indexOf(entry.getValue()));
		}
		return new RiskPreference(inventoryProblems.size(), risk.getPermanentLosses(), unknown,
			Math.max(0, risk.getTotalRisk() - request.getWildernessRiskBudget()),
			weaponPreference(stats(selected, "WEAPON")), preference);
	}

	private int weaponPreference(ItemStats weapon)
	{
		List<ItemOption> options = method.getEquipment().getOrDefault("WEAPON", Collections.emptyList());
		for (int index = 0; index < options.size(); index++)
		{
			if (weapon != null && options.get(index).getItemIds().contains(weapon.getId())) { return index; }
		}
		return options.size();
	}

	private void optimiseWilderness(Map<String, Candidate> selected, List<Supply> required, List<String> explanations)
	{
		if (!work.spend())
		{
			explanations.add("The shared Wilderness comparison limit was reached. This setup's Wiki equipment is still assessed; select its monster/location to focus the alternative search.");
			return;
		}
		Map<String, Candidate> original = new LinkedHashMap<>(selected);
		RiskPreference best = riskPreference(selected, required);
		int evaluated = 0;
		// Bounded coordinate search includes supplies for each candidate. Only complete compatible
		// setups are compared, so a price improvement cannot remove mandatory protection or a set.
		for (int pass = 0; pass < 12 && evaluated < 600 && !work.exhausted(); pass++)
		{
			Map<String, Candidate> next = null;
			boolean changed = false;
			RiskPreference nextPreference = best;
			// Reduce supporting gear risk before replacing the method's preferred weapon.
			// Otherwise expensive armour can displace it from the protected item slots.
			for (String slot : RISK_SEARCH_ORDER)
			{
				Candidate previous = selected.get(slot);
				if (previous.option != null && !previous.option.getRequires().isEmpty()) { continue; }
				for (Candidate candidate : domains.get(slot))
				{
					if (candidate == previous || candidate.stats == null && "WEAPON".equals(slot)) { continue; }
					Map<String, Candidate> before = new LinkedHashMap<>(selected);
					selected.put(slot, candidate);
					if ("WEAPON".equals(slot))
					{
						if (candidate.stats.isTwoHanded()) { selected.put("SHIELD", Candidate.EMPTY); }
						if (!EquipmentCompatibility.compatible(candidate.stats, stats(selected, "AMMO")))
						{
							selected.put("AMMO", domains.get("AMMO").stream()
								.filter(ammo -> EquipmentCompatibility.compatible(candidate.stats, ammo.stats))
								.findFirst().orElse(Candidate.EMPTY));
						}
					}
					if (possible(selected) && work.spend())
					{
						RiskPreference preference = riskPreference(selected, required);
						evaluated++;
						if (preference.betterThan(nextPreference))
						{
							next = new LinkedHashMap<>(selected);
							nextPreference = preference;
						}
					}
					selected.clear();
					selected.putAll(before);
					if (evaluated >= 600 || work.exhausted()) { break; }
				}
				selected.put(slot, previous);
				if (next != null)
				{
					selected.clear();
					selected.putAll(next);
					best = nextPreference;
					changed = true;
					next = null;
				}
				if (evaluated >= 600 || work.exhausted()) { break; }
			}
			// Conditional bonus pairs may require changing both slots to reach an affordable setup.
			if (evaluated < 600 && !work.exhausted())
			{
				Candidate head = selected.get("HEAD");
				Candidate amulet = selected.get("AMULET");
				for (Candidate h : riskPairOptions("HEAD", head))
				{
					selected.put("HEAD", h);
					for (Candidate a : riskPairOptions("AMULET", amulet))
					{
						selected.put("AMULET", a);
						if (possible(selected) && work.spend())
						{
							RiskPreference preference = riskPreference(selected, required);
							evaluated++;
							if (preference.betterThan(nextPreference))
							{
								next = new LinkedHashMap<>(selected);
								nextPreference = preference;
							}
						}
						if (evaluated >= 600 || work.exhausted()) { break; }
					}
					if (evaluated >= 600 || work.exhausted()) { break; }
				}
				selected.put("HEAD", head);
				selected.put("AMULET", amulet);
			}
			if (next != null)
			{
				selected.clear();
				selected.putAll(next);
				best = nextPreference;
				changed = true;
			}
			if (!changed) { break; }
		}
		for (String slot : SLOTS)
		{
			Candidate chosen = selected.get(slot);
			if (chosen != original.get(slot))
			{
				selected.put(slot, new Candidate(chosen.stats, "Wilderness budget", chosen.option));
			}
		}
		explanations.add("Wilderness gear compared against a " + request.getWildernessRiskBudget()
			+ " gp full-trip loss budget without relying on Protect Item. Permanent untradeable losses and unknown costs are excluded from automatic readiness; mandatory gear and non-stacking combat bonuses are preserved.");
		explanations.add("Within those loss constraints, this method's Wiki weapon order takes priority over flat equipment stats. The source order accounts for encounter-specific weapons and effects such as Wilderness damage bonuses or Venator bounces; this is not a measured DPS calculation.");
		if (evaluated >= 600 || work.exhausted())
		{
			explanations.add("Wilderness gear comparison reached its work limit; this is a verified candidate where marked ready, not a proof that no better owned combination exists.");
		}
	}

	private static final class RiskPreference
	{
		private final int blockers;
		private final int permanent;
		private final int unknown;
		private final long excess;
		private final int weaponPreference;
		private final double quality;

		private RiskPreference(int blockers, int permanent, int unknown, long excess, int weaponPreference, double quality)
		{
			this.blockers = blockers;
			this.permanent = permanent;
			this.unknown = unknown;
			this.excess = excess;
			this.weaponPreference = weaponPreference;
			this.quality = quality;
		}

		private boolean betterThan(RiskPreference other)
		{
			if (blockers != other.blockers) { return blockers < other.blockers; }
			if (permanent != other.permanent) { return permanent < other.permanent; }
			if (unknown != other.unknown) { return unknown < other.unknown; }
			if (excess != other.excess) { return excess < other.excess; }
			if (weaponPreference != other.weaponPreference) { return weaponPreference < other.weaponPreference; }
			return quality > other.quality + 0.000001;
		}
	}

	WildernessRiskCalculator riskCalculator() { return riskCalculator; }
	SlayerCatalogue catalogue() { return catalogue; }

	boolean spendComparison() { return work.spend(); }

	void checkCancelled() { work.checkCancelled(); }

	boolean isGear(Supply supply)
	{
		return !supply.getItemIds().isEmpty() && supply.getItemIds().stream().allMatch(this::isGearItem);
	}

	boolean hasGearAlternative(Supply supply)
	{
		return supply.getItemIds().stream().anyMatch(this::isGearItem);
	}

	boolean isGearItem(int id)
	{
		String slot = itemSlot(id);
		return SLOTS.contains(slot) && !"AMMO".equals(slot);
	}

	boolean isInventoryItem(int id)
	{
		return "".equals(itemSlot(id));
	}

	private boolean hasOwnedInventoryAlternative(Supply supply)
	{
		long quantity = supply.getItemIds().stream().distinct()
			.filter(this::isInventoryItem).filter(id -> supplyProblems(id).isEmpty())
			.mapToLong(id -> player.getOwned().getOrDefault(id, 0)).sum();
		return quantity >= Math.max(1, supply.getQuantity());
	}

	private String itemSlot(int id)
	{
		ItemStats item = player.getItems().get(id);
		ItemDefinition definition = catalogue.getItems().get(id);
		if (item != null && SLOTS.contains(item.getSlot()))
		{
			return item.getSlot();
		}
		if (definition != null && SLOTS.contains(definition.getSlot()))
		{
			return definition.getSlot();
		}
		if (item != null && "".equals(item.getSlot())
			|| definition != null && "".equals(definition.getSlot()))
		{
			return "";
		}
		return null;
	}

	private boolean isAmmunition(Supply supply)
	{
		return !supply.getItemIds().isEmpty() && supply.getItemIds().stream()
			.allMatch(id -> "AMMO".equals(itemSlot(id)));
	}

	List<String> itemProblems(int id)
	{
		return usability.computeIfAbsent(id, key ->
		{
			List<String> problems = new ArrayList<>();
			ItemStats stats = player.getItems().get(key);
			ItemDefinition definition = catalogue.getItems().get(key);
			String name = stats != null ? stats.getName() : definition == null ? "Item " + key : definition.getName();
			if (stats == null || !stats.isUsable())
			{
				problems.add("Item usability is not verified: " + name + ".");
			}
			if ((definition == null || !definition.isRequirementsKnown())
				&& !requirements.isMet("Can equip: " + name))
			{
				problems.add("Confirm requirement: Can equip: " + name);
			}
			if (definition != null)
			{
				if (!definition.isUsable())
				{
					problems.add("Unusable item form: " + name + ".");
				}
				definition.getLevels().forEach((skill, level) -> requirements.level(skill, level, problems));
				requirements.checkAll(definition.getRequirements(), problems);
			}
			return problems;
		});
	}

	List<String> supplyProblems(int id)
	{
		ItemStats stats = player.getItems().get(id);
		if (SLOTS.contains(itemSlot(id)))
		{
			return itemProblems(id);
		}
		List<String> problems = new ArrayList<>();
		ItemDefinition definition = catalogue.getItems().get(id);
		if (!isInventoryItem(id))
		{
			problems.add("Supply type is not verified: Item " + id + ".");
		}
		if (stats != null && !stats.isUsable())
		{
			problems.add("Unusable supply form: " + stats.getName() + ".");
		}
		if (definition != null)
		{
			if (!definition.isUsable())
			{
				problems.add("Unusable supply form: " + definition.getName() + ".");
			}
			definition.getLevels().forEach((skill, level) -> requirements.level(skill, level, problems));
			requirements.checkAll(definition.getRequirements(), problems);
		}
		return problems;
	}

	private void createDomains()
	{
		SLOTS.forEach(slot -> domains.put(slot, new ArrayList<>()));
		for (String slot : SLOTS)
		{
			List<ItemOption> options = method.getEquipment().getOrDefault(slot, Collections.emptyList());
			for (int index = 0; index < options.size(); index++)
			{
				ItemOption option = options.get(index);
				List<String> optionProblems = new ArrayList<>();
				requirements.checkAll(option.getRequirements(), optionProblems);
				if (!optionProblems.isEmpty())
				{
					continue;
				}
				List<Integer> ids = new ArrayList<>(option.getItemIds());
				ids.sort(Comparator.comparingInt((Integer id) -> player.getCarried().getOrDefault(id, 0) > 0 ? 0 : 1));
				for (Integer id : ids)
				{
					ItemStats item = player.getItems().get(id);
					if (item != null && owned(id) && usable(id) && slot.equals(item.getSlot())
						&& (!"WEAPON".equals(slot) || styleCompatible(item)))
					{
						addCandidate(slot, new Candidate(item, index == 0 ? "Wiki" : "Wiki alternative", option), false);
					}
				}
			}
		}
		// A companion can be necessary even when its own Wiki row was not compiled.
		Set<Integer> companionIds = method.getEquipment().values().stream().flatMap(List::stream)
			.flatMap(option -> option.getRequires().stream()).flatMap(List::stream).collect(Collectors.toSet());
		Set<Integer> wikiIds = method.getEquipment().values().stream().flatMap(List::stream)
			.flatMap(option -> option.getItemIds().stream()).collect(Collectors.toSet());
		for (Integer id : companionIds)
		{
			ItemStats item = player.getItems().get(id);
			if (item != null && usable(id) && owned(id) && !wikiIds.contains(id))
			{
				addCandidate(item.getSlot(), new Candidate(item, "Required", null), false);
			}
		}
		List<ItemStats> fallback = player.getItems().values().stream()
			.filter(item -> item != null && SLOTS.contains(item.getSlot()) && owned(item.getId())
				&& usable(item.getId()) && styleCompatible(item))
			.sorted(Comparator.comparingDouble(this::fallbackScore).reversed()
				.thenComparing(ItemStats::getName).thenComparingInt(ItemStats::getId))
			.collect(Collectors.toList());
		for (ItemStats item : fallback)
		{
			// Do not bypass a method-specific requirement/dependency via the same item's fallback.
			if (!wikiIds.contains(item.getId()))
			{
				addCandidate(item.getSlot(), new Candidate(item, "Owned fallback", null), false);
			}
		}
	}

	private boolean search(int index, Map<String, Candidate> selected)
	{
		if (++visited > SEARCH_LIMIT)
		{
			return false;
		}
		if (index == SEARCH_ORDER.size())
		{
			return stats(selected, "WEAPON") != null;
		}
		String slot = SEARCH_ORDER.get(index);
		for (Candidate candidate : domains.get(slot))
		{
			selected.put(slot, candidate);
			if (possible(selected) && search(index + 1, selected))
			{
				return true;
			}
		}
		selected.remove(slot);
		return false;
	}

	private void compareConditionalPairs(Map<String, Candidate> selected, List<String> explanations)
	{
		boolean available = domains.get("HEAD").stream().anyMatch(c -> bonuses.applicable(c.stats) > 1)
			|| domains.get("AMULET").stream().anyMatch(c -> bonuses.applicable(c.stats) > 1);
		if (!available)
		{
			return;
		}
		Candidate originalHead = selected.get("HEAD");
		Candidate originalAmulet = selected.get("AMULET");
		Candidate bestHead = originalHead;
		Candidate bestAmulet = originalAmulet;
		double best = bonusScore(selected);
		for (Candidate head : pairOptions("HEAD", originalHead))
		{
			selected.put("HEAD", head);
			for (Candidate amulet : pairOptions("AMULET", originalAmulet))
			{
				selected.put("AMULET", amulet);
				if (!possible(selected))
				{
					continue;
				}
				double score = bonusScore(selected);
				// Keep the original Wiki/carried priority when scores tie.
				if (score > best + 0.000001)
				{
					best = score;
					bestHead = head;
					bestAmulet = amulet;
				}
			}
		}
		selected.put("HEAD", compared(bestHead, originalHead));
		selected.put("AMULET", compared(bestAmulet, originalAmulet));
		explanations.add("Head and amulet compared together using whole-loadout offensive stats and one applicable Slayer/Salve boost. This is a relative stat estimate, not a DPS calculation; mandatory equipment and set dependencies are retained.");
	}

	private List<Candidate> riskPairOptions(String slot, Candidate original)
	{
		return original.option != null && !original.option.getRequires().isEmpty()
			? Collections.singletonList(original) : domains.get(slot);
	}

	private List<Candidate> pairOptions(String slot, Candidate original)
	{
		// Keep method-defining set/effect choices, including Void headgear and companion necklaces.
		// Their effects are outside this comparison; removing the option would erase its dependencies.
		if (original.option != null && !original.option.getRequires().isEmpty())
		{
			return Collections.singletonList(original);
		}
		return domains.get(slot).stream().filter(c -> c.stats != null || original.stats == null)
			.collect(Collectors.toList());
	}

	private Candidate compared(Candidate selected, Candidate original)
	{
		return selected == original || selected.stats == null ? selected
			: new Candidate(selected.stats, "Bonus comparison", selected.option);
	}

	private double bonusScore(Map<String, Candidate> selected)
	{
		double attack = 0;
		double strength = 0;
		double utility = 0;
		for (Candidate candidate : selected.values())
		{
			if (candidate.stats != null)
			{
				attack += candidate.stats.attackFor(method.getStyle());
				strength += candidate.stats.strengthFor(method.getStyle());
				utility += utilityScore(candidate.stats);
			}
		}
		double multiplier = bonuses.rankingMultiplier(stats(selected, "HEAD"), stats(selected, "AMULET"), stats(selected, "WEAPON"));
		// The bonus affects the whole attack, not just the helmet/amulet's own flat stats.
		// Offsets retain the underlying attack/damage when gear has zero offensive bonuses.
		double damageBase = "MAGIC".equalsIgnoreCase(method.getStyle()) ? 100 : 64;
		return (Math.max(0, strength + damageBase) * 4 + Math.max(0, attack + 64)) * multiplier + utility;
	}

	private boolean possible(Map<String, Candidate> selected)
	{
		ItemStats weapon = stats(selected, "WEAPON");
		if (selected.containsKey("WEAPON") && weapon == null)
		{
			return false;
		}
		if (weapon != null && weapon.isTwoHanded() && stats(selected, "SHIELD") != null)
		{
			return false;
		}
		if (selected.containsKey("AMMO") && !EquipmentCompatibility.compatible(weapon, stats(selected, "AMMO")))
		{
			return false;
		}
		if (!selected.containsKey("AMMO") && weapon != null && domains.get("AMMO").stream()
			.noneMatch(candidate -> EquipmentCompatibility.compatible(weapon, candidate.stats)))
		{
			return false;
		}
		List<List<Integer>> groups = new ArrayList<>(mandatory);
		if (!primaryAmmo.isEmpty() && EquipmentCompatibility.needsAmmo(weapon))
		{
			groups.add(primaryAmmo);
		}
		selected.values().stream().filter(c -> c.option != null)
			.forEach(c -> groups.addAll(c.option.getRequires()));
		for (List<Integer> group : groups)
		{
			boolean satisfiable = selected.values().stream()
				.anyMatch(c -> c.stats != null && group.contains(c.stats.getId()));
			if (!satisfiable)
			{
				satisfiable = domains.entrySet().stream().filter(e -> !selected.containsKey(e.getKey()))
					.filter(e -> weapon == null || !weapon.isTwoHanded() || !"SHIELD".equals(e.getKey()))
					.flatMap(e -> e.getValue().stream())
					.anyMatch(c -> c.stats != null && group.contains(c.stats.getId()));
			}
			if (!satisfiable)
			{
				return false;
			}
		}
		return true;
	}

	private boolean styleCompatible(ItemStats item)
	{
		String style = method.getStyle() == null ? "MELEE" : method.getStyle().toUpperCase(Locale.ROOT);
		if ("AMMO".equals(item.getSlot()))
		{
			return true;
		}
		if ("WEAPON".equals(item.getSlot()))
		{
			return style.equals(item.getStyle()) || "ANY".equals(item.getStyle()) && "MELEE".equals(style);
		}
		if (bonuses.applicable(item) > 1)
		{
			return true;
		}
		return style.equals(item.getStyle()) || "ANY".equals(item.getStyle());
	}

	private double fallbackScore(ItemStats item)
	{
		return item.strengthFor(method.getStyle()) * 4 + item.attackFor(method.getStyle()) + utilityScore(item);
	}

	private double utilityScore(ItemStats item)
	{
		double prayerWeight = request.getGoal() == RecommendationGoal.LOW_EFFORT ? 5 : 1;
		double defenceWeight = request.getGoal() == RecommendationGoal.LOW_EFFORT ? 0.4 : 0.05;
		return item.getPrayer() * prayerWeight
			+ item.getDefence() * defenceWeight;
	}

	private void addCandidate(String slot, Candidate candidate, boolean first)
	{
		List<Candidate> options = domains.get(slot);
		if (options == null || options.stream().anyMatch(c -> c.stats != null && c.stats.getId() == candidate.stats.getId()))
		{
			return;
		}
		options.add(first ? 0 : options.size(), candidate);
	}

	private boolean usable(int id)
	{
		return itemProblems(id).isEmpty();
	}

	private boolean owned(int id)
	{
		return player.getOwned().getOrDefault(id, 0) > 0;
	}

	private void addRelevantRequirements(List<Integer> ids, List<String> target)
	{
		for (Integer id : ids)
		{
			if (owned(id))
			{
				itemProblems(id).forEach(problem -> add(target, problem));
			}
		}
	}

	private void addSlotRequirements(String slot, List<String> target)
	{
		for (ItemOption option : method.getEquipment().getOrDefault(slot, Collections.emptyList()))
		{
			if (option.getItemIds().stream().anyMatch(this::owned))
			{
				requirements.checkAll(option.getRequirements(), target);
				addRelevantRequirements(option.getItemIds(), target);
			}
		}
		player.getItems().values().stream().filter(item -> item != null && slot.equals(item.getSlot())
			&& owned(item.getId()) && styleCompatible(item))
			.sorted(Comparator.comparingDouble(this::fallbackScore).reversed().thenComparing(ItemStats::getName))
			.limit(5).forEach(item -> itemProblems(item.getId()).forEach(problem -> add(target, problem)));
	}

	private static ItemStats stats(Map<String, Candidate> selected, String slot)
	{
		Candidate candidate = selected.get(slot);
		return candidate == null ? null : candidate.stats;
	}

	private static void add(List<String> target, String value)
	{
		if (!target.contains(value))
		{
			target.add(value);
		}
	}

	private static final class Candidate
	{
		private static final Candidate EMPTY = new Candidate(null, "Owned fallback", null);
		private final ItemStats stats;
		private final String origin;
		private final ItemOption option;

		private Candidate(ItemStats stats, String origin, ItemOption option)
		{
			this.stats = stats;
			this.origin = origin;
			this.option = option;
		}
	}
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.ItemStats;
import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Choice;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Location;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Method;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Supply;
import com.danieljglover.allinslayer.model.advisor.WildernessRisk.Scenario;
import com.danieljglover.allinslayer.model.advisor.TripPreparationData;
import com.danieljglover.allinslayer.model.advisor.BoostReservations;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.stream.Collectors;

/** Packs required items first, then switches, travel, and supplies, with a strict 28-slot limit. */
final class SupplyPlanner
{
	private static final int CAPACITY = 28;
	private static final int MAX_SUPPLY_REPLANS = 32;
	private static final java.util.regex.Pattern BOOST_SPACES = java.util.regex.Pattern.compile("\\s+");
	private static final java.util.regex.Pattern BOOST_DOSE = java.util.regex.Pattern.compile("\\s*\\([1-4]\\)$");
	private final RecommendationRequest request;
	private final PlayerSnapshot player;
	private final long riskBudget;
	private final EquipmentPlanner equipmentPlanner;
	private final RequirementEvaluator requirements;
	private final Map<Integer, Integer> available = new HashMap<>();
	private final Map<Integer, Integer> carried = new HashMap<>();
	private final Map<Integer, Allocation> allocations = new LinkedHashMap<>();
	private final List<Choice> unresolved = new ArrayList<>();
	private final Map<String, String> forcedFamilies;
	private final boolean collectAlternatives;
	private final boolean compareContainers;
	private final boolean omitOptionalPouch;
	private final boolean omitOptionalBag;
	private final Map<String, List<String>> alternatives = new LinkedHashMap<>();
	private final Map<String, Fulfillment> fulfilled = new LinkedHashMap<>();
	private final Map<String, Coverage> coverage = new LinkedHashMap<>();
	private int slots;
	private int capacity = CAPACITY;
	private boolean allowBlighted;
	private final TripPreparationData preparation;

	SupplyPlanner(RecommendationRequest request, EquipmentPlanner equipmentPlanner,
		Map<String, Choice> equipment)
	{
		this(request, equipmentPlanner, equipment, java.util.Collections.emptyMap(), false);
	}

	private SupplyPlanner(RecommendationRequest request, EquipmentPlanner equipmentPlanner,
		Map<String, Choice> equipment, Map<String, String> forcedFamilies, boolean collectAlternatives)
	{
		this(request, equipmentPlanner, equipment, forcedFamilies, collectAlternatives, true, false, false);
	}

	private SupplyPlanner(RecommendationRequest request, EquipmentPlanner equipmentPlanner,
		Map<String, Choice> equipment, Map<String, String> forcedFamilies, boolean collectAlternatives,
		boolean compareContainers, boolean omitOptionalPouch, boolean omitOptionalBag)
	{
		this.request = request;
		this.player = request.getPlayer();
		this.riskBudget = request.getWildernessRiskBudget();
		this.equipmentPlanner = equipmentPlanner;
		this.requirements = new RequirementEvaluator(request);
		this.preparation = equipmentPlanner.catalogue().getPreparation();
		this.forcedFamilies = new LinkedHashMap<>(forcedFamilies);
		this.collectAlternatives = collectAlternatives;
		this.compareContainers = compareContainers;
		this.omitOptionalPouch = omitOptionalPouch;
		this.omitOptionalBag = omitOptionalBag;
		available.putAll(player.getOwned());
		carried.putAll(player.getCarried());
		if (player.getDeathContext().isPouchContentsKnown() && preparation.getPouches().stream()
			.anyMatch(pouch -> player.getCarried().getOrDefault(pouch.getItemId(), 0) > 0))
		{
			player.getDeathContext().getPouchContents().forEach((id, quantity) ->
				carried.merge(id, quantity, (a, b) -> (int) Math.min(Integer.MAX_VALUE, (long) a + b)));
		}
		for (Choice choice : equipment.values())
		{
			if (choice.getItemId() > 0)
			{
				available.computeIfPresent(choice.getItemId(), (id, count) -> Math.max(0, count - choice.getQuantity()));
				carried.computeIfPresent(choice.getItemId(), (id, count) -> Math.max(0, count - choice.getCarried()));
			}
		}
	}

	List<Choice> planOptimized(Method method, Location location, List<Supply> required,
		Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		if (!equipmentPlanner.riskCalculator().applies())
		{
			return plan(method, location, required, equipment, blockers, explanations);
		}
		Attempt initial = attempt(method, location, required, equipment, java.util.Collections.emptyMap());
		Attempt best = initial;
		int replans = 0;
		boolean workAvailable = true;
		java.util.Set<Map<String, String>> seen = new java.util.HashSet<>();
		seen.add(java.util.Collections.emptyMap());
		while (workAvailable && replans < MAX_SUPPLY_REPLANS && !Thread.currentThread().isInterrupted() && !withinBudget(best.risk))
		{
			Attempt improved = best;
			// A complete trip is rebuilt for each choice: later runes, food and ammunition can
			// push an otherwise affordable early supply over budget or change protected items.
			comparison: for (Map.Entry<String, List<String>> group : best.planner.alternatives.entrySet())
			{
				for (String family : group.getValue())
				{
					if (replans >= MAX_SUPPLY_REPLANS || Thread.currentThread().isInterrupted()) { break; }
					String current = best.planner.forcedFamilies.getOrDefault(group.getKey(), group.getValue().get(0));
					if (family.equals(current)) { continue; }
					Map<String, String> forced = new LinkedHashMap<>(best.planner.forcedFamilies);
					forced.put(group.getKey(), family);
					if (!seen.add(forced)) { continue; }
					if (!equipmentPlanner.spendComparison())
					{
						workAvailable = false;
						break comparison;
					}
					replans++;
					Attempt candidate = attempt(method, location, required, equipment, forced);
					if (preserves(initial, candidate) && compare(candidate.risk, improved.risk) < 0)
					{
						improved = candidate;
						if (withinBudget(improved.risk)) { break; }
					}
				}
				if (withinBudget(improved.risk)) { break; }
			}
			if (improved == best) { break; }
			best = improved;
		}
		blockers.addAll(best.blockers);
		explanations.addAll(best.explanations);
		if (best != initial)
		{
			explanations.add("Owned supply alternatives were compared against the completed trip's Wilderness loss, preserving planned quantities and visible potion doses.");
		}
		if (!withinBudget(best.risk))
		{
			explanations.add("The bounded supply comparison did not find a complete inventory within the Wilderness loss budget.");
		}
		return best.inventory;
	}

	private Attempt attempt(Method method, Location location, List<Supply> required,
		Map<String, Choice> equipment, Map<String, String> forced)
	{
		equipmentPlanner.checkCancelled();
		SupplyPlanner planner = new SupplyPlanner(request, equipmentPlanner, equipment, forced, true);
		List<String> blockers = new ArrayList<>();
		List<String> explanations = new ArrayList<>();
		List<Choice> inventory = planner.plan(method, location, required, equipment, blockers, explanations);
		Scenario risk = equipmentPlanner.riskCalculator().baseline(equipment, inventory);
		return new Attempt(planner, inventory, blockers, explanations, risk);
	}

	private boolean withinBudget(Scenario scenario)
	{
		return scenario.isComplete() && scenario.getPermanentLosses() == 0 && scenario.getTotalRisk() <= riskBudget;
	}

	private int compare(Scenario first, Scenario second)
	{
		int order = Integer.compare(first.getPermanentLosses(), second.getPermanentLosses());
		if (order == 0) { order = Boolean.compare(second.isComplete(), first.isComplete()); }
		if (order == 0) { order = Long.compare(Math.max(0, first.getTotalRisk() - riskBudget), Math.max(0, second.getTotalRisk() - riskBudget)); }
		return order;
	}

	private static boolean preserves(Attempt original, Attempt candidate)
	{
		if (!original.blockers.containsAll(candidate.blockers)) { return false; }
		for (Map.Entry<String, Fulfillment> entry : original.planner.fulfilled.entrySet())
		{
			Fulfillment next = candidate.planner.fulfilled.get(entry.getKey());
			if (next == null || next.quantity < entry.getValue().quantity || next.doses < entry.getValue().doses)
			{
				return false;
			}
		}
		return true;
	}

	List<Choice> plan(Method method, Location location, List<Supply> required,
		Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		List<String> initialBlockers = new ArrayList<>();
		List<String> initialExplanations = new ArrayList<>();
		List<Choice> initialInventory = pack(method, location, required, equipment, initialBlockers, initialExplanations);
		Attempt best = new Attempt(this, initialInventory, initialBlockers, initialExplanations, null);
		if (compareContainers && equipmentPlanner.riskCalculator().applies()
			&& (hasOptionalContainer(false) || hasOptionalContainer(true)))
		{
			best = new Attempt(this, initialInventory, initialBlockers, initialExplanations,
				equipmentPlanner.riskCalculator().baseline(equipment, initialInventory));
			// Storage earns its place only against the completed trip. Rebuild once per
			// optional container so freed slots are refilled and rejected notes cannot leak.
			for (boolean pouch : new boolean[] {false, true})
			{
				if (withinBudget(best.risk) || !best.planner.hasOptionalContainer(pouch)) { continue; }
				if (!equipmentPlanner.spendComparison()) { break; }
				equipmentPlanner.checkCancelled();
				SupplyPlanner candidate = new SupplyPlanner(request, equipmentPlanner, equipment,
					forcedFamilies, collectAlternatives, false,
					pouch || best.planner.omitOptionalPouch, !pouch || best.planner.omitOptionalBag);
				List<String> candidateBlockers = new ArrayList<>();
				List<String> candidateExplanations = new ArrayList<>();
				List<Choice> inventory = candidate.pack(method, location, required, equipment,
					candidateBlockers, candidateExplanations);
				Scenario risk = equipmentPlanner.riskCalculator().baseline(equipment, inventory);
				if (best.blockers.containsAll(candidateBlockers) && compare(risk, best.risk) < 0)
				{
					best = new Attempt(candidate, inventory, candidateBlockers, candidateExplanations, risk);
				}
			}
		}
		if (best.planner != this)
		{
			alternatives.clear(); alternatives.putAll(best.planner.alternatives);
			coverage.clear(); coverage.putAll(best.planner.coverage);
			fulfilled.clear(); fulfilled.putAll(best.planner.fulfilled);
		}
		blockers.addAll(best.blockers);
		explanations.addAll(best.explanations);
		return best.inventory;
	}

	private boolean hasOptionalContainer(boolean pouch)
	{
		return allocations.values().stream().anyMatch(allocation -> !allocation.required && allocation.quantity > 0
			&& (pouch ? pouchItem(allocation.id) : preparation.getLootingBagIds().contains(allocation.id)));
	}

	private List<Choice> pack(Method method, Location location, List<Supply> required,
		Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		allowBlighted = location.isWilderness();
		SpellPlanner.CastingPlan casting = new SpellPlanner(preparation, request).plan(method, equipment, allowBlighted);
		blockers.addAll(casting.getBlockers());
		casting.getNotes().forEach(note -> explanations.add("Casting: " + note));
		TripTravelPlanner.TravelPlan travel = new TripTravelPlanner(equipmentPlanner.catalogue(), request)
			.plan(location, equipment, casting.getSupplies());
		blockers.addAll(travel.getBlockers());
		explanations.addAll(travel.getNotes());
		List<Need> needs = new ArrayList<>();
		for (Supply supply : required)
		{
			if (casting.isManaged() && castingResource(supply)) { continue; }
			if (supply.isRequired() && equipmentPlanner.isGear(supply)
				&& supply.getQuantity() <= 1)
			{
				// Merely carrying mandatory protection must not satisfy the equipment gate.
				continue;
			}
			needs.add(new Need(supply, "Required", "SUPPLY", supply.isRequired()));
		}
		for (Supply supply : method.getSwitches())
		{
			if (!waived(supply))
			{
				needs.add(new Need(supply, "Wiki", "SWITCH", supply.isRequired()));
			}
		}
		Choice shield = equipment.get("SHIELD");
		if (shield != null && shield.getItemId() > 0 && method.getSwitches().stream()
			.flatMap(supply -> supply.getItemIds().stream()).map(player.getItems()::get)
			.anyMatch(item -> item != null && item.isTwoHanded() && available.getOrDefault(item.getId(), 0) > 0))
		{
			capacity--;
			explanations.add("One inventory slot is reserved for the shield displaced by a two-handed weapon switch.");
		}
		for (Supply supply : location.getTravel())
		{
			if (!waived(supply))
			{
				needs.add(new Need(supply, "Wiki", "TRAVEL", supply.isRequired()));
			}
		}
		for (Supply supply : method.getInventory())
		{
			if (casting.isManaged() && castingResource(supply)) { continue; }
			if (!waived(supply))
			{
				needs.add(new Need(supply, "Wiki", "SUPPLY", supply.isRequired()));
			}
		}
		List<Supply> castingResources = new ArrayList<>(casting.getSupplies());
		castingResources.addAll(travel.getRunes());
		for (Supply resource : aggregateCasting(castingResources))
		{
			needs.add(0, new Need(resource, "Casting", "CASTING", true));
		}
		for (Supply resource : travel.getSupplies())
		{
			needs.add(0, new Need(resource, "Trip preparation", "TRAVEL", true));
		}
		for (Need need : needs.stream().filter(value -> value.required).collect(Collectors.toList()))
		{
			allocate(need, equipment, blockers, explanations);
		}
		if (method.isCannon())
		{
			ensureCannon(equipment, blockers, explanations);
		}
		validateSwitchAmmunition(equipment, blockers, explanations);
		packRunePouch(equipment, explanations);
		packConfiguredBoosts(method, equipment, blockers, explanations);
		packLootingBag(equipment, blockers, explanations);
		for (Need need : needs.stream().filter(value -> !value.required).collect(Collectors.toList()))
		{
			if (replacedBoost(need, method)) { continue; }
			Need remaining = withoutOptionalFood(need);
			if (remaining != null) { allocate(remaining, equipment, blockers, explanations); }
		}
		validateSwitchAmmunition(equipment, blockers, explanations);
		addOwnedBasics(equipment, blockers, explanations);
		if (collectAlternatives) { captureFulfillment(); }
		List<Choice> result = choices();
		result.addAll(unresolved);
		explanations.add("Inventory: " + slots + "/28 planned slots. Bank quantities come from the latest observed bank; doses and internal charges are not inferred.");
		return result;
	}

	private void packConfiguredBoosts(Method method, Map<String, Choice> equipment,
		List<String> blockers, List<String> explanations)
	{
		BoostReservations.Style configured = request.getBoostReservations().forStyle(method.getStyle());
		if (configured.getSlots() == 0) { return; }
		String style = method.getStyle().toLowerCase(Locale.ROOT);
		List<String> preferences = configured.getPreferences().stream().filter(this::knownBoost).collect(Collectors.toList());
		List<String> unsupported = configured.getPreferences().stream().filter(name -> !knownBoost(name)).collect(Collectors.toList());
		if (!unsupported.isEmpty())
		{
			explanations.add("Boosts: Ignored unrecognised combat boosts in " + style + " settings: "
				+ String.join(", ", unsupported) + ". Use the full item name, with or without a dose suffix.");
		}
		String selected = preferences.isEmpty() ? "Unspecified " + style + " boost" : preferences.get(0);
		List<Integer> ids = new ArrayList<>();
		for (String preference : preferences)
		{
			List<Integer> matches = player.getItems().values().stream()
				.filter(item -> player.getOwned().getOrDefault(item.getId(), 0) > 0
					&& !item.isStackable() && equipmentPlanner.isInventoryItem(item.getId())
					&& matchesBoost(preference, item.getName())
					&& equipmentPlanner.supplyProblems(item.getId()).isEmpty()
					&& (allowBlighted || !blightedItem(item.getId())))
				.sorted(Comparator.comparingInt((ItemStats item) -> doses(item.getName())).reversed()
					.thenComparingInt(ItemStats::getId))
				.map(ItemStats::getId).collect(Collectors.toList());
			if (!matches.isEmpty())
			{
				selected = preference;
				ids = matches;
				break;
			}
		}
		String selectedFamily = boostFamily(selected);
		boolean heart = preparation.getReusableBoosts().stream().anyMatch(name -> boostFamily(name).equals(selectedFamily));
		int target = heart ? 1 : configured.getSlots();
		int missing;
		if (ids.isEmpty())
		{
			missing = target;
			String message = preferences.isEmpty()
				? "Choose a recognised combat boost in the " + style + " boost settings, or set reserved slots to 0."
				: "No owned usable " + style + " boost matches your preferences: "
					+ String.join(", ", preferences) + ". Open your bank and check the configured item names.";
			add(blockers, message);
			unresolved.add(new Choice(0, 0, 0, 0, missing, "BOOST", selected, "Configured boost", true));
		}
		else
		{
			allocate(new Need(supply(selected, ids, target, true, false), "Configured boost", "BOOST", true),
				equipment, blockers, explanations);
			int packed = ids.stream().map(allocations::get).filter(java.util.Objects::nonNull)
				.mapToInt(allocation -> allocation.quantity).sum();
			missing = Math.max(0, target - packed);
			for (int id : ids)
			{
				Allocation allocation = allocations.get(id);
				if (allocation != null)
				{
					allocation.slot = "BOOST";
					allocation.origin = "Configured boost";
				}
			}
		}
		// Keep shortages free for the requested boost; food and optional supplies must not
		// consume its reservation. Mandatory supplies have already claimed their space.
		int held = Math.min(missing, Math.max(0, capacity - slots));
		capacity -= held;
		if (held > 0)
		{
			unresolved.add(new Choice(0, held, 0, 0, 0, "RESERVED BOOST", selected, "Configured boost", false,
				"Empty space reserved for missing configured boosts; see Checks."));
		}
		if (held < missing)
		{
			add(blockers, "Configured " + style + " boosts need " + missing + " more slots, but only " + held
				+ " remain after required items. Reduce the boost reservation or choose another method.");
		}
		explanations.add("Boosts: " + style + " - " + selected + ", " + (target - missing) + "/" + target
			+ " packed" + (held > 0 ? "; " + held + " inventory slots kept free for missing boosts" : "") + "."
			+ (heart ? " One reusable heart is enough; extra configured slots remain available for supplies."
				: " Slots count bottles, not doses; fuller owned bottles are preferred."));
	}

	private boolean replacedBoost(Need need, Method method)
	{
		BoostReservations.Style configured = request.getBoostReservations().forStyle(method.getStyle());
		if (configured.getSlots() == 0 || !"SUPPLY".equals(need.slot)) { return false; }
		// Only replace optional boosts for this combat style. Required strategy items and
		// mixed supply groups (for example a restore/boost alternative) keep their meaning.
		if (need.supply.getItemIds().isEmpty()) { return styleBoost(need.supply.getName(), method.getStyle(), configured); }
		return need.supply.getItemIds().stream().allMatch(id -> {
			ItemStats item = player.getItems().get(id);
			com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.ItemDefinition definition = equipmentPlanner.catalogue().getItems().get(id);
			String name = item != null ? item.getName() : definition == null ? "" : definition.getName();
			return styleBoost(name, method.getStyle(), configured);
		});
	}

	private boolean styleBoost(String name, String style, BoostReservations.Style configured)
	{
		if (configured.getPreferences().stream().filter(this::knownBoost)
			.anyMatch(preference -> matchesBoost(preference, name))) { return true; }
		String family = boostFamily(name);
		return preparation.getBoostFamilies().getOrDefault(style, java.util.Collections.emptyList()).stream()
			.anyMatch(boost -> boostFamily(boost).equals(family));
	}

	private boolean knownBoost(String preference)
	{
		String family = boostFamily(preference);
		return preparation.getBoostFamilies().values().stream().flatMap(List::stream)
			.anyMatch(boost -> boostFamily(boost).equals(family));
	}

	private static boolean matchesBoost(String preference, String name)
	{
		String wanted = BOOST_SPACES.matcher(preference.trim().toLowerCase(Locale.ROOT)).replaceAll(" ").replace(" (", "(");
		String actual = BOOST_SPACES.matcher(name.trim().toLowerCase(Locale.ROOT)).replaceAll(" ").replace(" (", "(");
		return wanted.equals(actual) || wanted.equals(boostFamily(actual));
	}

	private static String boostFamily(String name)
	{
		return BOOST_DOSE.matcher(BOOST_SPACES.matcher(name.trim().toLowerCase(Locale.ROOT)).replaceAll(" ")).replaceFirst("");
	}

	private void allocate(Need need, Map<String, Choice> equipment, List<String> blockers,
		List<String> explanations)
	{
		if (!need.required && !need.supply.getItemIds().isEmpty())
		{
			boolean pouch = need.supply.getItemIds().stream().allMatch(this::pouchItem);
			boolean bag = need.supply.getItemIds().stream().allMatch(preparation.getLootingBagIds()::contains);
			// Optional source pouch rows are handled by the compression pass. A second
			// source form must not add another physical pouch after that pass.
			if (pouch || bag && (omitOptionalBag || !allowBlighted
				|| allocations.keySet().stream().anyMatch(preparation.getLootingBagIds()::contains)))
			{
				return;
			}
		}
		boolean configuredFood = "Configured food".equals(need.origin);
		Supply supply = configuredFood ? need.supply : blightedAlternatives(need.supply);
		int target = Math.max(1, supply.getQuantity());
		boolean mixedProtection = need.required && !"SWITCH".equals(need.slot)
			&& equipmentPlanner.hasGearAlternative(supply) && !equipmentPlanner.isGear(supply);
		Choice equipped = equipment.values().stream()
			.filter(choice -> choice.getItemId() > 0 && choice.getQuantity() > 0
				&& supply.getItemIds().contains(choice.getItemId()))
			.findFirst().orElse(null);
		if (equipped != null)
		{
			if (mixedProtection && equipmentPlanner.isGearItem(equipped.getItemId())
				|| target <= equipped.getQuantity() || "SWITCH".equals(need.slot))
			{
				return;
			}
			target -= equipped.getQuantity();
		}
		if (supply.getItemIds().isEmpty())
		{
			String message = "No verified item IDs for " + supply.getName() + "; ownership cannot be checked.";
			add(need.required ? blockers : explanations, message);
			if (need.required)
			{
				unresolved.add(new Choice(0, 0, 0, 0, target, need.slot,
					supply.getName(), need.origin, true));
			}
			return;
		}
		List<Integer> usable = supply.getItemIds().stream()
			// A shield in the bag provides no protection while a two-handed weapon is equipped.
			.filter(id -> !mixedProtection || equipmentPlanner.isInventoryItem(id))
			.filter(id -> allowBlighted || !blightedItem(id))
			.filter(id -> "Trip preparation".equals(need.origin) || equipmentPlanner.supplyProblems(id).isEmpty()).collect(Collectors.toList());
		preferFullContainers(usable);
		if ("Owned fallback".equals(need.origin))
		{
			// The existing fallback policy prefers full potions across restoration families,
			// including when only one full potion of the first family is owned.
			usable.sort(Comparator.comparingInt((Integer id) ->
			{
				ItemStats item = player.getItems().get(id);
				return item == null ? 0 : -doses(item.getName());
			}));
		}
		// Fallbacks take part in the final full-trip comparison without multiplying work in
		// the equipment search, which calls the inexpensive plan path for many candidates.
		if (!configuredFood && !"Owned fallback".equals(need.origin)) { preferAffordableAlternatives(usable, target, equipment); }
		if (collectAlternatives && !configuredFood) { preferForcedFamily(need.key(), usable); }
		int previous = usable.stream().distinct().map(allocations::get)
			.filter(value -> value != null).mapToInt(value -> value.quantity).sum();
		int missing = Math.max(0, target - previous);
		boolean capacityLimited = false;
		boolean pouchLimited = false;
		Allocation last = null;
		for (Integer id : new LinkedHashSet<>(usable))
		{
			ItemStats stats = player.getItems().get(id);
			boolean stackable = stats == null ? supply.isStackable() : stats.isStackable();
			Allocation existing = allocations.get(id);
			int owned = available.getOrDefault(id, 0);
			int room = stackable ? existing != null || slots < capacity ? missing : 0 : capacity - slots;
			int quantity = Math.min(missing, Math.min(owned, room));
			if (existing != null && "RUNE POUCH".equals(existing.slot))
			{
				int pouchRoom = Math.max(0, plannedPouchLimit() - existing.quantity);
				pouchLimited |= quantity > pouchRoom;
				quantity = Math.min(quantity, pouchRoom);
			}
			capacityLimited |= room < missing && owned > room;
			if (quantity > 0)
			{
				if (existing == null)
				{
					existing = new Allocation(id, stats == null ? supply.getName() : stats.getName(),
						need.slot, need.origin, stackable);
					allocations.put(id, existing);
				}
				slots += stackable ? existing.quantity == 0 ? 1 : 0 : quantity;
				existing.quantity += quantity;
				missing -= quantity;
				available.put(id, owned - quantity);
			}
			if (existing != null)
			{
				last = existing;
				existing.required |= need.required;
				if (need.required)
				{
					existing.origin = "Required";
				}
			}
		}
		if (collectAlternatives) { recordFulfillment(need.key(), usable, target); }
		if (missing > 0)
		{
			String reason = pouchLimited ? "the rune pouch's per-rune capacity" : capacityLimited
				? "the 28-slot inventory limit" : "observed ownership or item usability";
			String message = supply.getName() + ": " + (target - missing) + "/" + target
				+ " available in the plan; limited by " + reason + ".";
			add(need.required ? blockers : explanations, message);
			for (Integer id : supply.getItemIds())
			{
				if (!usable.contains(id) && player.getOwned().getOrDefault(id, 0) > 0)
				{
					equipmentPlanner.supplyProblems(id).forEach(problem -> add(need.required ? blockers : explanations, problem));
				}
			}
			if (need.required && last != null)
			{
				last.missing = Math.max(last.missing, missing);
			}
			else if (need.required)
			{
				unresolved.add(new Choice(supply.getItemIds().get(0), 0, 0, 0, missing,
					need.slot, supply.getName(), "Required", true));
			}
		}
	}

	private void ensureCannon(Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		String[] names = {"Cannon base", "Cannon stand", "Cannon barrels", "Cannon furnace"};
		int[] ids = {6, 8, 10, 12};
		for (int index = 0; index < ids.length; index++)
		{
			Supply supply = supply(names[index], java.util.Collections.singletonList(ids[index]), 1, true, false);
			allocate(new Need(supply, "Required", "SUPPLY", true), equipment, blockers, explanations);
		}
		if (allocations.values().stream().noneMatch(a -> a.name.toLowerCase(Locale.ROOT).contains("cannonball")))
		{
			int ownedBalls = (int) Math.min(1000L, (long) available.getOrDefault(2, 0)
				+ available.getOrDefault(21726, 0));
			Supply balls = supply("Cannonballs", java.util.Arrays.asList(2, 21726), Math.max(1, ownedBalls), true, true);
			allocate(new Need(balls, "Required", "SUPPLY", true), equipment, blockers, explanations);
			explanations.add("Cannonballs use up to 1,000 observed owned shots when no source quantity is specified; adjust for trip length.");
		}
	}

	private void preferAffordableAlternatives(List<Integer> ids, int quantity, Map<String, Choice> equipment)
	{
		WildernessRiskCalculator calculator = equipmentPlanner.riskCalculator();
		if (!calculator.applies() || ids.size() < 2) { return; }
		Map<String, com.danieljglover.allinslayer.model.advisor.WildernessRisk.Scenario> scores = new LinkedHashMap<>();
		List<Choice> base = choices();
		// Compare each source alternative at the fullest owned dose; never prefer a nearly empty
		// potion merely because its unit price is lower. Stable sorting retains Wiki preference ties.
		for (Integer id : ids)
		{
			if (available.getOrDefault(id, 0) < quantity || scores.containsKey(containerFamily(id))) { continue; }
			List<Choice> proposed = new ArrayList<>(base);
			proposed.add(new Choice(id, quantity, 0, quantity, 0, "SUPPLY", "Supply alternative", "Comparison", false));
			scores.put(containerFamily(id), calculator.baseline(equipment, proposed));
		}
		ids.sort(Comparator.comparingInt((Integer id) -> scores.containsKey(containerFamily(id))
			? scores.get(containerFamily(id)).getPermanentLosses() : Integer.MAX_VALUE)
			.thenComparingInt(id -> scores.containsKey(containerFamily(id))
				&& scores.get(containerFamily(id)).isComplete() ? 0 : 1)
			.thenComparingLong(id -> scores.containsKey(containerFamily(id))
				? Math.max(0, scores.get(containerFamily(id)).getTotalRisk() - riskBudget) : Long.MAX_VALUE));
	}

	private void preferFullContainers(List<Integer> ids)
	{
		// Wiki item IDs are not necessarily ordered by dose. Preserve the source's order
		// between different supplies, but prefer a fuller visible form of the same item.
		Map<String, Integer> order = new LinkedHashMap<>();
		for (int id : ids)
		{
			order.putIfAbsent(containerFamily(id), order.size());
		}
		ids.sort(Comparator.comparingInt((Integer id) -> order.get(containerFamily(id)))
			.thenComparingInt(id ->
			{
				ItemStats item = player.getItems().get(id);
				return item == null ? 0 : -doses(item.getName());
			}));
	}

	private void preferForcedFamily(String key, List<Integer> ids)
	{
		List<String> families = ids.stream().filter(id -> available.getOrDefault(id, 0) > 0)
			.map(this::containerFamily).distinct().collect(Collectors.toList());
		if (families.size() > 1) { alternatives.put(key, families); }
		String forced = forcedFamilies.get(key);
		if (forced != null)
		{
			// Move the family as a unit so four-dose forms still precede one-dose forms.
			ids.sort(Comparator.comparingInt(id -> forced.equals(containerFamily(id)) ? 0 : 1));
		}
	}

	private void recordFulfillment(String key, List<Integer> ids, int target)
	{
		Coverage existing = coverage.get(key);
		if (existing == null || existing.target < target)
		{
			coverage.put(key, new Coverage(new ArrayList<>(new LinkedHashSet<>(ids)), target));
		}
	}

	private void captureFulfillment()
	{
		for (Map.Entry<String, Coverage> entry : coverage.entrySet())
		{
			int quantity = 0;
			long doseCount = 0;
			List<Integer> ids = new ArrayList<>(entry.getValue().ids);
			preferFullContainers(ids);
			for (int id : ids)
			{
				Allocation allocation = allocations.get(id);
				if (allocation == null) { continue; }
				int count = Math.min(allocation.quantity, entry.getValue().target - quantity);
				quantity += count;
				doseCount += (long) count * doses(allocation.name);
			}
			fulfilled.put(entry.getKey(), new Fulfillment(quantity, doseCount));
		}
	}

	private String containerFamily(int id)
	{
		ItemStats item = player.getItems().get(id);
		return item == null || doses(item.getName()) == 0 ? "item:" + id
			: item.getName().toLowerCase(Locale.ROOT).replaceFirst("\\s*\\([1-9]\\)$", "");
	}

	private void validateSwitchAmmunition(Map<String, Choice> equipment, List<String> blockers,
		List<String> explanations)
	{
		for (Allocation allocation : new ArrayList<>(allocations.values()))
		{
			if (!"SWITCH".equals(allocation.slot))
			{
				continue;
			}
			ItemStats weapon = player.getItems().get(allocation.id);
			if (weapon == null || !"WEAPON".equals(weapon.getSlot()))
			{
				continue;
			}
			if (EquipmentCompatibility.chargeBearing(weapon))
			{
				explanations.add("Check " + weapon.getName() + " switch charges and loaded ammunition before the trip.");
			}
			if (!EquipmentCompatibility.needsAmmo(weapon))
			{
				continue;
			}
			Choice ammo = equipment.get("AMMO");
			boolean equippedAmmo = ammo != null && ammo.getItemId() > 0
				&& EquipmentCompatibility.compatible(weapon, player.getItems().get(ammo.getItemId()));
			boolean packedAmmo = allocations.values().stream().map(value -> player.getItems().get(value.id))
				.anyMatch(item -> item != null && "AMMO".equals(item.getSlot())
					&& EquipmentCompatibility.compatible(weapon, item));
			if (equippedAmmo || packedAmmo)
			{
				continue;
			}
			List<ItemStats> alternatives = player.getItems().values().stream()
				.filter(item -> item != null && "AMMO".equals(item.getSlot())
					&& equipmentPlanner.itemProblems(item.getId()).isEmpty()
					&& EquipmentCompatibility.compatible(weapon, item))
				.sorted(Comparator.comparingDouble(ItemStats::getStrength).reversed().thenComparingInt(ItemStats::getId))
				.collect(Collectors.toList());
			ItemStats alternative = alternatives.stream().filter(item -> available.getOrDefault(item.getId(), 0) > 0)
				.findFirst().orElse(null);
			if (alternative != null && slots < capacity)
			{
				int quantity = Math.min(1000, available.get(alternative.getId()));
				Supply supply = supply("Ammunition for " + weapon.getName(), alternatives.stream().map(ItemStats::getId).collect(Collectors.toList()),
					quantity, allocation.required, alternative.isStackable());
				allocate(new Need(supply, "Owned fallback", "SWITCH AMMO", allocation.required),
					equipment, blockers, explanations);
				explanations.add(weapon.getName() + ": compatible ammunition is packed with the weapon switch.");
			}
			else if (allocation.required)
			{
				blockers.add("Required weapon switch " + weapon.getName() + " has no usable compatible ammunition in the plan.");
			}
			else
			{
				allocations.remove(allocation.id);
				slots -= allocation.stackable ? 1 : allocation.quantity;
				available.merge(allocation.id, allocation.quantity, Integer::sum);
				explanations.add("Omitted optional " + weapon.getName() + " switch because compatible ammunition cannot be packed.");
			}
		}
	}

	private void addOwnedBasics(Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		boolean prayerPlanned = allocations.values().stream().anyMatch(a -> restoration(a.name));
		if (!prayerPlanned && player.getLevels().getOrDefault("PRAYER", 1) > 1)
		{
			addFallback("Owned prayer/restoration potions", player.getItems().values().stream().filter(item -> restoration(item.getName()))
				.sorted(Comparator.comparingInt((ItemStats item) -> doses(item.getName())).reversed()
					.thenComparing(ItemStats::getName)).collect(Collectors.toList()), 2, equipment, blockers, explanations);
		}
		if (request.getFoodOverride().isEnabled())
		{
			packConfiguredFood(equipment, blockers, explanations);
			return;
		}
		if (slots < capacity)
		{
			int plannedFood = allocations.values().stream().filter(a -> foodPriority(a.name) > 0).mapToInt(a -> a.quantity).sum();
			addFallback("Owned food", player.getItems().values().stream().filter(item -> foodPriority(item.getName()) > 0)
				.sorted(Comparator.comparingInt((ItemStats item) -> foodPriority(item.getName())).reversed()
				.thenComparing(ItemStats::getName)).collect(Collectors.toList()), plannedFood + capacity - slots, equipment, blockers, explanations);
		}
		if (allocations.values().stream().noneMatch(a -> foodPriority(a.name) > 0))
		{
			explanations.add("No recognised owned food is included; review the method's sustain and healing guidance.");
		}
		if (allocations.values().stream().anyMatch(a -> "Owned fallback".equals(a.origin)))
		{
			explanations.add("Owned restoration supplements the method supplies; useful owned food fills the remaining inventory slots after travel, casting and storage items.");
		}
	}

	private Need withoutOptionalFood(Need need)
	{
		if (!request.getFoodOverride().isEnabled() || need.required || !"SUPPLY".equals(need.slot)) { return need; }
		if (need.supply.getItemIds().isEmpty())
		{
			String name = need.supply.getName().toLowerCase(Locale.ROOT);
			return foodPriority(name) > 0 || name.equals("food") || name.equals("foods")
				|| name.equals("high healing food") || name.equals("cooked food") ? null : need;
		}
		// Keep non-food alternatives in mixed optional supply groups. Mandatory items,
		// switches and travel supplies retain their source meaning.
		List<Integer> ids = need.supply.getItemIds().stream().filter(id -> !foodItem(id)).collect(Collectors.toList());
		if (ids.isEmpty()) { return null; }
		if (ids.size() == need.supply.getItemIds().size()) { return need; }
		return new Need(supply(need.supply.getName(), ids, need.supply.getQuantity(), false,
			need.supply.isStackable()), need.origin, need.slot, false);
	}

	private boolean foodItem(int id)
	{
		ItemStats item = player.getItems().get(id);
		if (item != null) { return item.isFood(); }
		com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.ItemDefinition definition = equipmentPlanner.catalogue().getItems().get(id);
		return definition != null && foodPriority(definition.getName()) > 0;
	}

	private void packConfiguredFood(Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		int room = Math.max(0, capacity - slots);
		if (room == 0)
		{
			explanations.add("Food: No slots remain for custom food after required items, reserved boosts and other supplies.");
			return;
		}
		List<String> preferences = request.getFoodOverride().getPreferences();
		List<Integer> ids = new ArrayList<>();
		List<String> unavailable = new ArrayList<>();
		for (String preference : preferences)
		{
			List<Integer> matches = player.getItems().values().stream()
				.filter(item -> player.getOwned().getOrDefault(item.getId(), 0) > 0
					&& item.isFood() && !item.isStackable() && equipmentPlanner.isInventoryItem(item.getId())
					&& foodName(preference).equals(foodName(item.getName()))
					&& equipmentPlanner.supplyProblems(item.getId()).isEmpty()
					&& (allowBlighted || !blightedItem(item.getId())))
				.sorted(Comparator.comparingInt(ItemStats::getId)).map(ItemStats::getId).collect(Collectors.toList());
			if (matches.isEmpty()) { unavailable.add(preference); }
			ids.addAll(matches);
		}
		ids = new ArrayList<>(new LinkedHashSet<>(ids));
		int previous = ids.stream().map(allocations::get).filter(java.util.Objects::nonNull)
			.mapToInt(allocation -> allocation.quantity).sum();
		int target = previous + room;
		int missing;
		if (ids.isEmpty())
		{
			missing = room;
			add(blockers, preferences.isEmpty()
				? "Choose preferred foods in the Food settings, or disable the food override."
				: "No owned usable food matches your override. Open your bank and check the full food names. "
					+ "Use recognised non-stackable food; blighted food needs a Wilderness combat destination.");
			unresolved.add(new Choice(0, 0, 0, 0, missing, "FOOD", "Preferred food", "Configured food", true));
		}
		else
		{
			allocate(new Need(supply("Preferred food", ids, target, true, false), "Configured food", "FOOD", true),
				equipment, blockers, explanations);
			int packed = ids.stream().map(allocations::get).filter(java.util.Objects::nonNull)
				.mapToInt(allocation -> allocation.quantity).sum();
			missing = Math.max(0, target - packed);
			for (int id : ids)
			{
				Allocation allocation = allocations.get(id);
				if (allocation != null)
				{
					allocation.slot = "FOOD";
					allocation.origin = "Configured food";
				}
			}
		}
		if (missing > 0)
		{
			capacity -= missing;
			unresolved.add(new Choice(0, missing, 0, 0, 0, "RESERVED FOOD", "Preferred food", "Configured food", false,
				"Empty space reserved for missing custom food; see Checks."));
		}
		if (!unavailable.isEmpty())
		{
			explanations.add("Food: Unavailable or unsupported for this destination: " + String.join(", ", unavailable) + ".");
		}
		explanations.add("Food: Custom preferences filled " + (room - missing) + "/" + room
			+ " remaining inventory slots in listed order. Required strategy supplies are retained."
			+ (missing > 0 ? " Missing food leaves " + missing + " slots empty; see Checks." : ""));
	}

	private static String foodName(String name)
	{
		String normalized = name.trim().toLowerCase(Locale.ROOT).replaceAll("\\s+", " ");
		return normalized.equals("karambwan") ? "cooked karambwan" : normalized;
	}

	private boolean castingResource(Supply supply)
	{
		return !supply.getItemIds().isEmpty() && supply.getItemIds().stream().allMatch(id ->
			preparation.getRuneIds().containsValue(id) || preparation.getCombinationRunes().containsKey(id)
				|| preparation.getSpells().values().stream().anyMatch(spell -> spell.getSackItemId() == id));
	}

	private List<Supply> aggregateCasting(List<Supply> supplies)
	{
		Map<List<Integer>, Supply> result = new LinkedHashMap<>();
		for (Supply resource : supplies)
		{
			List<Integer> key = new ArrayList<>(resource.getItemIds());
			Supply previous = result.get(key);
			if (previous == null)
			{
				result.put(key, supply(resource.getName(), key, resource.getQuantity(), true, true));
			}
			else
			{
				previous.setQuantity((int) Math.min(Integer.MAX_VALUE, (long) previous.getQuantity() + resource.getQuantity()));
			}
		}
		return new ArrayList<>(result.values());
	}

	private boolean blightedItem(int id)
	{
		ItemStats item = player.getItems().get(id);
		return preparation.getBlightedReplacements().containsValue(id)
			|| item != null && item.getName().toLowerCase(Locale.ROOT).startsWith("blighted ");
	}

	private Supply blightedAlternatives(Supply original)
	{
		if (!allowBlighted) { return original; }
		List<Integer> ids = new ArrayList<>();
		for (int id : original.getItemIds())
		{
			Integer replacement = preparation.getBlightedReplacements().get(id);
			if (replacement != null) { ids.add(replacement); }
			ids.add(id);
		}
		return supply(original.getName(), new ArrayList<>(new LinkedHashSet<>(ids)),
			original.getQuantity(), original.isRequired(), original.isStackable());
	}

	private List<Choice> choices()
	{
		List<Choice> result = new ArrayList<>();
		boolean ownsPouch = preparation.getPouches().stream()
			.anyMatch(pouch -> player.getOwned().getOrDefault(pouch.getItemId(), 0) > 0);
		for (Allocation allocation : allocations.values())
		{
			Choice choice = allocation.choice(carried);
			int inPouch = ownsPouch && player.getDeathContext().isPouchContentsKnown()
				? Math.min(allocation.quantity, player.getDeathContext().getPouchContents().getOrDefault(allocation.id, 0)) : 0;
			String explanation = "RUNE POUCH".equals(allocation.slot)
				? inPouch + " already in pouch; load " + Math.max(0, allocation.quantity - inPouch)
					+ " more to match this configuration. Unload other runes."
				: inPouch > 0 ? "Includes " + inPouch + " runes available to unload from your observed pouch." : "";
			if (inPouch > 0 && preparation.getPouches().stream()
				.noneMatch(pouch -> player.getCarried().getOrDefault(pouch.getItemId(), 0) > 0))
			{
				explanation += " The pouch is banked; withdraw the loaded pouch or unload those runes at the bank.";
			}
			if ("LOOTING BAG".equals(allocation.slot))
			{
				explanation = "Preparation target: empty the bag at a bank before departure. Future loot adds to the planned loss; current contents are assessed separately.";
			}
			result.add(new Choice(choice.getItemId(), choice.getQuantity(), choice.getCarried(), choice.getWithdraw(),
				choice.getMissing(), choice.getSlot(), choice.getName(), choice.getOrigin(), choice.isRequired(), explanation));
		}
		return result;
	}

	private void packRunePouch(Map<String, Choice> equipment, List<String> explanations)
	{
		if (omitOptionalPouch)
		{
			explanations.add("Rune pouch: leave the optional pouch banked; the completed trip has lower Wilderness risk with loose runes.");
			return;
		}
		List<Allocation> runes = allocations.values().stream().filter(a -> a.quantity > 0
			&& (preparation.getRuneIds().containsValue(a.id) || preparation.getCombinationRunes().containsKey(a.id)))
			.collect(Collectors.toList());
		if (runes.size() < 2) { return; }
		boolean packedPouch = allocations.keySet().stream().anyMatch(this::pouchItem);
		List<TripPreparationData.Pouch> pouches = preparation.getPouches().stream()
			.filter(p -> packedPouch ? allocations.containsKey(p.getItemId()) : available.getOrDefault(p.getItemId(), 0) > 0)
			.sorted(Comparator.comparingInt(TripPreparationData.Pouch::getCapacity).reversed())
			.collect(Collectors.toList());
		Scenario looseRisk = equipmentPlanner.riskCalculator().applies()
			? equipmentPlanner.riskCalculator().baseline(equipment, choices()) : null;
		for (TripPreparationData.Pouch pouch : pouches)
		{
			List<Allocation> contained = runes.stream().filter(a -> a.quantity <= pouch.getMaxPerRune())
				.limit(pouch.getCapacity()).collect(Collectors.toList());
			if (contained.size() < 2) { continue; }
			ItemStats stats = player.getItems().get(pouch.getItemId());
			Allocation container = allocations.get(pouch.getItemId());
			boolean added = container == null;
			if (added)
			{
				container = new Allocation(pouch.getItemId(), stats == null ? "Rune pouch" : stats.getName(),
					"SUPPLY", "Trip preparation", false);
				container.quantity = 1;
			}
			allocations.put(container.id, container);
			Map<Allocation, String> priorSlots = new LinkedHashMap<>();
			contained.forEach(a -> { priorSlots.put(a, a.slot); a.slot = "RUNE POUCH"; });
			Scenario pouchRisk = looseRisk == null ? null : equipmentPlanner.riskCalculator().baseline(equipment, choices());
			if (pouchRisk != null && (!pouchRisk.isComplete() || pouchRisk.getPermanentLosses() > looseRisk.getPermanentLosses()
				|| pouchRisk.getTotalRisk() > riskBudget && pouchRisk.getTotalRisk() > looseRisk.getTotalRisk()))
			{
				if (added) { allocations.remove(container.id); }
				priorSlots.forEach((a, slot) -> a.slot = slot);
				continue;
			}
			if (added) { available.computeIfPresent(container.id, (id, count) -> count - 1); }
			int saved = contained.size() - (added ? 1 : 0);
			slots -= saved;
			explanations.add("Rune pouch: " + container.name + " saves " + saved
				+ " inventory slots. Use the exact displayed configuration and unload any extra runes. Capacity " + pouch.getCapacity()
				+ " types, " + pouch.getMaxPerRune() + " per type.");
			return;
		}
		explanations.add("Rune pouch: loose runes retained; no owned pouch can save slots within the verified capacity and Wilderness risk limits.");
	}

	private void packLootingBag(Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		if (!allowBlighted) { return; }
		if (omitOptionalBag)
		{
			explanations.add("Looting bag: leave the optional bag banked; the completed trip has lower Wilderness risk without it.");
			return;
		}
		List<Integer> owned = preparation.getLootingBagIds().stream()
			.filter(id -> allocations.containsKey(id) || available.getOrDefault(id, 0) > 0).collect(Collectors.toList());
		if (owned.isEmpty())
		{
			explanations.add("Looting bag: none observed. Loot must use inventory space freed as supplies are consumed.");
			return;
		}
		if (owned.stream().noneMatch(allocations::containsKey))
		{
			allocate(new Need(supply("Looting bag", owned, 1, false, false), "Trip preparation", "LOOTING BAG", false),
				equipment, blockers, explanations);
		}
		if (owned.stream().noneMatch(allocations::containsKey))
		{
			explanations.add("Looting bag: no spare slot after mandatory items; loot uses freed inventory slots.");
			return;
		}
		owned.stream().map(allocations::get).filter(allocation -> allocation != null)
			.forEach(allocation -> allocation.slot = "LOOTING BAG");
		explanations.add("Looting bag: one inventory slot reserved. Its 28 loot slots cannot supply food, potions or casting runes during the trip.");
		explanations.add("Looting bag: empty the bag at a bank before departure. Planned risk assumes this empty target; future loot adds loss and actual carried contents remain separately assessed.");
		preparation.getLootingBagNotes().forEach(note -> explanations.add("Looting bag: " + note));
	}

	private boolean pouchItem(int id)
	{
		return preparation.getPouches().stream().anyMatch(pouch -> pouch.getItemId() == id);
	}

	private int plannedPouchLimit()
	{
		return preparation.getPouches().stream().filter(pouch -> allocations.containsKey(pouch.getItemId()))
			.mapToInt(TripPreparationData.Pouch::getMaxPerRune).min().orElse(0);
	}

	private void addFallback(String name, List<ItemStats> options, int target,
		Map<String, Choice> equipment, List<String> blockers, List<String> explanations)
	{
		if (target <= 0 || options.isEmpty()) { return; }
		Supply supply = supply(name, options.stream().map(ItemStats::getId).collect(Collectors.toList()), target, false, false);
		allocate(new Need(supply, "Owned fallback", "SUPPLY", false), equipment, blockers, explanations);
	}

	private static int foodPriority(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT).replaceFirst("^blighted ", "");
		if (lower.equals("karambwan")) { lower = "cooked karambwan"; }
		if (lower.startsWith("raw ") || lower.contains("burnt") || lower.contains("noted"))
		{
			return 0;
		}
		String[] foods = {"trout", "salmon", "tuna", "lobster", "bass", "swordfish", "monkfish",
			"cooked karambwan", "shark", "sea turtle", "manta ray", "dark crab", "anglerfish"};
		for (int index = foods.length - 1; index >= 0; index--)
		{
			if (lower.equals(foods[index]))
			{
				return index + 1;
			}
		}
		return 0;
	}

	private boolean waived(Supply supply)
	{
		return supply.getWaiverRequirement() != null
			&& requirements.isMet(supply.getWaiverRequirement());
	}

	private static boolean restoration(String name)
	{
		String lower = name.toLowerCase(Locale.ROOT);
		return (lower.startsWith("prayer potion(") || lower.startsWith("super restore(") || lower.startsWith("blighted super restore("))
			&& !lower.contains("(0)");
	}

	private static int doses(String name)
	{
		java.util.regex.Matcher matcher = java.util.regex.Pattern.compile("\\((\\d)\\)").matcher(name);
		return matcher.find() ? Integer.parseInt(matcher.group(1)) : 0;
	}

	private static Supply supply(String name, List<Integer> ids, int quantity, boolean required, boolean stackable)
	{
		Supply supply = new Supply();
		supply.setName(name);
		supply.setItemIds(ids);
		supply.setQuantity(quantity);
		supply.setRequired(required);
		supply.setStackable(stackable);
		return supply;
	}

	private static void add(List<String> values, String value)
	{
		if (!values.contains(value))
		{
			values.add(value);
		}
	}

	private static final class Attempt
	{
		private final SupplyPlanner planner;
		private final List<Choice> inventory;
		private final List<String> blockers;
		private final List<String> explanations;
		private final Scenario risk;

		private Attempt(SupplyPlanner planner, List<Choice> inventory, List<String> blockers,
			List<String> explanations, Scenario risk)
		{
			this.planner = planner;
			this.inventory = inventory;
			this.blockers = blockers;
			this.explanations = explanations;
			this.risk = risk;
		}
	}

	private static final class Coverage
	{
		private final List<Integer> ids;
		private final int target;

		private Coverage(List<Integer> ids, int target)
		{
			this.ids = ids;
			this.target = target;
		}
	}

	private static final class Fulfillment
	{
		private final int quantity;
		private final long doses;

		private Fulfillment(int quantity, long doses)
		{
			this.quantity = quantity;
			this.doses = doses;
		}
	}

	private static final class Need
	{
		private final Supply supply;
		private final String origin;
		private final String slot;
		private final boolean required;

		private Need(Supply supply, String origin, String slot, boolean required)
		{
			this.supply = supply;
			this.origin = origin;
			this.slot = slot;
			this.required = required;
		}

		private String key()
		{
			return slot + "|" + origin + "|" + supply.getName() + "|" + supply.getItemIds();
		}
	}

	private static final class Allocation
	{
		private final int id;
		private final String name;
		private String slot;
		private String origin;
		private final boolean stackable;
		private int quantity;
		private int missing;
		private boolean required;

		private Allocation(int id, String name, String slot, String origin, boolean stackable)
		{
			this.id = id;
			this.name = name;
			this.slot = slot;
			this.origin = origin;
			this.stackable = stackable;
		}

		private Choice choice(Map<Integer, Integer> carried)
		{
			int carriedCount = Math.min(quantity, carried.getOrDefault(id, 0));
			return new Choice(id, quantity, carriedCount, quantity - carriedCount,
				missing, slot, name, origin, required);
		}
	}
}

package com.danieljglover.allinslayer.loadout.advisor;

import java.util.concurrent.CancellationException;
import java.util.function.BooleanSupplier;

/** A shared worker budget prevents large task families multiplying the gear search without limit. */
final class PreparationWork
{
    private int remaining = 3000;
    private final BooleanSupplier cancelled;

    PreparationWork(BooleanSupplier cancelled)
    {
        this.cancelled = cancelled;
    }

    void checkCancelled()
    {
        if (cancelled.getAsBoolean() || Thread.currentThread().isInterrupted())
        {
            throw new CancellationException("Preparation superseded by newer account or panel state");
        }
    }

    boolean spend()
    {
        checkCancelled();
        if (remaining == 0) { return false; }
        remaining--;
        return true;
    }

    boolean exhausted() { return remaining == 0; }
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.CombatBonus;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.ItemStats;
import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.ItemDefinition;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Location;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Method;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Monster;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Task;
import java.util.List;
import java.util.Locale;

/** Resolves mutually exclusive task/undead bonuses for this target and preparation. */
final class ConditionalBonuses
{
	private final SlayerCatalogue catalogue;
	private final Method method;
	private final boolean onTask;
	private final boolean undead;
	private final boolean preview;

	ConditionalBonuses(SlayerCatalogue catalogue, RecommendationRequest request, Task task,
		Monster monster, Location location, Method method)
	{
		this.catalogue = catalogue;
		this.method = method;
		this.undead = monster.isUndead();
		this.preview = request.isTaskPreview();
		String assignedArea = preview ? null : request.getLockedLocationId();
		this.onTask = request.hasTaskForPlanning()
			&& task.isSlayerHelmApplies() && task.getId().equals(request.getTaskId())
			&& task.getMonsterIds().contains(monster.getId())
			&& (request.getAllowedMonsterIds().isEmpty() || request.getAllowedMonsterIds().contains(monster.getId()))
			&& (!request.isWildernessTaskForPlanning() || location.isWilderness())
			&& (assignedArea == null || assignedArea.equals(location.getId())
				|| assignedArea.equals(location.getAssignmentAreaId()));
	}

	CombatBonus effect(ItemStats item)
	{
		ItemDefinition definition = item == null ? null : catalogue.getItems().get(item.getId());
		return definition == null || definition.getCombatBonus() == null ? CombatBonus.NONE : definition.getCombatBonus();
	}

	double applicable(ItemStats item)
	{
		CombatBonus effect = effect(item);
		return effect.isSlayer() && onTask || effect.isSalve() && undead ? effect.multiplier(method.getStyle()) : 1;
	}

	double multiplier(ItemStats head, ItemStats amulet)
	{
		double salve = applicable(amulet);
		// Wearing both is legal, including when the helmet supplies mandatory protection.
		// An applicable Salve effect takes priority; never add or multiply the two effects.
		return salve > 1 ? salve : applicable(head);
	}

	double rankingMultiplier(ItemStats head, ItemStats amulet, ItemStats weapon)
	{
		// Do not value Salve as an all-target boost for barrage/chinchompa preparations.
		return areaAttack(weapon) && applicable(amulet) > 1 ? 1 : multiplier(head, amulet);
	}

	void explain(ItemStats head, ItemStats amulet, ItemStats weapon, List<String> explanations)
	{
		double salve = applicable(amulet);
		double slayer = applicable(head);
		if (salve > 1)
		{
			explanations.add(amulet.getName() + ": +" + percent(salve) + "% " + method.getStyle().toLowerCase(Locale.ROOT)
				+ " accuracy and damage against this undead variant. Salve and Slayer helmet/Black mask boosts do not stack."
				+ (slayer > 1 ? " The helmet's task boost is suppressed; its equipment stats and protection remain." : ""));
			if (areaAttack(weapon))
			{
				explanations.add("Salve boosts only the primary ranged/magic target. Its boost is not credited to secondary targets when comparing this area method's head and amulet.");
			}
		}
		else if (slayer > 1)
		{
			explanations.add(head.getName() + ": +" + percent(slayer) + "% " + method.getStyle().toLowerCase(Locale.ROOT)
				+ (preview ? " accuracy and damage assuming the selected Catalogue task and location. This is a planning assumption."
					: " accuracy and damage for this matching active Slayer task and assigned area."));
		}
		if (effect(head).isSlayer() && slayer == 1)
		{
			explanations.add(head.getName() + (onTask
				? ": the unimbued form has no ranged or magic task boost."
				: ": no task boost applies to this preview, target or location."));
		}
		if (effect(amulet).isSalve() && salve == 1)
		{
			explanations.add(amulet.getName() + (undead
				? ": this unimbued form has no ranged or magic undead boost."
				: ": this target variant is not flagged undead; no Salve boost is applied."));
		}
		if (method.isCannon() && (slayer > 1 || salve > 1))
		{
			explanations.add("These target-specific boosts apply to your own attacks; no Slayer/Salve accuracy boost is credited to the cannon.");
		}
	}

	private boolean areaAttack(ItemStats weapon)
	{
		return method.isBarrage() || "RANGED".equalsIgnoreCase(method.getStyle()) && weapon != null
			&& weapon.getName().toLowerCase(Locale.ROOT).contains("chinchompa");
	}

	private static String percent(double multiplier)
	{
		return multiplier == 7.0 / 6.0 ? "16.67" : Integer.toString((int) Math.round((multiplier - 1) * 100));
	}
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.RecommendationGoal;
import com.danieljglover.allinslayer.model.advisor.WildernessRisk;
import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Choice;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Setup;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Evidence;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Location;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Master;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Method;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Monster;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Supply;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Task;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/** Pure, deterministic recommendations from bundled knowledge and an immutable player snapshot. */
public final class RecommendationEngine
{
	public RecommendationResult recommend(SlayerCatalogue catalogue, RecommendationRequest request)
	{
		return recommend(catalogue, request, () -> false);
	}

	public RecommendationResult recommend(SlayerCatalogue catalogue, RecommendationRequest request,
		java.util.function.BooleanSupplier cancelled)
	{
		PreparationWork work = new PreparationWork(cancelled);
		List<String> notices = new ArrayList<>();
		if (request == null)
		{
			return new RecommendationResult(null, Collections.emptyList(),
				Collections.singletonList("Select a Slayer task to build a recommendation."));
		}
		if (catalogue == null)
		{
			return new RecommendationResult(request.getTaskId(), Collections.emptyList(),
				Collections.singletonList("The bundled Slayer catalogue is unavailable."));
		}
		Task task = catalogue.getTasks().get(request.getTaskId());
		if (task == null)
		{
			return new RecommendationResult(request.getTaskId(), Collections.emptyList(),
				Collections.singletonList(request.getTaskId() == null ? "Select a task from the Slayer catalogue."
					: "This Slayer assignment has no matching bundled task record: " + request.getTaskId() + "."));
		}
		if (!request.getPlayer().isLoggedIn())
		{
			notices.add("Log in to verify levels and equipment. The catalogue remains available for planning.");
		}
		if (request.getPlayer().getBankSeenAt() == 0)
		{
			notices.add("Open your bank to include banked items. Ownership currently covers only observed carried equipment and inventory.");
		}
		else
		{
			notices.add("Bank ownership uses the last observed bank. Reopen it after bank changes or account changes.");
		}
		if (!request.isActiveTask())
		{
			notices.add("On-task preview: the selected assignment is assumed for Slayer bonuses and task-only preparations. Your detected task is unchanged; levels, quests, unlocks and Wilderness loss are still checked.");
		}
		if (request.isWildernessTaskForPlanning() && !request.isAllowWilderness())
		{
			notices.add("This assignment requires Wilderness kills. Enable Allow Wilderness to see preparations for it; no location is recommended while it is disabled.");
			return new RecommendationResult(task.getId(), Collections.emptyList(), notices);
		}
		if (request.getMasterId() != null && !task.getMasterIds().contains(request.getMasterId()))
		{
			if (!request.isActiveTask() || !request.getPlayer().isLoggedIn() || request.getRemaining() <= 0)
			{
				notices.add("This task is not listed for the selected Slayer master.");
				return new RecommendationResult(task.getId(), Collections.emptyList(), notices);
			}
			// A live assignment can outlast a master-table update or precede a bundled data
			// refresh. Its master link is not an access gate for killing the assigned monster.
			notices.add("Using your detected active assignment; the catalogue's Slayer master list for this task needs updating.");
		}
		List<RankedSetup> ranked = new ArrayList<>();
		boolean excludedWilderness = false;
		for (String monsterId : task.getMonsterIds())
		{
			if (!request.getAllowedMonsterIds().isEmpty() && !request.getAllowedMonsterIds().contains(monsterId))
			{
				continue;
			}
			if (request.getMonsterId() != null && !request.getMonsterId().equals(monsterId))
			{
				continue;
			}
			Monster monster = catalogue.getMonsters().get(monsterId);
			if (monster == null)
			{
				notices.add("Missing monster record: " + monsterId + ".");
				continue;
			}
			if (!monster.isRepeatable())
			{
				if (request.getMonsterId() != null)
				{
					notices.add(monster.getName() + " is an incidental encounter. Its task information remains available, but it has no repeatable trip recommendation.");
				}
				continue;
			}
			Set<String> methodIds = new LinkedHashSet<>(monster.getMethodIds());
			catalogue.getMethods().values().stream().filter(method -> method.getMonsterIds().contains(monsterId))
				.forEach(method -> methodIds.add(method.getId()));
			List<String> locationIds = monster.getLocationIds().isEmpty() ? task.getLocationIds() : monster.getLocationIds();
			if (methodIds.isEmpty())
			{
				notices.add(monster.getName() + ": no combat method has been compiled; read the task guidance.");
			}
			for (String methodId : methodIds)
			{
				if (request.getMethodId() != null && !request.getMethodId().equals(methodId))
				{
					continue;
				}
				Method method = catalogue.getMethods().get(methodId);
				if (method == null || !method.isSelectable()
					|| !method.getMonsterIds().isEmpty() && !method.getMonsterIds().contains(monsterId))
				{
					continue;
				}
				for (String locationId : new LinkedHashSet<>(locationIds))
				{
					if (request.getLocationId() != null && !request.getLocationId().equals(locationId)
						|| !method.getLocationIds().isEmpty() && !method.getLocationIds().contains(locationId))
					{
						continue;
					}
					Location base = catalogue.getLocations().get(locationId);
					Location location = task.getLocationOverrides().getOrDefault(locationId, base);
					if (location == null)
					{
						notices.add("Missing location record: " + locationId + ".");
						continue;
					}
					// Disabled locations are not automatic candidates, even if every owned setup
					// has missing gear. An explicitly selected location can still explain its blocker.
					if (wildernessRisk(catalogue, location) && !request.isAllowWilderness() && request.getLocationId() == null)
					{
						excludedWilderness = true;
						continue;
					}
					if (request.isWildernessTaskForPlanning() && !location.isWilderness())
					{
						continue;
					}
					work.checkCancelled();
					Setup setup = setup(catalogue, request, task, monster, location, method, work);
					ranked.add(new RankedSetup(setup, rank(method, request.getGoal()),
						wildernessRisk(catalogue, location) ? 1 : 0, method.isGroup() ? 1 : 0));
				}
			}
		}
		ranked.sort(Comparator.comparing((RankedSetup value) -> !value.setup.isFeasible())
			.thenComparingInt(value -> value.priority)
			.thenComparingInt(value -> value.wilderness)
			.thenComparingLong(value -> value.setup.getWildernessRisk() == null ? 0
				: value.setup.getWildernessRisk().baseline().getTotalRisk())
			.thenComparingInt(value -> value.group)
			.thenComparingInt(value -> value.setup.getBlockers().size())
			.thenComparingInt(value -> (int) value.setup.getEquipment().values().stream()
				.filter(choice -> "Owned fallback".equals(choice.getOrigin())).count())
			.thenComparing(value -> value.setup.getMonsterId())
			.thenComparing(value -> value.setup.getLocationId())
			.thenComparing(value -> value.setup.getMethodId()));
		if (work.exhausted())
		{
			notices.add("The task-wide Wilderness comparison limit was reached. Select a monster or location to focus the owned-alternative search. Displayed costs are still assessed; an optimal loadout is not guaranteed.");
		}
		if (excludedWilderness)
		{
			notices.add("Wilderness locations are excluded from automatic recommendations. Enable Allow Wilderness to include them.");
		}
		if (ranked.isEmpty())
		{
			notices.add("No compiled monster, location and combat-method combination matches these selections. Clear a filter or inspect the source coverage notes.");
		}
		else if (ranked.stream().noneMatch(value -> value.setup.isFeasible()))
		{
			notices.add("No setup is currently verified as feasible. Review the listed requirements, missing gear and access confirmations.");
		}
		notices.add("Goals use relative source priorities; hourly XP, kill speed and profit are not measured. Wilderness losses use cached item prices.");
		return new RecommendationResult(task.getId(), ranked.stream().map(value -> value.setup).collect(Collectors.toList()),
			new ArrayList<>(new LinkedHashSet<>(notices)));
	}

	private Setup setup(SlayerCatalogue catalogue, RecommendationRequest request, Task task,
		Monster monster, Location location, Method method, PreparationWork work)
	{
		List<String> blockers = new ArrayList<>();
		List<String> explanations = new ArrayList<>();
		List<String> guidance = new ArrayList<>(task.getNotes());
		guidance.addAll(location.getNotes());
		guidance.addAll(method.getGuidance());
		method.getRisks().forEach(risk -> guidance.add("Risk: " + risk));
		RequirementEvaluator evaluator = new RequirementEvaluator(request, monster.getId());
		if (!request.getPlayer().isLoggedIn())
		{
			blockers.add("Player state is unavailable while logged out.");
		}
		evaluator.level("SLAYER", Math.max(task.getSlayerLevel(), monster.getSlayerLevel()), blockers);
		evaluator.checkAll(task.getRequirements(), blockers);
		evaluator.checkAll(monster.getRequirements(), blockers);
		evaluator.checkAll(location.getRequirements(), blockers);
		SpellPlanner spellPlanner = new SpellPlanner(catalogue.getPreparation(), request);
		evaluator.checkAll(method.getRequirements().stream().filter(requirement -> !spellPlanner.managesRequirement(requirement))
			.collect(Collectors.toList()), blockers);
		Master master = catalogue.getMasters().get(request.getMasterId());
		if (master != null && !request.isActiveTask())
		{
			evaluator.level("COMBAT", master.getCombatLevel(), blockers);
			evaluator.level("SLAYER", master.getSlayerLevel(), blockers);
			evaluator.checkAll(master.getRequirements(), blockers);
		}
		if ((location.isTaskOnly() || method.isTaskOnly()) && !request.hasTaskForPlanning())
		{
			blockers.add("Requires an active matching Slayer task.");
		}
		if (request.isActiveTask() && request.getLockedLocationId() != null
			&& !request.getLockedLocationId().equals(location.getId())
			&& !request.getLockedLocationId().equals(location.getAssignmentAreaId()))
		{
			blockers.add("Your active task is locked to " + locationName(catalogue, request.getLockedLocationId()) + ".");
		}
		if (request.isWildernessTaskForPlanning() && !location.isWilderness())
		{
			blockers.add("This Wilderness assignment only counts eligible Wilderness kills.");
		}
		if (wildernessRisk(catalogue, location) && !request.isAllowWilderness())
		{
			blockers.add("Wilderness setups are disabled. Enable Wilderness options to include this setup.");
		}
		if (method.isGroup() && !request.isAllowGroups())
		{
			blockers.add("Group methods are disabled. Enable group options to include this setup.");
		}
		if (method.isCannon() && !location.isCannon())
		{
			blockers.add("This location does not support the method's cannon.");
		}
		if (method.isCannon())
		{
			evaluator.checkAll(Collections.singletonList("Dwarf Cannon"), blockers);
		}
		if (method.isBarrage() && (!location.isBarrage() || !location.isMulti()))
		{
			blockers.add("This location does not support the method's multi-target barrage setup.");
		}
		if (method.getEquipment().isEmpty())
		{
			explanations.add("No Wiki equipment priorities were compiled for this method; all gear uses labelled owned fallbacks.");
		}
		if (method.getCoverageStatus() != null)
		{
			explanations.add("Source coverage: " + method.getCoverageStatus());
		}
		int sourceRank = rank(method, request.getGoal());
		explanations.add(sourceRank == Integer.MAX_VALUE
			? "Goal: " + request.getGoal() + ". This method is unrated; placed after methods with a source priority."
			: "Goal: " + request.getGoal() + "; relative source priority " + sourceRank + ".");
		if (method.getRankingReason() != null && !method.getRankingReason().isEmpty())
		{
			explanations.add(method.getRankingReason());
		}
		List<Supply> required = new ArrayList<>(task.getRequiredItems());
		required.addAll(location.getRequiredItems());
		required.addAll(method.getRequiredItems());
		required.removeIf(supply -> waived(supply, request));
		if (method.isBarrage() && !spellPlanner.hasDocumentedBarrageSpell(method))
		{
			blockers.add("This barrage method lacks a reviewed explicit spell baseline; its source plan needs review.");
		}
		EquipmentPlanner equipmentPlanner = new EquipmentPlanner(catalogue, request, task, monster, location, method, work);
		Map<String, Choice> equipment = equipmentPlanner.plan(required, blockers, explanations);
		SupplyPlanner supplies = new SupplyPlanner(request, equipmentPlanner, equipment);
		List<Choice> inventory = supplies.planOptimized(method, location, required, equipment, blockers, explanations);
		WildernessRisk risk = null;
		WildernessRiskCalculator riskCalculator = equipmentPlanner.riskCalculator();
		if (riskCalculator.applies())
		{
			risk = riskCalculator.assess(equipment, inventory, request.getWildernessRiskBudget());
			if (risk.baseline().getPermanentLosses() > 0)
			{
				blockers.add("This setup risks permanent loss of an untradeable item or component. Use a protected or locked alternative.");
			}
			if (!risk.baseline().isComplete())
			{
				blockers.add("Wilderness loss cannot be fully valued for this setup. Review its unknown death rules, prices or stored charges in Wilderness death risk.");
			}
			if (risk.baseline().getTotalRisk() > request.getWildernessRiskBudget())
			{
				blockers.add("Estimated Wilderness loss exceeds the " + request.getWildernessRiskBudget()
					+ " gp budget. Adjust the loss budget in plugin configuration or choose another setup.");
			}
		}

		List<Evidence> evidence = new ArrayList<>(task.getEvidence());
		evidence.addAll(monster.getEvidence());
		evidence.addAll(location.getEvidence());
		evidence.addAll(method.getEvidence());
		if (risk != null)
		{
			if (catalogue.getWildernessAreas().containsKey(location.getId()))
			{
				evidence.addAll(catalogue.getWildernessAreas().get(location.getId()).getEvidence());
			}
			java.util.Set<Integer> riskIds = new LinkedHashSet<>(WildernessRiskCalculator.quantities(equipment, inventory).keySet());
			riskIds.addAll(request.getPlayer().getRiskCarried().keySet());
			riskIds.stream().map(catalogue.getDeathRules()::get).filter(java.util.Objects::nonNull)
				.forEach(rule -> evidence.addAll(rule.getEvidence()));
		}
		Map<String, Evidence> uniqueEvidence = new LinkedHashMap<>();
		for (Evidence source : evidence)
		{
			uniqueEvidence.put(source.getUrl() + "#" + source.getRevisionId(), source);
		}
		return new Setup(monster.getId(), location.getId(), method.getId(),
			monster.getName() + " - " + location.getName() + " - " + method.getName(),
			method.getSummary(), blockers.isEmpty(), equipment, inventory,
			new ArrayList<>(new LinkedHashSet<>(explanations)), new ArrayList<>(new LinkedHashSet<>(blockers)),
			new ArrayList<>(new LinkedHashSet<>(guidance)), new ArrayList<>(uniqueEvidence.values()), risk);
	}

	private static boolean wildernessRisk(SlayerCatalogue catalogue, Location location)
	{
		return location.isWilderness() || catalogue.getWildernessAreas().containsKey(location.getId())
			&& catalogue.getWildernessAreas().get(location.getId()).isWildernessTravel();
	}

	private static int rank(Method method, RecommendationGoal goal)
	{
		int value = goal == RecommendationGoal.PROFIT ? method.getProfitRank()
			: goal == RecommendationGoal.LOW_EFFORT ? method.getEffortRank() : method.getXpRank();
		return value > 0 ? value : Integer.MAX_VALUE;
	}

	private static boolean waived(Supply supply, RecommendationRequest request)
	{
		return supply.getWaiverRequirement() != null
			&& new RequirementEvaluator(request).isMet(supply.getWaiverRequirement());
	}

	private static String locationName(SlayerCatalogue catalogue, String id)
	{
		Location location = catalogue.getLocations().get(id);
		return location == null ? id : location.getName();
	}

	private static final class RankedSetup
	{
		private final Setup setup;
		private final int priority;
		private final int wilderness;
		private final int group;

		private RankedSetup(Setup setup, int priority, int wilderness, int group)
		{
			this.setup = setup;
			this.priority = priority;
			this.wilderness = wilderness;
			this.group = group;
		}
	}
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.ReturnDestination;
import com.danieljglover.allinslayer.model.advisor.ItemValue;
import com.danieljglover.allinslayer.model.advisor.AccountProgress;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.ItemStats;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Choice;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Location;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.ItemDefinition;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Supply;
import com.danieljglover.allinslayer.model.advisor.TripPreparationData;
import com.danieljglover.allinslayer.model.advisor.TripPreparationData.Teleport;
import com.danieljglover.allinslayer.model.advisor.WildernessArea;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.LinkedHashSet;
import java.util.Set;
import lombok.Value;

/** Plans portable return/abort resources. It never invokes a teleport or changes a route. */
final class TripTravelPlanner
{
    private final SlayerCatalogue catalogue;
    private final TripPreparationData data;
    private final RecommendationRequest request;
    private final RequirementEvaluator requirements;
    private final SpellPlanner spells;

    TripTravelPlanner(SlayerCatalogue catalogue, RecommendationRequest request)
    {
        this.catalogue = catalogue;
        this.data = catalogue.getPreparation();
        this.request = request;
        this.requirements = new RequirementEvaluator(request);
        this.spells = new SpellPlanner(data, request);
    }

    @Value
    static class TravelPlan
    {
        List<Supply> supplies;
        List<Supply> runes;
        List<String> notes;
        List<String> blockers;
    }

    TravelPlan plan(Location location, Map<String, Choice> equipment)
    {
        return plan(location, equipment, Collections.emptyList());
    }

    TravelPlan plan(Location location, Map<String, Choice> equipment, List<Supply> reservedCasting)
    {
        List<Supply> supplies = new ArrayList<>();
        List<Supply> runes = new ArrayList<>();
        List<String> notes = new ArrayList<>();
        List<String> blockers = new ArrayList<>();
        Map<Integer, Integer> remaining = new LinkedHashMap<>(request.getPlayer().getOwned());
        reserve(remaining, reservedCasting);
        ReturnDestination target = request.getReturnDestination();
        List<String> routes = target == ReturnDestination.HOUSE ? data.getHouseRoutes()
            : target == ReturnDestination.BANK ? data.getBankRoutes()
            : data.getMasterRoutes().getOrDefault(request.getMasterId(), Collections.emptyList());
        Option back = firstOption(routes, location, equipment, remaining);
        boolean bankFallback = back == null && target == ReturnDestination.SLAYER_MASTER;
        if (bankFallback) { back = firstOption(data.getBankRoutes(), location, equipment, remaining); }
        if (back != null) { reserve(remaining, back.runes); }
        boolean deferredReturn = false;
        WildernessArea area = catalogue.getWildernessAreas().get(location.getId());
        boolean wilderness = location.isWilderness() || area != null && area.isWildernessTravel();
        if (wilderness)
        {
            int maxLevel = area == null ? -1 : area.getMaxLevel();
            final Option returnOption = back;
            List<Option> escapes = new ArrayList<>();
            for (Teleport teleport : data.getTeleports().values())
            {
                if (!teleport.isEmergency()) { continue; }
                // Reuse the already-reserved return cast for the alternative abort outcome.
                Option option = back != null && back.teleport.getId().equals(teleport.getId())
                    ? back : option(teleport, location, equipment, remaining);
                if (option != null) { escapes.add(option); }
            }
            // Above level 20 (or with unknown depth), retain the broader level-30 exit.
            escapes.sort(Comparator.comparingInt((Option o) ->
                (maxLevel < 0 || maxLevel > 20) && o.teleport.getWildernessLimit() < 30 ? 1 : 0)
                .thenComparingInt(o -> o.teleport.getEscapePriority())
                .thenComparingInt(o -> returnOption != null && o.itemId > 0 && o.itemId == returnOption.itemId ? 0 : 1));
            if (escapes.isEmpty())
            {
                String missing = "Escape: no verified owned and usable emergency teleport remains after reserving combat and return resources. Arrange one before entering the Wilderness.";
                notes.add(missing);
                blockers.add(missing);
            }
            else
            {
                Option escape = escapes.get(0);
                if (escape.teleport.isBankNearby())
                {
                    if (target == ReturnDestination.BANK || bankFallback
                        || target == ReturnDestination.SLAYER_MASTER && routes.contains(escape.teleport.getId())
                            && (back == null || !back.teleport.isRemoteContact()))
                    {
                        // One portable exit can serve both roles when its destination already fits.
                        back = escape;
                    }
                    else if (target == ReturnDestination.SLAYER_MASTER && back != null
                        && !back.teleport.isRemoteContact() && !back.runes.isEmpty()
                        && !sharesReturnUse(back, escape))
                    {
                        // Collect onward spell resources at the escape destination's bank instead
                        // of carrying multiple extra rune stacks through Wilderness combat.
                        notes.add("Return: use " + escape.teleport.getName() + " and bank near "
                            + escape.teleport.getDestination() + ". Collect the runes"
                            + (back.accessItem > 0 ? " and " + catalogue.getItems().get(back.accessItem).getName() : "")
                            + " for "
                            + back.teleport.getName() + " there before continuing to your Slayer master."
                            + " Onward teleport resources are not packed for this trip. "
                            + safe(back.teleport.getNote()));
                        appendConfigurationNotes(back, "Return: ", notes);
                        back = null;
                        deferredReturn = true;
                    }
                }
                // Finishing and aborting are alternative outcomes; one remaining use can serve both.
                if (!sharesReturnUse(back, escape))
                {
                    pack(escape, supplies, runes);
                }
                notes.add("Escape: " + escape.teleport.getName() + " works at Wilderness level "
                    + escape.teleport.getWildernessLimit() + " or below. "
                    + (maxLevel < 0 || maxLevel > escape.teleport.getWildernessLimit()
                        ? "Leave the boss arena if necessary and retreat within that limit before teleporting. " : "")
                    + safe(escape.teleport.getNote()));
                Set<String> mechanisms = new LinkedHashSet<>();
                mechanisms.add(mechanism(escape));
                List<String> alternatives = new ArrayList<>();
                for (Option alternative : escapes)
                {
                    if (mechanisms.add(mechanism(alternative)))
                    {
                        alternatives.add(alternative.teleport.getName() + " (level "
                            + alternative.teleport.getWildernessLimit() + ")");
                    }
                    if (alternatives.size() == 3) { break; }
                }
                if (!alternatives.isEmpty())
                {
                    notes.add("Escape: owned alternatives, not additionally packed: "
                        + String.join("; ", alternatives) + ".");
                }
            }
            for (String note : data.getWildernessEscapeNotes()) { notes.add("Escape: " + note); }
            if (back != null && !back.teleport.isRemoteContact())
            {
                notes.add("Return: this teleport also requires Wilderness level " + back.teleport.getWildernessLimit()
                    + " or below; leave restricted areas first.");
            }
        }
        if (back != null)
        {
            pack(back, supplies, runes);
            String master = catalogue.getMasters().containsKey(request.getMasterId())
                ? catalogue.getMasters().get(request.getMasterId()).getName() : "your Slayer master";
            String purpose = target == ReturnDestination.HOUSE ? "your house"
                : target == ReturnDestination.BANK || bankFallback ? "banking" : master;
            notes.add("Return: " + back.teleport.getName() + " for " + purpose + ". "
                + (back.teleport.isRemoteContact() ? "Request the next assignment remotely. " : "")
                + (back.teleport.isBankNearby() ? "A bank is nearby. " : "")
                + safe(back.teleport.getNote()));
            appendConfigurationNotes(back, "Return: ", notes);
            if (bankFallback)
            {
                notes.add("Return: no usable direct route to " + master
                    + " was found; bank first, then arrange the next-assignment journey.");
            }
        }
        else if (!deferredReturn)
        {
            notes.add("Return: no owned and unlocked " + target.toString().toLowerCase(java.util.Locale.ROOT)
                + " return option is available. Check teleport stock and unlocks before leaving.");
            if (target == ReturnDestination.HOUSE && !requirements.isMet("Own a player-owned house"))
            {
                blockers.add("Confirm requirement: Own a player-owned house");
            }
        }
        return new TravelPlan(supplies, runes, notes, blockers);
    }

    private Option firstOption(List<String> ids, Location location, Map<String, Choice> equipment,
        Map<Integer, Integer> remaining)
    {
        for (String id : ids)
        {
            Option option = option(data.getTeleports().get(id), location, equipment, remaining);
            if (option != null) { return option; }
        }
        return null;
    }

    private void appendConfigurationNotes(Option option, String prefix, List<String> notes)
    {
        Set<String> sources = new LinkedHashSet<>();
        for (String requirement : option.teleport.getRequirements())
        {
            String source = request.getPlayer().getAccountProgress().getConfiguredRequirements()
                .get(AccountProgress.key(requirement));
            if (source != null) { sources.add(source); }
        }
        for (String source : sources) { notes.add(prefix + source + " Imported configuration, not observed furniture."); }
    }

    private static String mechanism(Option option)
    {
        return option.itemId > 0 ? "item:" + option.itemId : "spell:" + option.teleport.getSpellName();
    }

    private Option option(Teleport teleport, Location location, Map<String, Choice> equipment,
        Map<Integer, Integer> remaining)
    {
        if (teleport == null || teleport.getRequirements().stream().anyMatch(r -> !requirements.isMet(r))) { return null; }
        int accessItem = teleport.getRequiredItemIds().stream()
            .filter(id -> request.getPlayer().getOwned().getOrDefault(id, 0) > 0)
            .filter(this::helperUsable).findFirst().orElse(0);
        if (!teleport.getRequiredItemIds().isEmpty() && accessItem == 0) { return null; }
        if (teleport.getSpellName() != null)
        {
            TripPreparationData.Spell spell = data.getSpells().get(teleport.getSpellName());
            if (spell == null || !spells.problems(spell, equipment).isEmpty()) { return null; }
            List<Supply> runes = spells.suppliesFor(spell, 1, equipment, false, remaining);
            if (runes.stream().anyMatch(s -> s.getItemIds().stream().mapToLong(id ->
                remaining.getOrDefault(id, 0)).sum() < s.getQuantity())) { return null; }
            return new Option(teleport, 0, 1, accessItem, runes);
        }
        List<Integer> variants = new ArrayList<>(teleport.getItemIds());
        variants.sort(Comparator.comparingInt((Integer id) -> equipment.values().stream()
            .anyMatch(choice -> choice.getItemId() == id && choice.getMissing() == 0 && choice.getQuantity() > 0) ? 0 : 1)
            // An eternal or ornamented piece is not worth risking merely for a spare teleport.
            .thenComparingLong(this::itemPrice)
            .thenComparingInt(id -> teleport.getCharges().getOrDefault(id, -1) == 0
                ? Integer.MIN_VALUE : -teleport.getCharges().getOrDefault(id, -1)));
        for (int id : variants)
        {
            if (request.getPlayer().getOwned().getOrDefault(id, 0) <= 0) { continue; }
            // Do not spend the sole charge/item on the outward journey and promise it again for return.
            int outward = location.getTravel().stream().filter(s -> s.getItemIds().contains(id))
                .mapToInt(s -> Math.max(1, s.getQuantity())).max().orElse(0);
            int charges = teleport.getCharges().getOrDefault(id, -1);
            int count = teleport.isConsumable() ? outward + 1 : 1;
            if (charges < 0 || charges > 0 && !teleport.isConsumable() && charges <= outward
                || request.getPlayer().getOwned().getOrDefault(id, 0) < count) { continue; }
            return new Option(teleport, id, count, accessItem, Collections.emptyList());
        }
        return null;
    }

    private long itemPrice(int id)
    {
        ItemValue value = request.getPlayer().getItemValues().get(id);
        return value == null || value.getMarketPrice() < 0 ? Long.MAX_VALUE : value.getMarketPrice();
    }

    private boolean helperUsable(int id)
    {
        ItemStats stats = request.getPlayer().getItems().get(id);
        ItemDefinition definition = catalogue.getItems().get(id);
        if (stats == null || !stats.isUsable() || definition == null || !definition.isUsable()) { return false; }
        if (!definition.isRequirementsKnown() && !requirements.isMet("Can equip: " + definition.getName())) { return false; }
        return definition.getLevels().entrySet().stream()
            .allMatch(level -> requirements.isMet(level.getKey() + " >= " + level.getValue()))
            && definition.getRequirements().stream().allMatch(requirements::isMet);
    }

    private static boolean sharesReturnUse(Option back, Option escape)
    {
        if (back == null) { return false; }
        if (back.itemId > 0) { return back.itemId == escape.itemId; }
        return back.teleport.getSpellName() != null
            && back.teleport.getSpellName().equals(escape.teleport.getSpellName());
    }

    private static void reserve(Map<Integer, Integer> remaining, List<Supply> supplies)
    {
        for (Supply supply : supplies)
        {
            int missing = Math.max(0, supply.getQuantity());
            for (int id : supply.getItemIds())
            {
                int owned = remaining.getOrDefault(id, 0);
                int used = Math.min(missing, owned);
                remaining.put(id, owned - used);
                missing -= used;
                if (missing == 0) { break; }
            }
        }
    }

    private void pack(Option option, List<Supply> supplies, List<Supply> runes)
    {
        if (option.itemId > 0) { supplies.add(item(option.teleport.getName(), option.itemId, option.quantity)); }
        if (option.accessItem > 0) { supplies.add(item("Return route access item", option.accessItem, 1)); }
        runes.addAll(option.runes);
    }

    private static Supply item(String name, int id, int quantity)
    {
        Supply supply = new Supply();
        supply.setName(name);
        supply.setItemIds(Collections.singletonList(id));
        supply.setQuantity(quantity);
        supply.setRequired(true);
        return supply;
    }

    private static String safe(String text) { return text == null ? "" : text; }

    @Value
    private static class Option
    {
        Teleport teleport;
        int itemId;
        int quantity;
        int accessItem;
        List<Supply> runes;
    }
}

package com.danieljglover.allinslayer.loadout.advisor;

import com.danieljglover.allinslayer.model.advisor.AccountProgress.State;
import com.danieljglover.allinslayer.model.advisor.ChargeObservation;
import com.danieljglover.allinslayer.model.advisor.DeathContext;
import com.danieljglover.allinslayer.model.advisor.DeathRule;
import com.danieljglover.allinslayer.model.advisor.DepartureCheck;
import com.danieljglover.allinslayer.model.advisor.DepartureCheck.Entry;
import com.danieljglover.allinslayer.model.advisor.ItemValue;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot;
import com.danieljglover.allinslayer.model.advisor.PreparationSnapshot;
import com.danieljglover.allinslayer.model.advisor.RecommendationRequest;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Choice;
import com.danieljglover.allinslayer.model.advisor.RecommendationResult.Setup;
import com.danieljglover.allinslayer.model.advisor.SlayerCatalogue;
import com.danieljglover.allinslayer.model.advisor.WildernessRisk;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.LinkedHashSet;

/** Compares the selected plan with physical placement, never with estimated bank ownership. */
public final class DepartureEvaluator
{
    private DepartureEvaluator() { }

    public static DepartureCheck assess(SlayerCatalogue catalogue, RecommendationRequest request,
        Setup setup, Map<String, RequirementEvaluator.Assessment> requirements)
    {
        List<Entry> entries = new ArrayList<>();
        PlayerSnapshot player = request.getPlayer();
        PreparationSnapshot actual = player.getPreparation();
        if (!player.isLoggedIn() || !actual.isKnown())
        {
            entries.add(new Entry("Waiting for current items", "Log in to check your worn equipment and backpack.", true));
            return new DepartureCheck(entries);
        }

        Map<Integer, Integer> inventory = canonicalQuantities(actual.getInventory(), actual);
        for (Map.Entry<String, Choice> slot : setup.getEquipment().entrySet())
        {
            Choice choice = slot.getValue();
            if (!physical(choice)) { continue; }
            int id = actual.canonicalId(choice.getItemId());
            PreparationSnapshot.Stack worn = actual.getEquipment().get(slot.getKey());
            int equipped = worn != null && actual.canonicalId(worn.getItemId()) == id ? worn.getQuantity() : 0;
            int remaining = Math.max(0, choice.getQuantity() - equipped);
            if (remaining > 0)
            {
                entries.add(new Entry("Equip " + amount(choice.getName(), remaining),
                    "Required in " + slot.getKey().toLowerCase(Locale.ROOT) + ". "
                        + availability(choice, remaining, inventory.getOrDefault(id, 0)), false));
                // A copy waiting to be equipped cannot also satisfy an inventory switch or supply.
                take(inventory, id, remaining);
            }
        }
        for (Choice choice : setup.getInventory())
        {
            if (!physical(choice)) { continue; }
            int remaining = choice.getQuantity() - take(inventory, actual.canonicalId(choice.getItemId()), choice.getQuantity());
            if (remaining > 0)
            {
                entries.add(new Entry("Pack " + amount(choice.getName(), remaining),
                    "Backpack is short of this quantity. " + availability(choice, remaining, 0), false));
            }
        }
        pouch(catalogue, setup, player, entries);
        charges(catalogue, setup, request, entries);
        wilderness(catalogue, setup, player, entries);

        requirements.forEach((name, assessment) -> {
            if (assessment.getState() != State.MET || assessment.isAssumed())
            {
                entries.add(new Entry(assessment.isAssumed() ? "Check assignment access" : name,
                    assessment.getDetail(), true));
            }
        });
        for (String blocker : setup.getBlockers())
        {
            if (requirements.keySet().stream().anyMatch(blocker::contains)) { continue; }
            // Missing item rows above already give the actual quantity and destination.
            if (blocker.startsWith("Missing") && choices(setup).stream().anyMatch(c -> blocker.contains(c.getName()))) { continue; }
            entries.add(new Entry("Resolve setup blocker", blocker, true));
        }
        if (!setup.isFeasible() && entries.isEmpty())
        {
            entries.add(new Entry("Review setup", "The selected recommendation is not currently feasible.", true));
        }
        return new DepartureCheck(entries);
    }

    private static void pouch(SlayerCatalogue catalogue, Setup setup, PlayerSnapshot player, List<Entry> entries)
    {
        Map<Integer, Integer> planned = new LinkedHashMap<>();
        setup.getInventory().stream().filter(c -> "RUNE POUCH".equals(c.getSlot()) && c.getQuantity() > 0)
            .forEach(c -> planned.merge(c.getItemId(), c.getQuantity(), DepartureEvaluator::add));
        boolean selected = setup.getInventory().stream().filter(DepartureEvaluator::physical)
            .anyMatch(c -> catalogue.getPreparation().getPouches().stream().anyMatch(p -> p.getItemId() == c.getItemId()));
        if (!selected && planned.isEmpty()) { return; }
        boolean packed = setup.getInventory().stream().filter(DepartureEvaluator::physical)
            .anyMatch(c -> player.getPreparation().getInventory().getOrDefault(c.getItemId(), 0) > 0
                && catalogue.getPreparation().getPouches().stream().anyMatch(p -> p.getItemId() == c.getItemId()));
        DeathContext context = player.getDeathContext();
        if (!packed || !context.isPouchContentsKnown())
        {
            entries.add(new Entry("Check rune pouch contents", packed ? "Current contents are unavailable."
                : "Pack the selected pouch before its contents can be confirmed.", true));
            return;
        }
        Set<Integer> ids = new LinkedHashSet<>(planned.keySet());
        ids.addAll(context.getPouchContents().keySet());
        for (int id : ids)
        {
            int target = planned.getOrDefault(id, 0);
            int current = context.getPouchContents().getOrDefault(id, 0);
            if (current == target) { continue; }
            entries.add(new Entry((current < target ? "Load " : "Unload ") + amount(name(player, id), Math.abs(target - current)),
                "Rune pouch: " + number(current) + " / " + number(target) + " planned. Loose runes do not count as loaded.", false));
        }
    }

    private static void charges(SlayerCatalogue catalogue, Setup setup, RecommendationRequest request, List<Entry> entries)
    {
        PlayerSnapshot player = request.getPlayer();
        Set<Integer> checked = new LinkedHashSet<>();
        for (Choice choice : choices(setup))
        {
            if (!physical(choice) || !checked.add(choice.getItemId())) { continue; }
            ItemValue value = player.getItemValues().get(choice.getItemId());
            DeathRule rule = catalogue.getDeathRules().get(choice.getItemId());
            boolean ether = rule != null && "ETHER_WEAPON".equals(rule.getContentsType());
            boolean powered = catalogue.getPreparation().getPoweredWeapons().containsKey(choice.getItemId());
            boolean spellCharges = choice.getName().startsWith("Iban's staff") || choice.getItemId() == 21255;
            ChargeObservation observed = player.getPreparation().getCharges().get(choice.getItemId());
            if (!ether && !powered && !spellCharges && observed == null
                && (value == null || !value.isChargesUnknown())) { continue; }
            int minimum = ether ? 1
                : powered || spellCharges ? catalogue.getPreparation().getCombatCasts() : 1;
            if (observed != null && observed.isObserved() && observed.getCharges() >= 0)
            {
                if (ether && observed.getCharges() > request.getWildernessChargeLimit())
                {
                    entries.add(new Entry("Remove excess ether from " + choice.getName(),
                        chargeDetails(observed, player) + " Alert limit: " + number(request.getWildernessChargeLimit())
                        + " usable charges, excluding the 1,000 activation ether. Change Wildy charge limit in AIO settings.", false));
                }
                else if (observed.getCharges() < minimum)
                {
                    entries.add(new Entry("Charge " + choice.getName(), chargeDetails(observed, player)
                        + " Needs at least " + number(minimum)
                        + (observed.getResources().isEmpty() ? " usable charges." : " of each loaded resource."), false));
                }
                continue;
            }
            String detail = ether
                ? "Confirm a usable charge balance. The excess-charge alert applies only above "
                    + number(request.getWildernessChargeLimit()) + " usable charges; the 1,000 activation ether is separate."
                : powered || spellCharges ? "Check at least " + number(catalogue.getPreparation().getCombatCasts())
                    + " loaded charges for this trip. Loose runes are not loaded charges."
                : "Check the remaining charges and any loaded ammunition before departure.";
            entries.add(new Entry("Check " + choice.getName() + " charges", (observed == null ? "Balance unknown. "
                : chargeDetails(observed, player) + " This tracker balance is an estimate shared by item family. ") + detail
                + " Right-click the carried item in game and choose Check. AIO records the result automatically; use or recharge can require another check.", true));
        }
    }

    private static void wilderness(SlayerCatalogue catalogue, Setup setup, PlayerSnapshot player, List<Entry> entries)
    {
        WildernessRisk risk = setup.getWildernessRisk();
        if (risk == null) { return; }
        PreparationSnapshot actual = player.getPreparation();
        Map<Integer, Integer> planned = new LinkedHashMap<>();
        choices(setup).stream().filter(DepartureEvaluator::physical)
            .forEach(c -> planned.merge(actual.canonicalId(c.getItemId()), c.getQuantity(), DepartureEvaluator::add));
        // Include noted items here: they fail packing checks and still add Wilderness risk.
        canonicalQuantities(player.getRiskCarried(), actual).forEach((id, quantity) -> {
            int surplus = quantity - planned.getOrDefault(id, 0);
            if (surplus > 0)
            {
                entries.add(new Entry("Bank extra " + amount(name(player, id), surplus),
                    "Outside the selected Wilderness setup; it adds risk or changes which items are protected.", false));
            }
        });
        boolean bag = choices(setup).stream().filter(DepartureEvaluator::physical)
            .anyMatch(c -> catalogue.getPreparation().getLootingBagIds().contains(c.getItemId()));
        if (bag)
        {
            DeathContext context = player.getDeathContext();
            if (!context.isLootingBagContentsKnown())
            {
                entries.add(new Entry("Check looting bag is empty", context.getLootingBagDetail()
                    + " Use the bag's View/Check option in game once to refresh it. Closing the view keeps that observation.", true));
            }
            else if (!context.getLootingBagContents().isEmpty())
            {
                entries.add(new Entry("Empty looting bag", "The selected setup assumes an empty bag at departure.", false));
            }
        }
        if (!risk.getCarried().isEmpty())
        {
            WildernessRisk.Scenario carried = risk.getCarried().get(0);
            if (carried.getPermanentLosses() > 0)
            {
                entries.add(new Entry("Review items lost permanently", "Current carried items include permanent losses in the baseline death scenario. Open Wilderness risk below.", true));
            }
            if (carried.getTotalRisk() > risk.getBudget())
            {
                entries.add(new Entry("Carried risk exceeds budget", number(carried.getTotalRisk()) + " gp vs "
                    + number(risk.getBudget()) + " gp budget, before any unverified contents. Open Wilderness risk below.", true));
            }
            if (!carried.isComplete())
            {
                entries.add(new Entry("Carried risk is unverified", "Some charges, contents or values are unknown. The planned estimate is not confirmation of what you are carrying.", true));
            }
        }
    }

    public static String chargeDetails(ChargeObservation charge, PlayerSnapshot player)
    {
        String balance;
        if (charge.getResources().isEmpty())
        {
            balance = charge.getCharges() < 0 ? "balance unknown" : number(charge.getCharges()) + " charges";
        }
        else
        {
            List<String> parts = new ArrayList<>();
            charge.getResources().forEach((id, count) -> parts.add(name(player, id) + " x" + number(count)));
            balance = String.join(", ", parts);
            if (charge.getCharges() < 0) { balance += "; other loaded resources unknown"; }
            else if (charge.getCharges() == 0) { balance += "; not ready to use"; }
        }
        return charge.getSource() + ": " + balance + ".";
    }

    private static List<Choice> choices(Setup setup)
    {
        List<Choice> result = new ArrayList<>(setup.getEquipment().values());
        result.addAll(setup.getInventory());
        return result;
    }

    private static boolean physical(Choice choice)
    {
        return choice.getItemId() > 0 && choice.getQuantity() > 0 && !"RUNE POUCH".equals(choice.getSlot());
    }

    private static Map<Integer, Integer> canonicalQuantities(Map<Integer, Integer> input, PreparationSnapshot actual)
    {
        Map<Integer, Integer> result = new LinkedHashMap<>();
        input.forEach((id, quantity) -> result.merge(actual.canonicalId(id), quantity, DepartureEvaluator::add));
        return result;
    }

    private static int take(Map<Integer, Integer> quantities, int id, int needed)
    {
        int available = quantities.getOrDefault(id, 0);
        int taken = Math.min(needed, available);
        quantities.put(id, available - taken);
        return taken;
    }

    private static String availability(Choice choice, int remaining, int inBackpack)
    {
        return inBackpack >= remaining ? "In your backpack."
            : choice.getMissing() > 0 ? "Some items are missing from known stock; check your bank."
            : "Use the bank filter to find the selected item. Exact doses and charged forms must match.";
    }

    private static String name(PlayerSnapshot player, int id)
    {
        ItemValue value = player.getItemValues().get(id);
        PlayerSnapshot.ItemStats stats = player.getItems().get(id);
        return value != null ? value.getName() : stats != null ? stats.getName() : "Item " + id;
    }

    private static String amount(String name, int quantity) { return name + (quantity == 1 ? "" : " x" + number(quantity)); }
    private static String number(long value) { return String.format(Locale.ENGLISH, "%,d", value); }
    private static int add(int a, int b) { return (int) Math.min(Integer.MAX_VALUE, (long) a + b); }
}

