@Slf4j
@PluginDependency(BankTagsPlugin.class)
@PluginDescriptor(name = "All-In Slayer", description = "Wiki-first Slayer planning with the gear you own",
    tags = {"slayer", "tasks", "gear", "bank", "locations"})
public class AllInSlayerPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ClientThread clientThread;
    @Inject private AllInSlayerConfig config;
    @Inject private ConfigManager configManager;
    @Inject private AdvisorDataService data;
    @Inject private PlayerStateCapture playerState;
    @Inject private ChargeStateCapture chargeState;
    @Inject private LootingBagCapture lootingBag;
    @Inject private WeaponChargesBridge weaponCharges;
    @Inject private ActiveTaskReader taskReader;
    @Inject private ItemManager itemManager;
    @Inject private ClientToolbar toolbar;
    @Inject private OverlayManager overlays;
    @Inject private ScheduledExecutorService executor;
    @Inject private ShortestPathBridge shortestPath;
    @Inject private BankSetupFilter bankFilter;
    @Inject private SetupExporter exporter;

    private final RecommendationEngine engine = new RecommendationEngine();
    private final AtomicReference<Work> pending = new AtomicReference<>();
    private final AtomicBoolean computing = new AtomicBoolean();
    private final AtomicLong revision = new AtomicLong();
    private volatile boolean started;
    private volatile AdvisorPanel.Selection selection;
    private AdvisorPanel panel;
    private AdvisorOverlay overlay;
    private NavigationButton navigation;
    private boolean dirty;
    private boolean chargesAvailable;
    private int retryTicks;
    private String activeIdentity;
    private int lastDeathStateFingerprint;
    private RecommendationRequest displayedRequest;
    private RecommendationResult displayedResult;
    private RecommendationRequest lastCapturedRequest;
    private ActiveTask lastCapturedTask;

    @Provides
    AllInSlayerConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(AllInSlayerConfig.class);
    }

    @Override
    protected void startUp() throws Exception
    {
        data.load();
        started = true;
        selection = new AdvisorPanel.Selection(false, null, null, null, null, null,
            config.recommendationGoal(), config.allowWilderness(), config.allowGroups(), config.returnDestination());
        onEdtAndWait(() ->
        {
            panel = new AdvisorPanel();
            overlay = new AdvisorOverlay();
            panel.setItemManager(itemManager);
            panel.setCatalogue(data.getCatalogue());
            panel.setPreferences(config.recommendationGoal(), config.allowWilderness(), config.allowGroups(), config.returnDestination());
            panel.setOnSelection(this::select);
            panel.setOnRefresh(() -> clientThread.invokeLater(() ->
            {
                lastCapturedRequest = null;
                capture();
            }));
            panel.setOnConfirmRequirement(requirement -> clientThread.invokeLater(() ->
            {
                playerState.confirm(requirement);
                capture();
            }));
            panel.setOnClearConfirmations(() -> clientThread.invokeLater(() ->
            {
                playerState.clearConfirmations();
                capture();
            }));
            panel.setOnExport(this::export);
            panel.setOnBankFilter(this::filterBank);
            panel.setOnRoute(this::route);
            panel.setOnClearRoute(() -> clientThread.invokeLater(shortestPath::clear));
            navigation = NavigationButton.builder().tooltip("All-In Slayer")
                .icon(ImageUtil.loadImageResource(getClass(), "/icons/aio-slayer-assistant.png"))
                .priority(6).panel(panel).build();
            toolbar.addNavigation(navigation);
            overlay.setEnabled(config.showOverlay());
            overlays.add(overlay);
        });
        clientThread.invokeLater(() ->
        {
            if (!started) { return; }
            weaponCharges.start();
            lootingBag.reset();
            bankFilter.start(state -> SwingUtilities.invokeLater(() -> {
                if (started && panel != null) { panel.setBankFilterState(state); }
            }));
            shortestPath.setListener(state -> SwingUtilities.invokeLater(() -> {
                if (started && panel != null) { panel.setRouteState(state); }
            }));
            SwingUtilities.invokeLater(() -> {
                if (started && panel != null) { panel.setRouteState(shortestPath.getState()); }
            });
            dirty = true;
            retryTicks = 0;
            capture();
        });
    }

    @Override
    protected void shutDown() throws Exception
    {
        started = false;
        revision.incrementAndGet();
        pending.set(null);
        selection = null;
        activeIdentity = null;
        lastCapturedRequest = null;
        lastCapturedTask = null;
        clientThread.invokeLater(() -> {
            bankFilter.stop();
            shortestPath.stop();
            weaponCharges.stop();
            lootingBag.reset();
            playerState.clear();
        });
        onEdtAndWait(() ->
        {
            displayedRequest = null;
            displayedResult = null;
            if (navigation != null)
            {
                toolbar.removeNavigation(navigation);
            }
            if (overlay != null)
            {
                overlays.remove(overlay);
            }
            panel = null;
            overlay = null;
        });
    }

    private void select(AdvisorPanel.Selection next)
    {
        selection = next;
        displayedResult = null;
        revision.incrementAndGet();
        // Only preference changes write configuration; browsing never mutates the active assignment.
        if (next.getGoal() != config.recommendationGoal())
        {
            configManager.setConfiguration(AllInSlayerConfig.GROUP, "recommendationGoal", next.getGoal());
        }
        if (next.getReturnDestination() != config.returnDestination())
        {
            configManager.setConfiguration(AllInSlayerConfig.GROUP, "returnDestination", next.getReturnDestination());
        }
        if (next.isAllowWilderness() != config.allowWilderness())
        {
            configManager.setConfiguration(AllInSlayerConfig.GROUP, "allowWilderness", next.isAllowWilderness());
        }
        if (next.isAllowGroups() != config.allowGroups())
        {
            configManager.setConfiguration(AllInSlayerConfig.GROUP, "allowGroups", next.isAllowGroups());
        }
        clientThread.invokeLater(() ->
        {
            bankFilter.reset();
            shortestPath.clear();
            lastCapturedRequest = null;
            capture();
        });
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event)
    {
        int id = event.getContainerId();
        if (lootingBag.observe(event)) { dirty = true; }
        if (id == InventoryID.BANK)
        {
            playerState.bankChanged();
            shortestPath.bankObserved();
        }
        if (id == InventoryID.BANK || id == InventoryID.INV || id == InventoryID.WORN || id == InventoryID.LOOTING_BAG)
        {
            dirty = true;
        }
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        chargeState.observe(event);
        lootingBag.observe(event);
        dirty = true;
    }

    @Subscribe
    public void onChatMessage(ChatMessage event)
    {
        chargeState.observe(event);
        lootingBag.observe(event);
        dirty = true;
    }

    @Subscribe
    public void onAnimationChanged(AnimationChanged event)
    {
        if (lootingBag.observe(event)) { dirty = true; }
        if (event.getActor() == client.getLocalPlayer() && event.getActor().getAnimation() != -1)
        {
            chargeState.equipmentUsed();
            dirty = true;
        }
    }

    @Subscribe
    public void onItemDespawned(ItemDespawned event)
    {
        if (lootingBag.observe(event)) { dirty = true; }
    }

    @Subscribe
    public void onItemQuantityChanged(ItemQuantityChanged event)
    {
        if (lootingBag.observe(event)) { dirty = true; }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        if (event.getActor() == client.getLocalPlayer()) { chargeState.equipmentUsed(); dirty = true; }
    }

    @Subscribe
    public void onActorDeath(ActorDeath event)
    {
        if (event.getActor() == client.getLocalPlayer())
        {
            lootingBag.invalidate();
            chargeState.invalidate();
            dirty = true;
        }
    }

    @Subscribe
    public void onPluginChanged(PluginChanged event)
    {
        if (WeaponChargesBridge.PLUGIN_CLASS.equals(event.getPlugin().getClass().getName()))
        {
            weaponCharges.pluginChanged();
            clientThread.invokeLater(() -> { lastCapturedRequest = null; dirty = true; });
        }
    }

    @Subscribe
    public void onVarbitChanged(VarbitChanged event)
    {
        // Quest/access gates can change on varbits beyond the Slayer assignment itself.
        dirty = true;
    }

    @Subscribe
    public void onStatChanged(StatChanged event)
    {
        dirty = true;
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (playerState.settlePreparation()) { dirty = true; }
        if (chargesAvailable != weaponCharges.isAvailable())
        {
            chargesAvailable = weaponCharges.isAvailable();
            dirty = true;
        }
        if (lootingBag.gameTick()) { dirty = true; }
        bankFilter.refresh();
        shortestPath.refresh();
        // Capture inventory and bank together after the tick's container updates have settled.
        // Periodic refresh also recovers item stats that loaded asynchronously after the first scan.
        int deathFingerprint = playerState.deathStateFingerprint();
        if (deathFingerprint != lastDeathStateFingerprint)
        {
            lastDeathStateFingerprint = deathFingerprint;
            dirty = true;
        }
        boolean periodic = ++retryTicks >= 50;
        if (dirty || periodic)
        {
            if (periodic)
            {
                lastCapturedRequest = null;
            }
            retryTicks = 0;
            capture();
        }
    }

    @Subscribe(priority = -2)
    public void onScriptPreFired(ScriptPreFired event)
    {
        if (event.getScriptId() == ScriptID.BANKMAIN_FINISHBUILDING) { bankFilter.finishLayout(); }
    }

    @Subscribe(priority = -2)
    public void onScriptPostFired(ScriptPostFired event)
    {
        if (event.getScriptId() == ScriptID.BANKMAIN_BUILD) { bankFilter.afterBankBuild(); }
    }

    @Subscribe
    public void onWidgetLoaded(WidgetLoaded event)
    {
        if (event.getGroupId() == InterfaceID.BANKMAIN)
        {
            clientThread.invokeLater(() -> { if (started) { bankFilter.refresh(); } });
        }
    }

    @Subscribe
    public void onWidgetClosed(WidgetClosed event)
    {
        if (event.getGroupId() == InterfaceID.BANKMAIN && event.isUnload())
        {
            // Widget unload can be emitted inside a game script; bank relayouts are not reentrant.
            clientThread.invokeLater(bankFilter::clear);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        lootingBag.observe(event);
        dirty = true;
        if (event.getGameState() != GameState.LOGGED_IN)
        {
            revision.incrementAndGet();
            pending.set(null);
            lastCapturedRequest = null;
            playerState.invalidatePreparation();
            chargeState.invalidate();
            invalidatePreparation();
        }
        if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.LOGGING_IN)
        {
            clientThread.invokeLater(bankFilter::reset);
            shortestPath.accountChanged();
            playerState.clear();
            lootingBag.reset();
            activeIdentity = null;
            clientThread.invokeLater(this::capture);
        }
        else if (event.getGameState() == GameState.LOGGED_IN)
        {
            clientThread.invokeLater(this::capture);
        }
    }

    @Subscribe
    public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
    {
        revision.incrementAndGet();
        pending.set(null);
        invalidatePreparation();
        clientThread.invokeLater(() ->
        {
            bankFilter.reset();
            shortestPath.accountChanged();
            playerState.clear();
            lootingBag.reset();
            lastCapturedRequest = null;
            activeIdentity = null;
            capture();
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (WeaponChargesBridge.CONFIG_GROUP.equals(event.getGroup()))
        {
            // Most provider updates originate in the same game-message callback as our Check.
            // Preserve that ordering so an older queued balance cannot erase a newer check.
            if (client.isClientThread()) { chargeState.providerChanged(event); dirty = true; }
            else { clientThread.invokeLater(() -> { chargeState.providerChanged(event); dirty = true; }); }
            return;
        }
        if ("shortestpath".equals(event.getGroup()) && ("usePoh".equals(event.getKey())
            || "pohJewelleryBoxTier".equals(event.getKey()) || "usePohMountedItems".equals(event.getKey())))
        {
            clientThread.invokeLater(() -> {
                lastCapturedRequest = null;
                capture();
            });
            return;
        }
        if (!AllInSlayerConfig.GROUP.equals(event.getGroup()) || event.getKey().startsWith("advisor"))
        {
            return;
        }
        revision.incrementAndGet();
        SwingUtilities.invokeLater(() ->
        {
            if (!started || panel == null)
            {
                return;
            }
            displayedResult = null;
            panel.setPreferences(config.recommendationGoal(), config.allowWilderness(), config.allowGroups(), config.returnDestination());
            overlay.setEnabled(config.showOverlay());
            AdvisorPanel.Selection previous = selection;
            if (previous != null)
            {
                selection = new AdvisorPanel.Selection(previous.isBrowsing(), previous.getTaskId(),
                    previous.getMasterId(), previous.getMonsterId(), previous.getLocationId(), previous.getMethodId(),
                    config.recommendationGoal(), config.allowWilderness(), config.allowGroups(), config.returnDestination());
            }
            clientThread.invokeLater(() ->
            {
                bankFilter.reset();
                if ("allowWilderness".equals(event.getKey())) { shortestPath.clear(); }
                lastCapturedRequest = null;
                capture();
            });
        });
    }

    private void capture()
    {
        if (!started || selection == null)
        {
            return;
        }
        dirty = false;
        try
        {
            ActiveTask active = taskReader.read(data.getCatalogue());
            String identity = assignmentIdentity(active);
            AdvisorPanel.Selection chosen = selection;
            if (!Objects.equals(activeIdentity, identity))
            {
                activeIdentity = identity;
                if (!chosen.isBrowsing())
                {
                    chosen = new AdvisorPanel.Selection(false, active.getTaskId(), active.getMasterId(),
                        active.getMonsterId(), null, null, chosen.getGoal(), chosen.isAllowWilderness(), chosen.isAllowGroups(), chosen.getReturnDestination());
                    selection = chosen;
                }
            }
            boolean live = !chosen.isBrowsing();
            PlayerSnapshot player = playerState.capture();
            RecommendationRequest request = new RecommendationRequest(
                live ? active.getTaskId() : chosen.getTaskId(),
                live ? active.getMasterId() : chosen.getMasterId(),
                live && active.getMonsterId() != null ? active.getMonsterId() : chosen.getMonsterId(),
                chosen.getLocationId(), chosen.getMethodId(), live, live ? active.getRemaining() : 0,
                live ? active.getLockedLocationId() : null, live && active.isWilderness(),
                chosen.getGoal(), chosen.isAllowWilderness(), chosen.isAllowGroups(), player,
                live ? active.getAllowedMonsterIds() : Collections.emptySet(), config.wildernessRiskBudget(),
                config.plannedEtherCharges(), chosen.getReturnDestination(), config.wildernessChargeLimit(),
                new BoostReservations(config.meleeBoostSlots(), config.meleeBoostItems(),
                    config.rangedBoostSlots(), config.rangedBoostItems(), config.magicBoostSlots(), config.magicBoostItems()),
                new FoodOverride(config.overrideFood(), config.preferredFoods()));
            if (request.equals(lastCapturedRequest) && active.equals(lastCapturedTask))
            {
                return;
            }
            lastCapturedRequest = request;
            lastCapturedTask = active;
            long sequence = revision.incrementAndGet();
            invalidatePreparation();
            pending.set(new Work(sequence, request, active));
            submit();
        }
        catch (RuntimeException ex)
        {
            revision.incrementAndGet();
            pending.set(null);
            lastCapturedRequest = null;
            invalidatePreparation();
            log.warn("Unable to capture Slayer preparation state", ex);
            SwingUtilities.invokeLater(() ->
            {
                if (started && panel != null)
                {
                    panel.showStatus("Game data is not ready. Open your bank or refresh to try again.");
                }
            });
        }
    }

    private void invalidatePreparation()
    {
        SwingUtilities.invokeLater(() -> {
            if (started && panel != null) { panel.invalidatePreparation(); }
        });
    }

    private void submit()
    {
        if (computing.compareAndSet(false, true))
        {
            executor.execute(() ->
            {
                try
                {
                    Work work;
                    while (started && (work = pending.getAndSet(null)) != null)
                    {
                        Work current = work;
                        RecommendationResult result;
                        try
                        {
                            result = engine.recommend(data.getCatalogue(), current.getRequest(),
                                () -> !started || current.getRevision() != revision.get());
                        }
                        catch (java.util.concurrent.CancellationException ignored)
                        {
                            continue;
                        }
                        catch (RuntimeException ex)
                        {
                            log.warn("Unable to calculate Slayer preparation", ex);
                            SwingUtilities.invokeLater(() ->
                            {
                                if (started && panel != null && current.getRevision() == revision.get())
                                {
                                    displayedResult = null;
                                    clientThread.invokeLater(() -> {
                                        if (revision.get() == current.getRevision()) { bankFilter.reset(); }
                                    });
                                    panel.showStatus("This recommendation could not be calculated. Refresh to try again.");
                                }
                            });
                            continue;
                        }
                        SwingUtilities.invokeLater(() -> publish(current, result));
                    }
                }
                finally
                {
                    computing.set(false);
                    if (started && pending.get() != null)
                    {
                        submit();
                    }
                }
            });
        }
    }

    private void publish(Work work, RecommendationResult result)
    {
        if (!started || panel == null || work.getRevision() != revision.get())
        {
            return;
        }
        displayedRequest = work.getRequest();
        displayedResult = result;
        ActiveTask active = work.getActive();
        panel.setActiveAssignmentIdentity(assignmentIdentity(active));
        panel.setActiveAllowedMonsters(active.getAllowedMonsterIds());
        panel.setActiveTask(active.getTaskId(), active.getRemaining(), active.getStatus());
        panel.render(work.getRequest(), result);
        RecommendationResult.Setup best = result.best();
        RecommendationResult.Setup selected = best == null && !result.getSetups().isEmpty() ? result.getSetups().get(0) : best;
        clientThread.invokeLater(() -> {
            if (started && revision.get() == work.getRevision())
            {
                bankFilter.setSetup(work.getRequest().getPlayer().isLoggedIn() ? selected : null, work.getRequest().getPlayer());
            }
        });
        String routedId = shortestPath.getState().getRouteId();
        RouteDestination routed = data.getCatalogue().getRouteDestinations().get(routedId);
        if (routed != null && (selected == null || !routed.getLocationId().equals(selected.getLocationId())
            || !routed.getMonsterIds().contains(selected.getMonsterId())))
        {
            // A bank/task update can change the recommendation without a selector click.
            clientThread.invokeLater(() -> {
                if (revision.get() == work.getRevision() && routedId.equals(shortestPath.getState().getRouteId()))
                {
                    shortestPath.clear();
                }
            });
        }
        overlay.update(active.getTaskId() == null ? "" : active.getStatus(),
            !work.getRequest().isActiveTask() || best == null ? "" : best.getTitle());
    }

    private void export()
    {
        if (displayedResult == null || displayedRequest == null || displayedResult.best() == null)
        {
            panel.showStatus("Choose a feasible setup before exporting.");
            return;
        }
        try
        {
            String encoded = exporter.export(displayedResult.best(), displayedRequest.getPlayer(), displayedRequest.isTaskPreview());
            Toolkit.getDefaultToolkit().getSystemClipboard().setContents(new StringSelection(encoded), null);
            panel.showStatus("Setup copied. Import it in Inventory Setups inside RuneLite.");
        }
        catch (HeadlessException | IllegalStateException | SecurityException ex)
        {
            panel.showStatus("Clipboard is unavailable. The equipment and checklist remain in this panel.");
        }
    }

    private void filterBank(boolean enabled)
    {
        if (!enabled)
        {
            clientThread.invokeLater(bankFilter::clear);
            return;
        }
        if (displayedResult == null || displayedRequest == null || !displayedRequest.getPlayer().isLoggedIn()) { return; }
        RecommendationResult.Setup best = displayedResult.best();
        RecommendationResult.Setup selected = best == null && !displayedResult.getSetups().isEmpty()
            ? displayedResult.getSetups().get(0) : best;
        PlayerSnapshot player = displayedRequest.getPlayer();
        long requestedRevision = revision.get();
        clientThread.invokeLater(() -> {
            if (started && requestedRevision == revision.get())
            {
                bankFilter.setSetup(selected, player);
                bankFilter.open();
            }
        });
    }

    private void route(RouteDestination destination)
    {
        if (displayedResult == null || displayedRequest == null) { return; }
        RecommendationResult.Setup setup = displayedResult.best();
        if (setup == null && !displayedResult.getSetups().isEmpty()) { setup = displayedResult.getSetups().get(0); }
        if (setup == null || !destination.getLocationId().equals(setup.getLocationId())
            || !destination.getMonsterIds().contains(setup.getMonsterId())) { return; }
        boolean wilderness = displayedRequest.isAllowWilderness();
        com.danieljglover.allinslayer.model.advisor.SlayerCatalogue.Location location = data.getCatalogue().getLocations().get(setup.getLocationId());
        if (!wilderness && (location.isWilderness() || setup.getWildernessRisk() != null))
        {
            panel.showStatus("Enable Allow Wilderness before routing to this location.");
            return;
        }
        long requestedRevision = revision.get();
        clientThread.invokeLater(() -> {
            if (started && revision.get() == requestedRevision) { shortestPath.route(destination, wilderness); }
        });
    }

    private static void onEdtAndWait(Runnable action) throws Exception
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            action.run();
        }
        else
        {
            SwingUtilities.invokeAndWait(action);
        }
    }

    private static String assignmentIdentity(ActiveTask task)
    {
        return task.getTaskId() + ":" + task.getMonsterId() + ":" + task.getLockedLocationId()
            + ":" + String.join(",", task.getAllowedMonsterIds());
    }

    @Value
    private static class Work
    {
        long revision;
        RecommendationRequest request;
        ActiveTask active;
    }
}

package com.danieljglover.allinslayer.bank.advisor;

import com.danieljglover.allinslayer.data.AdvisorDataService;
import com.danieljglover.allinslayer.model.advisor.DeathContext;
import com.danieljglover.allinslayer.model.advisor.DeathRule;
import com.danieljglover.allinslayer.model.advisor.ItemValue;
import java.util.Collections;
import java.util.EnumSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Prayer;
import net.runelite.api.SkullIcon;
import net.runelite.api.WorldType;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.vars.AccountType;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.util.Text;

/** Read-only client-thread observations; prices come from RuneLite's existing item cache. */
@Singleton
public final class DeathStateCapture
{
    private static final Pattern WILDERNESS_LEVEL = Pattern.compile("(?i)level\\s*:\\s*(\\d+)");
    // RuneLite's current ParamID.QUIVER_AMMO_AVAILABLE; not named in every supported API release.
    private static final int QUIVER_AMMO_AVAILABLE = 1910;
    private static final int[] POUCH_TYPES = {
        VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3,
        VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
    };
    private static final int[] POUCH_QUANTITIES = {
        VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3,
        VarbitID.RUNE_POUCH_QUANTITY_4, VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
    };
    private final Client client;
    private final ItemManager itemManager;
    private final AdvisorDataService data;
    private final LootingBagCapture lootingBag;

    @Inject
    public DeathStateCapture(Client client, ItemManager itemManager, AdvisorDataService data, LootingBagCapture lootingBag)
    {
        this.client = client;
        this.itemManager = itemManager;
        this.data = data;
        this.lootingBag = lootingBag;
    }

    public int fingerprint()
    {
        int result = status().hashCode();
        try
        {
            Widget bag = client.getWidget(InterfaceID.WildernessLootingbag.ITEMS);
            return 31 * result + (bag != null && !bag.isHidden() ? 1 : 0);
        }
        catch (RuntimeException ignored)
        {
            return 31 * result;
        }
    }

    public DeathContext capture()
    {
        DeathContext status = status();
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return status;
        }
        Map<Integer, Integer> pouch = new LinkedHashMap<>();
        boolean pouchKnown = capturePouch(pouch);
        Map<Integer, Integer> quiver = new LinkedHashMap<>();
        boolean quiverKnown = captureQuiver(quiver);
        LootingBagCapture.Snapshot bag = lootingBag.capture();
        return new DeathContext(status.isKnown(), status.isSkulled(), status.isProtectItemActive(),
            status.isHighRisk(), status.isUltimateIronman(), status.getWildernessLevel(),
            pouch, bag.getContents(), pouchKnown, bag.isKnown(), quiver, quiverKnown, bag.getDetail());
    }

    public Map<Integer, ItemValue> values(Set<Integer> ownedIds, Map<Integer, Integer> carried,
        DeathContext context)
    {
        Set<Integer> ids = new LinkedHashSet<>(ownedIds);
        ids.addAll(carried.keySet());
        ids.addAll(context.getPouchContents().keySet());
        ids.addAll(context.getLootingBagContents().keySet());
        ids.addAll(context.getQuiverContents().keySet());
        for (DeathRule rule : data.getCatalogue().getDeathRules().values())
        {
            ids.addAll(rule.getReplacementItems().keySet());
            ids.addAll(rule.getRepairCostItems().keySet());
            ids.addAll(rule.getAlwaysLostItems().keySet());
        }
        Map<Integer, ItemValue> values = new LinkedHashMap<>();
        for (int id : ids)
        {
            values.put(id, describeValue(id));
        }
        return values;
    }

    boolean containsRunePouch(Map<Integer, Integer> items)
    {
        return items.entrySet().stream().anyMatch(entry ->
        {
            DeathRule rule = data.getCatalogue().getDeathRules().get(entry.getKey());
            return entry.getValue() != null && entry.getValue() > 0
                && rule != null && "RUNE_POUCH".equals(rule.getContentsType());
        });
    }

    public Map<Integer, Integer> readCarried(ItemContainer container)
    {
        Map<Integer, Integer> counts = new LinkedHashMap<>();
        if (container == null)
        {
            return counts;
        }
        for (Item item : container.getItems())
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }
            ItemComposition definition = itemManager.getItemComposition(item.getId());
            if (definition.getPlaceholderTemplateId() == -1)
            {
                // Notes cannot be selected as equipment, but are still actual valuables at risk.
                counts.merge(item.getId(), item.getQuantity(), DeathStateCapture::add);
            }
        }
        return counts;
    }

    private DeathContext status()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return DeathContext.unknown();
        }
        try
        {
            Player player = client.getLocalPlayer();
            if (player == null)
            {
                return DeathContext.unknown();
            }
            EnumSet<WorldType> world = client.getWorldType();
            AccountType account = client.getAccountType();
            int skull = player.getSkullIcon();
            boolean highRisk = world.contains(WorldType.HIGH_RISK) || skull == SkullIcon.SKULL_HIGH_RISK;
            boolean known = account != null && !world.contains(WorldType.DEADMAN)
                && !world.contains(WorldType.SEASONAL) && !world.contains(WorldType.PVP_ARENA)
                && !world.contains(WorldType.LAST_MAN_STANDING);
            return new DeathContext(known, skull != SkullIcon.NONE && skull != SkullIcon.SKULL_FIGHT_PIT,
                client.isPrayerActive(Prayer.PROTECT_ITEM), highRisk, account == AccountType.ULTIMATE_IRONMAN,
                wildernessLevel(), Collections.emptyMap(), Collections.emptyMap(), false, false);
        }
        catch (RuntimeException ignored)
        {
            return DeathContext.unknown();
        }
    }

    private int wildernessLevel()
    {
        if (client.getVarbit(VarbitID.INSIDE_WILDERNESS) == null)
        {
            return -1;
        }
        if (client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) == 0)
        {
            return 0;
        }
        Widget level = client.getWidget(InterfaceID.PvpIcons.WILDERNESSLEVEL);
        if (level == null || level.isHidden() || level.getText() == null)
        {
            return -1;
        }
        // Reading the game's depth also handles caves and instances without coordinate guesses.
        Matcher matcher = WILDERNESS_LEVEL.matcher(Text.removeTags(level.getText()));
        return matcher.find() ? Integer.parseInt(matcher.group(1)) : -1;
    }

    private boolean capturePouch(Map<Integer, Integer> contents)
    {
        try
        {
            EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
            if (runes == null || runes.size() == 0)
            {
                return false;
            }
            for (int i = 0; i < POUCH_TYPES.length; i++)
            {
                if (client.getVarbit(POUCH_TYPES[i]) == null || client.getVarbit(POUCH_QUANTITIES[i]) == null)
                {
                    return false;
                }
                int type = client.getVarbitValue(POUCH_TYPES[i]);
                int quantity = client.getVarbitValue(POUCH_QUANTITIES[i]);
                if (quantity < 0 || (quantity > 0 && type <= 0))
                {
                    return false;
                }
                if (quantity > 0)
                {
                    int id = runes.getIntValue(type);
                    if (id <= 0)
                    {
                        return false;
                    }
                    contents.merge(id, quantity, DeathStateCapture::add);
                }
            }
            return true;
        }
        catch (RuntimeException ignored)
        {
            return false;
        }
    }

    private ItemValue describeValue(int id)
    {
        try
        {
            ItemComposition exact = itemManager.getItemComposition(id);
            ItemComposition base = exact.getNote() == -1 ? exact
                : itemManager.getItemComposition(exact.getLinkedNoteId());
            long market = itemManager.getItemPrice(id);
            long official = itemManager.getItemPriceWithSource(id, false);
            long protection = official > 0 ? official : base.isGeTradeable() ? -1 : base.getHaPrice();
            if (base.getId() == ItemID.COINS || base.getId() == ItemID.PLATINUM)
            {
                market = protection = base.getId() == ItemID.COINS ? 1 : 1000;
            }
            // ItemManager returns zero when no price has loaded, not proof of a worthless item.
            return new ItemValue(id, exact.getName(), market > 0 ? market : -1, protection,
                base.isTradeable(), exact.isStackable(), chargesUnknown(base));
        }
        catch (RuntimeException ignored)
        {
            return new ItemValue(id, null, -1, -1, false, false, true);
        }
    }

    private boolean captureQuiver(Map<Integer, Integer> contents)
    {
        try
        {
            ItemContainer worn = client.getItemContainer(InventoryID.WORN);
            Item cape = worn == null ? null : worn.getItem(EquipmentInventorySlot.CAPE.getSlotIdx());
            if (cape == null || itemManager.getItemComposition(cape.getId()).getIntValue(QUIVER_AMMO_AVAILABLE) != 1)
            {
                return false;
            }
            // These transmitted values also drive RuneLite's own quiver ammunition infobox.
            int id = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
            int quantity = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
            if (quantity < 0 || (quantity > 0 && id <= 0))
            {
                return false;
            }
            if (quantity > 0)
            {
                contents.put(id, quantity);
            }
            return true;
        }
        catch (RuntimeException ignored)
        {
            return false;
        }
    }

    private static boolean chargesUnknown(ItemComposition item)
    {
        String name = item.getName() == null ? "" : item.getName().toLowerCase(Locale.ROOT);
        switch (item.getId())
        {
            case 28947: case 28949: case 28951: case 28953:
                return true; // Unblessed quivers can have partial blessing progress as well as sunfire charges.
            case 24551: case 25867: case 25870: case 25872: case 25874: case 25876:
            case 25878: case 25880: case 25882: case 25884: case 25886: case 25888:
            case 25890: case 25892: case 25894: case 25896: case 33021:
                return false; // Corrupted crystal weapons have no stored charge balance.
            default:
                break;
        }
        if (name.contains("uncharged") || name.contains("(empty)") || name.contains("(inactive)")
            || name.contains("corrupted") || name.contains("(broken)") || name.contains("(mangled)"))
        {
            return false;
        }
        switch (item.getId())
        {
            case 22550: case 22545: case 22555: case 27655: case 27660: case 27665: case 27679: case 27788:
                return true; // Ether stored in Wilderness weapons is lost even if the weapon is protected.
            default:
                break;
        }
        String[] actions = item.getInventoryActions();
        if (actions != null)
        {
            for (String action : actions)
            {
                if (action != null && action.equalsIgnoreCase("Uncharge"))
                {
                    return true;
                }
            }
        }
        // Stored charges are not supplied by bank/inventory containers. Never assume full or empty.
        return name.contains("arclight") || name.contains("iban's staff") || name.contains("slayer's staff (e)")
            || name.contains("trident") || name.contains("blowpipe") || name.contains("serpentine helm")
            || name.contains("tanzanite helm") || name.contains("magma helm")
            || name.contains("tumeken's shadow") || name.contains("sanguinesti staff")
            || name.contains("scythe of vitur") || name.contains("eye of ayak")
            || name.contains("blood fury") || name.contains("suffering (r")
            || name.contains("bracelet of ethereum") || name.contains("tonalztics of ralos")
            || name.contains("toxic staff of the dead") || name.contains("venator bow")
            || name.contains("warped sceptre") || name.contains("lithic sceptre")
            || name.contains("tome of fire") || name.contains("tome of water") || name.contains("tome of earth")
            || name.contains("ring of endurance") || name.contains("abyssal tentacle")
            || name.contains("crystal bow") || name.contains("crystal shield")
            || name.contains("crystal halberd") || name.contains("crystal helm")
            || name.contains("crystal body") || name.contains("crystal legs")
            || name.contains("bow of faerdhinen") || name.contains("blade of saeldor");
    }

    private static int add(int first, int second)
    {
        return (int) Math.min(Integer.MAX_VALUE, (long) first + second);
    }
}

package com.danieljglover.allinslayer.bank.advisor;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.MenuAction;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.ItemDespawned;
import net.runelite.api.events.ItemQuantityChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.RuneScapeProfileType;
import net.runelite.client.util.Text;

/** Client-thread-only, session-local observations of the bag; never requests a game action. */
@Singleton
public final class LootingBagCapture
{
    private static final int BAG_SLOTS = 28;
    private static final String UNOBSERVED = "Bag contents have not been observed this session.";
    private static final String STALE = "Bag contents may have changed; check the bag to refresh.";
    private static final Snapshot UNKNOWN = new Snapshot(false, Collections.emptyMap(), UNOBSERVED);
    private final Client client;
    private Snapshot snapshot = UNKNOWN;
    private long accountHash = -1;
    private RuneScapeProfileType profileType;
    private Widget ignoredViewMarker;
    private boolean carried;
    private PickupTarget pickupTarget;
    private PickupTarget telegrabTarget;
    private WorldPoint objectLootTarget;
    private boolean objectLootAnimation;

    @Inject
    public LootingBagCapture(Client client)
    {
        this.client = client;
    }

    public Snapshot capture()
    {
        return syncSession() && client.getGameState() == GameState.LOGGED_IN ? snapshot : UNKNOWN;
    }

    public boolean observe(ItemContainerChanged event)
    {
        Snapshot before = snapshot;
        if (!syncSession()) { return !before.equals(snapshot); }
        if (event.getContainerId() == InventoryID.LOOTING_BAG)
        {
            // A transmitted container is fresh even if its view has already closed. An absent
            // container, however, can also mean "not sent", so it never proves an empty bag.
            ItemContainer container = event.getItemContainer();
            if (container != null)
            {
                Map<Integer, Integer> contents = new LinkedHashMap<>();
                for (Item item : container.getItems())
                {
                    if (item != null) { add(contents, item.getId(), item.getQuantity()); }
                }
                confirm(contents);
            }
        }
        else if (event.getContainerId() == InventoryID.INV)
        {
            boolean present = hasBag(event.getItemContainer(), false);
            if (carried && !present) { invalidate(); }
            if (!present) { clearPendingActions(); }
            carried = present;
        }
        return !before.equals(snapshot);
    }

    public boolean gameTick()
    {
        Snapshot before = snapshot;
        if (syncSession() && client.getGameState() == GameState.LOGGED_IN)
        {
            boolean present = hasBag(client.getItemContainer(InventoryID.INV), false);
            if (carried && !present) { invalidate(); }
            if (!present) { clearPendingActions(); }
            carried = present;
            observeContentsView();
        }
        return !before.equals(snapshot);
    }

    public boolean observe(MenuOptionClicked event)
    {
        Snapshot before = snapshot;
        if (!syncSession() || event.isConsumed()) { return !before.equals(snapshot); }
        MenuAction action = event.getMenuAction();
        String option = plain(event.getMenuOption()).toLowerCase(Locale.ROOT);
        Widget clicked = event.getWidget();
        int clickedId = event.getItemId();
        if (clickedId <= 0 && clicked != null) { clickedId = clicked.getItemId(); }
        Widget selected = client.getSelectedWidget();
        boolean usedOnBag = action == MenuAction.WIDGET_TARGET_ON_WIDGET
            && (bagId(clickedId) || selected != null && bagId(selected.getItemId()));
        boolean removedBag = bagId(clickedId) && (option.equals("destroy") || option.equals("drop"));
        int component = event.getParam1();
        boolean deposit = component >>> 16 == InterfaceID.WILDERNESS_LOOTINGBAG
            && option.startsWith("store-");
        boolean bankContents = component == InterfaceID.Bankmain.DEPOSITCONTAINERS
            || component == InterfaceID.BankDepositbox.DEPOSIT_LOOTINGBAG
            || component == InterfaceID.Bankside.LOOTINGBAG_BANKALL
            || component == InterfaceID.Bankside.LOOTINGBAG_ITEMS && !option.equals("examine");
        boolean collecting = hasBag(client.getItemContainer(InventoryID.INV), true);
        boolean groundPickup = collecting && (action == MenuAction.GROUND_ITEM_THIRD_OPTION
            && option.equals("take") || action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM);
        boolean lootObject = collecting && objectAction(action)
            && (option.equals("loot") || option.equals("steal") || option.startsWith("search")
                || option.equals("collect") || option.equals("claim")
                || (option.equals("open") || option.equals("unlock"))
                    && plain(event.getMenuTarget()).toLowerCase(Locale.ROOT).contains("chest"));
        if (groundPickup)
        {
            PickupTarget target = new PickupTarget(event.getId(), clickedPoint(event));
            if (action == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM) { telegrabTarget = target; }
            else { pickupTarget = target; }
        }
        if (lootObject)
        {
            objectLootTarget = clickedPoint(event);
            objectLootAnimation = false;
        }
        else if (!objectLootAnimation && (objectAction(action) || action == MenuAction.WALK))
        {
            objectLootTarget = null;
            objectLootAnimation = false;
        }
        if (usedOnBag || removedBag || deposit || bankContents || groundPickup || lootObject)
        {
            // These actions can alter the bag without transmitting container 516. Their success
            // and quantities are not guaranteed, so retain the old snapshot only as unknown.
            invalidate();
        }
        return !before.equals(snapshot);
    }

    public boolean observe(ItemDespawned event)
    {
        return pickupCompleted(event.getItem().getId(), event.getTile().getWorldLocation(), true);
    }

    public boolean observe(ItemQuantityChanged event)
    {
        return event.getNewQuantity() < event.getOldQuantity()
            && pickupCompleted(event.getItem().getId(), event.getTile().getWorldLocation(), false);
    }

    public boolean observe(AnimationChanged event)
    {
        Snapshot before = snapshot;
        if (!syncSession() || event.getActor() != client.getLocalPlayer() || objectLootTarget == null
            || !hasBag(client.getItemContainer(InventoryID.INV), true)) { return !before.equals(snapshot); }
        if (event.getActor().getAnimation() != -1)
        {
            if (objectLootTarget.distanceTo(client.getLocalPlayer().getWorldLocation()) > 2) { return false; }
            objectLootAnimation = true;
            invalidate();
        }
        else if (objectLootAnimation)
        {
            // A fresh View can finish while the player's earlier loot action is animating.
            invalidate();
            objectLootTarget = null;
            objectLootAnimation = false;
        }
        return !before.equals(snapshot);
    }

    private boolean pickupCompleted(int itemId, WorldPoint point, boolean removed)
    {
        Snapshot before = snapshot;
        if (!syncSession()) { return !before.equals(snapshot); }
        boolean pickup = pickupTarget != null && pickupTarget.matches(itemId, point);
        boolean telegrab = telegrabTarget != null && telegrabTarget.matches(itemId, point);
        if ((pickup || telegrab) && hasBag(client.getItemContainer(InventoryID.INV), true))
        {
            // A View response can arrive after Take was clicked but before walking or a
            // telegrab finishes. The later ground-stack change invalidates that observation.
            // Another player may have taken it instead; uncertainty is preferable to inferring loot.
            invalidate();
        }
        if (removed)
        {
            if (pickup) { pickupTarget = null; }
            if (telegrab) { telegrabTarget = null; }
        }
        return !before.equals(snapshot);
    }

    private WorldPoint clickedPoint(MenuOptionClicked event)
    {
        WorldView worldView = client.getWorldView(event.getMenuEntry().getWorldViewId());
        return worldView == null ? null
            : WorldPoint.fromScene(worldView, event.getParam0(), event.getParam1(), worldView.getPlane());
    }

    private void clearPendingActions()
    {
        pickupTarget = null;
        telegrabTarget = null;
        objectLootTarget = null;
        objectLootAnimation = false;
    }

    public boolean observe(ChatMessage event)
    {
        Snapshot before = snapshot;
        if (!syncSession()) { return !before.equals(snapshot); }
        if ((event.getType() == ChatMessageType.GAMEMESSAGE || event.getType() == ChatMessageType.SPAM)
            && hasBag(client.getItemContainer(InventoryID.INV), true))
        {
            String message = plain(event.getMessage());
            if (message.startsWith("You have been awarded ") && message.contains("Agility dispenser"))
            {
                invalidate();
            }
        }
        return !before.equals(snapshot);
    }

    public boolean observe(GameStateChanged event)
    {
        Snapshot before = snapshot;
        GameState state = event.getGameState();
        if (state != GameState.LOGGED_IN && state != GameState.LOADING)
        {
            reset();
        }
        else
        {
            syncSession();
        }
        return !before.equals(snapshot);
    }

    public void reset()
    {
        snapshot = UNKNOWN;
        accountHash = -1;
        profileType = null;
        ignoredViewMarker = null;
        carried = false;
        clearPendingActions();
    }

    public void invalidate()
    {
        snapshot = new Snapshot(false, snapshot.getContents(), STALE);
        // A mutation can be clicked while the previous empty view still exists. Do not allow
        // that old widget tree to make the snapshot known again before the game rebuilds it.
        ignoredViewMarker = viewMarker();
    }

    private boolean syncSession()
    {
        GameState state = client.getGameState();
        if (state != GameState.LOGGED_IN && state != GameState.LOADING)
        {
            reset();
            return false;
        }
        long currentHash = client.getAccountHash();
        if (currentHash == -1)
        {
            reset();
            return false;
        }
        RuneScapeProfileType currentType = RuneScapeProfileType.getCurrent(client);
        if (currentHash != accountHash || currentType != profileType)
        {
            reset();
            accountHash = currentHash;
            profileType = currentType;
            // Neither a buffered container nor an old widget is evidence for a new account.
            ignoredViewMarker = viewMarker();
        }
        return true;
    }

    private void observeContentsView()
    {
        Widget title = client.getWidget(InterfaceID.WildernessLootingbag.TITLE);
        Widget grid = client.getWidget(InterfaceID.WildernessLootingbag.ITEMS);
        if (title == null || title.isHidden() || !plain(title.getText()).equals("Looting bag")
            || grid == null || grid.isHidden())
        {
            return;
        }
        Widget marker = grid.getChild(0);
        if (marker == null || marker == ignoredViewMarker) { return; }
        Widget[] children = grid.getDynamicChildren();
        if (children == null || children.length < BAG_SLOTS) { return; }
        Map<Integer, Integer> contents = new LinkedHashMap<>();
        for (int slot = 0; slot < BAG_SLOTS; slot++)
        {
            Widget item = grid.getChild(slot);
            if (item == null) { return; }
            if (!item.isSelfHidden()) { add(contents, item.getItemId(), item.getItemQuantity()); }
        }
        Widget empty = grid.getChild(BAG_SLOTS);
        boolean explicitlyEmpty = empty != null && !empty.isHidden()
            && plain(empty.getText()).equals("The bag is empty.");
        // Group 81 also displays inventory 93 for "Add to bag". A missing container, unloaded
        // grid, or empty inventory in that mode must never be interpreted as an empty bag.
        if (!contents.isEmpty() || explicitlyEmpty)
        {
            confirm(contents);
            ignoredViewMarker = marker;
        }
    }

    private Widget viewMarker()
    {
        Widget grid = client.getWidget(InterfaceID.WildernessLootingbag.ITEMS);
        return grid == null ? null : grid.getChild(0);
    }

    private void confirm(Map<Integer, Integer> contents)
    {
        snapshot = new Snapshot(true, contents, contents.isEmpty()
            ? "An empty bag was observed this session." : "Bag contents were observed this session.");
        ignoredViewMarker = viewMarker();
    }

    private static boolean hasBag(ItemContainer inventory, boolean openOnly)
    {
        if (inventory == null) { return false; }
        for (Item item : inventory.getItems())
        {
            if (item != null && item.getQuantity() > 0
                && (item.getId() == ItemID.LOOTING_BAG_OPEN || !openOnly && item.getId() == ItemID.LOOTING_BAG))
            {
                return true;
            }
        }
        return false;
    }

    private static boolean bagId(int id)
    {
        return id == ItemID.LOOTING_BAG || id == ItemID.LOOTING_BAG_OPEN;
    }

    private static boolean objectAction(MenuAction action)
    {
        return action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
            || action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION
            || action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
    }

    private static String plain(String text)
    {
        return text == null ? "" : Text.removeTags(text).trim();
    }

    private static void add(Map<Integer, Integer> contents, int id, int quantity)
    {
        if (id > 0 && quantity > 0)
        {
            contents.merge(id, quantity,
                (first, second) -> (int) Math.min(Integer.MAX_VALUE, (long) first + second));
        }
    }

    private static final class PickupTarget
    {
        private final int itemId;
        private final WorldPoint point;

        private PickupTarget(int itemId, WorldPoint point)
        {
            this.itemId = itemId;
            this.point = point;
        }

        private boolean matches(int id, WorldPoint location)
        {
            return itemId == id && point != null && point.equals(location);
        }
    }

    @Getter
    @EqualsAndHashCode
    public static final class Snapshot
    {
        private final boolean known;
        private final Map<Integer, Integer> contents;
        private final String detail;

        private Snapshot(boolean known, Map<Integer, Integer> contents, String detail)
        {
            this.known = known;
            this.contents = Collections.unmodifiableMap(new LinkedHashMap<>(contents));
            this.detail = detail;
        }
    }
}

package com.danieljglover.allinslayer.bank.advisor;

import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot;
import com.danieljglover.allinslayer.model.advisor.PreparationSnapshot;
import com.danieljglover.allinslayer.model.advisor.AccountProgress;
import com.danieljglover.allinslayer.model.advisor.AccountProgress.State;
import com.danieljglover.allinslayer.model.advisor.DeathContext;
import com.danieljglover.allinslayer.model.advisor.PlayerSnapshot.Spellbook;
import com.google.gson.Gson;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.itemstats.Effect;
import net.runelite.client.plugins.itemstats.ItemStatChanges;
import net.runelite.client.plugins.itemstats.RangeStatChange;
import net.runelite.client.plugins.itemstats.StatChange;
import net.runelite.client.plugins.itemstats.StatsChanges;
import net.runelite.client.plugins.itemstats.stats.Stats;

/** All methods are called on the client thread. Persist only observations tied to an RS profile. */
@Slf4j
@Singleton
public final class PlayerStateCapture
{
    private static final String GROUP = "allinslayer";
    private static final String BANK_KEY = "advisorBankV2";
    private static final String REQUIREMENTS_KEY = "advisorConfirmedRequirementsV2";
    private static final String[] SLOTS = {
        "HEAD", "CAPE", "AMULET", "WEAPON", "BODY", "SHIELD", null,
        "LEGS", null, "HANDS", "FEET", null, "RING", "AMMO"
    };
    private final Client client;
    private final ConfigManager config;
    private final ItemManager itemManager;
    private final ItemStatChanges itemStatChanges;
    private final Gson gson;
    private final AccountProgressCapture accountProgressCapture;
    private final DeathStateCapture deathStateCapture;
    private final ChargeStateCapture chargeStateCapture;
    private String profile;
    private BankObservation bank;
    private final Set<String> confirmations = new HashSet<>();
    private boolean bankDirty;
    private boolean bankWasOpen;
    private boolean preparationSettled;

    public boolean settlePreparation()
    {
        syncProfile();
        boolean ready = client.getGameState() == GameState.LOGGED_IN
            && client.getLocalPlayer() != null && profile != null;
        boolean changed = preparationSettled != ready;
        preparationSettled = ready;
        chargeStateCapture.setSessionSettled(ready);
        return changed;
    }

    public void invalidatePreparation()
    {
        preparationSettled = false;
        chargeStateCapture.setSessionSettled(false);
    }

    @Inject
    public PlayerStateCapture(Client client, ConfigManager config, ItemManager itemManager, Gson gson,
        AccountProgressCapture accountProgressCapture, DeathStateCapture deathStateCapture,
        ChargeStateCapture chargeStateCapture, ItemStatChanges itemStatChanges)
    {
        this.client = client;
        this.config = config;
        this.itemManager = itemManager;
        this.itemStatChanges = itemStatChanges;
        this.gson = gson;
        this.accountProgressCapture = accountProgressCapture;
        this.deathStateCapture = deathStateCapture;
        this.chargeStateCapture = chargeStateCapture;
    }

    public int deathStateFingerprint()
    {
        return deathStateCapture.fingerprint();
    }

    public void bankChanged()
    {
        bankDirty = true;
    }

    public void clear()
    {
        invalidatePreparation();
        chargeStateCapture.invalidate();
        profile = null;
        bank = null;
        bankDirty = false;
        bankWasOpen = false;
        confirmations.clear();
    }

    public void confirm(String requirement)
    {
        syncProfile();
        if (profile != null && requirement != null && !requirement.trim().isEmpty())
        {
            // Confirmation toggles are reversible and never override a known failed skill check.
            if (!confirmations.remove(requirement))
            {
                confirmations.add(requirement);
            }
            config.setRSProfileConfiguration(GROUP, REQUIREMENTS_KEY, gson.toJson(confirmations));
        }
    }

    public void clearConfirmations()
    {
        syncProfile();
        confirmations.clear();
        if (profile != null)
        {
            config.unsetRSProfileConfiguration(GROUP, REQUIREMENTS_KEY);
        }
    }

    public PlayerSnapshot capture()
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            return new PlayerSnapshot(Collections.emptyMap(), Collections.emptyMap(),
                Collections.emptyMap(), Collections.emptyMap(), Collections.emptySet(), false, 0);
        }
        syncProfile();
        ItemContainer inventoryContainer = client.getItemContainer(InventoryID.INV);
        ItemContainer equipmentContainer = client.getItemContainer(InventoryID.WORN);
        Map<Integer, Integer> inventory = read(inventoryContainer);
        Map<Integer, Integer> carried = new LinkedHashMap<>(inventory);
        Map<Integer, Integer> worn = read(equipmentContainer);
        merge(carried, worn);
        Map<Integer, Integer> riskCarried = deathStateCapture.readCarried(client.getItemContainer(InventoryID.INV));
        merge(riskCarried, deathStateCapture.readCarried(client.getItemContainer(InventoryID.WORN)));
        DeathContext deathContext = deathStateCapture.capture();
        Widget bankWidget = client.getWidget(InterfaceID.Bankmain.ITEMS);
        boolean bankOpen = bankWidget != null && !bankWidget.isHidden();
        ItemContainer liveBank = client.getItemContainer(InventoryID.BANK);
        if (bankOpen && liveBank != null && (bankDirty || bank == null || !bankWasOpen))
        {
            BankObservation next = new BankObservation();
            next.version = 3;
            next.seenAt = System.currentTimeMillis();
            next.items = read(liveBank);
            next.carried = new HashMap<>(carried);
            next.pouchContents = new HashMap<>(usablePouchContents(deathContext, carried, next.items));
            bank = next;
            bankDirty = false;
            if (profile != null)
            {
                config.setRSProfileConfiguration(GROUP, BANK_KEY, gson.toJson(next));
            }
        }
        bankWasOpen = bankOpen;
        Map<Integer, Integer> pouch = usablePouchContents(deathContext, carried,
            bank == null ? Collections.emptyMap() : bank.items);
        Map<Integer, Integer> owned = new LinkedHashMap<>(carried);
        merge(owned, pouch);
        if (bank != null)
        {
            bank.items.forEach((id, quantity) ->
            {
                // Loading the pouch can withdraw runes without increasing loose inventory.
                // Compare both outside-bank stores together so moving runes between them does
                // not subtract twice, while a closed-bank withdrawal cannot add owned stock.
                long outside = (long) carried.getOrDefault(id, 0) + pouch.getOrDefault(id, 0);
                long previous = (long) bank.carried.getOrDefault(id, 0) + bank.pouchContents.getOrDefault(id, 0);
                long newlyOutside = Math.max(0, outside - previous);
                int estimate = (int) Math.max(0, quantity - newlyOutside);
                owned.merge(id, estimate, PlayerStateCapture::add);
            });
        }
        Map<String, Integer> levels = new HashMap<>();
        for (Skill skill : Skill.values())
        {
            if (skill != Skill.OVERALL)
            {
                levels.put(skill.name(), client.getRealSkillLevel(skill));
            }
        }
        if (client.getLocalPlayer() != null)
        {
            levels.put("COMBAT", client.getLocalPlayer().getCombatLevel());
        }
        Set<String> confirmed = new HashSet<>(confirmations);
        AccountProgress accountProgress = accountProgressCapture.capture();
        Map<String, State> progress = new LinkedHashMap<>(accountProgress.getRequirements());
        for (int id : worn.keySet())
        {
            progress.put(AccountProgress.key("Can equip: " + itemManager.getItemComposition(id).getName()), State.MET);
        }
        Map<Integer, PlayerSnapshot.ItemStats> stats = new HashMap<>();
        for (int id : owned.keySet())
        {
            PlayerSnapshot.ItemStats value = describe(id);
            if (value != null)
            {
                stats.put(id, value);
            }
        }
        PreparationSnapshot prepared = preparation(equipmentContainer, inventory, owned.keySet());
        Set<Integer> valuedIds = new HashSet<>(owned.keySet());
        prepared.getCharges().values().forEach(charges -> valuedIds.addAll(charges.getResources().keySet()));
        return new PlayerSnapshot(owned, carried, stats, levels, confirmed, true,
            bank == null ? 0 : bank.seenAt, captureSpellbook(), new AccountProgress(progress, accountProgress.getConfiguredRequirements()),
            deathStateCapture.values(valuedIds, riskCarried, deathContext), riskCarried, deathContext, prepared);
    }

    private PreparationSnapshot preparation(ItemContainer worn,
        Map<Integer, Integer> inventory, Set<Integer> ownedIds)
    {
        if (!preparationSettled) { return PreparationSnapshot.unknown(); }
        Map<String, PreparationSnapshot.Stack> equipment = new LinkedHashMap<>();
        // Empty containers need not exist in the client hash table. A completed logged-in
        // tick settles the initial packets; before that tick, absence remains unknown.
        for (int index = 0; index < SLOTS.length; index++)
        {
            Item item = worn == null ? null : worn.getItem(index);
            if (SLOTS[index] != null && item != null && item.getId() > 0 && item.getQuantity() > 0)
            {
                equipment.put(SLOTS[index], new PreparationSnapshot.Stack(item.getId(), item.getQuantity()));
            }
        }
        Map<Integer, Integer> canonicalIds = new LinkedHashMap<>();
        for (int id : ownedIds)
        {
            // Canonicalization only joins linked worn forms here, never notes, doses or charge variants.
            canonicalIds.put(id, itemManager.canonicalize(id));
        }
        return new PreparationSnapshot(true, inventory, equipment, canonicalIds, chargeStateCapture.capture());
    }

    private Map<Integer, Integer> usablePouchContents(DeathContext context,
        Map<Integer, Integer> carried, Map<Integer, Integer> bankItems)
    {
        // Global pouch varbits alone do not prove the account currently owns a usable pouch.
        return context.isPouchContentsKnown()
            && (deathStateCapture.containsRunePouch(carried) || deathStateCapture.containsRunePouch(bankItems))
            ? context.getPouchContents() : Collections.emptyMap();
    }

    private Spellbook captureSpellbook()
    {
        try
        {
            // RuneLite's spellbook varbit uses the same 0-3 mapping as Inventory Setups.
            switch (client.getVarbitValue(VarbitID.SPELLBOOK))
            {
                case 0: return Spellbook.STANDARD;
                case 1: return Spellbook.ANCIENT;
                case 2: return Spellbook.LUNAR;
                case 3: return Spellbook.ARCEUUS;
                default: return null;
            }
        }
        catch (RuntimeException ignored)
        {
            // Unavailable cache state must not silently become the Standard spellbook.
            return null;
        }
    }

    private void syncProfile()
    {
        String key = client.getGameState() == GameState.LOGGED_IN ? config.getRSProfileKey() : null;
        if (Objects.equals(profile, key))
        {
            return;
        }
        boolean pendingBankChange = bankDirty;
        clear();
        bankDirty = pendingBankChange;
        profile = key;
        if (key == null)
        {
            return;
        }
        try
        {
            BankObservation loaded = gson.fromJson(config.getRSProfileConfiguration(GROUP, BANK_KEY), BankObservation.class);
            if (loaded != null && (loaded.version == 2 || loaded.version == 3) && loaded.seenAt > 0
                && loaded.seenAt <= System.currentTimeMillis() && validCounts(loaded.items) && validCounts(loaded.carried)
                && (loaded.version == 2 || validCounts(loaded.pouchContents)))
            {
                // Older observations did not record pouch contents. Deduct all currently loaded
                // runes from the old bank estimate rather than inventing an unobserved baseline.
                if (loaded.version == 2) { loaded.pouchContents = Collections.emptyMap(); }
                bank = loaded;
            }
        }
        catch (RuntimeException ex)
        {
            log.warn("Ignoring invalid AIO Slayer bank observation");
        }
        try
        {
            String[] loaded = gson.fromJson(config.getRSProfileConfiguration(GROUP, REQUIREMENTS_KEY), String[].class);
            if (loaded != null)
            {
                for (String requirement : loaded)
                {
                    if (requirement != null && !requirement.trim().isEmpty())
                    {
                        confirmations.add(requirement);
                    }
                }
            }
        }
        catch (RuntimeException ex)
        {
            log.warn("Ignoring invalid AIO Slayer access confirmations");
        }
    }

    private Map<Integer, Integer> read(ItemContainer container)
    {
        Map<Integer, Integer> counts = new LinkedHashMap<>();
        if (container == null)
        {
            return counts;
        }
        for (Item item : container.getItems())
        {
            if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
            {
                continue;
            }
            ItemComposition definition = itemManager.getItemComposition(item.getId());
            if (definition.getPlaceholderTemplateId() != -1 || definition.getNote() != -1)
            {
                continue; // Neither placeholders nor bank notes can be worn or used as supplies.
            }
            counts.merge(item.getId(), item.getQuantity(), PlayerStateCapture::add);
        }
        return counts;
    }

    private PlayerSnapshot.ItemStats describe(int id)
    {
        ItemComposition definition = itemManager.getItemComposition(id);
        String name = definition.getName();
        String lower = name.toLowerCase(Locale.ROOT);
        boolean usable = !lower.contains("(broken)") && !lower.contains("(mangled)")
            && !lower.matches(".*(?:helm|platebody|platelegs|plateskirt|hood|robe top|robe skirt|staff|warspear|hammers|crossbow) 0$");
        boolean food = isHealingFood(definition);
        ItemStats stats = itemManager.getItemStats(id);
        ItemEquipmentStats e = stats == null ? null : stats.getEquipment();
        if (e == null)
        {
            return new PlayerSnapshot.ItemStats(id, name, null, "ANY", usable, false,
                definition.isStackable(), 0, 0, 0, 0, 0, 0, 0, 0, food);
        }
        String slot = e.getSlot() >= 0 && e.getSlot() < SLOTS.length ? SLOTS[e.getSlot()] : null;
        // Uncharged jewellery can retain its combat stats. Powered weapons need a usable
        // charged form; the bundled item definitions apply any additional form restrictions.
        if ("WEAPON".equals(slot) && (lower.contains("uncharged") || lower.contains("(empty)")
            || lower.contains("(inactive)")))
        {
            usable = false;
        }
        double melee = Math.max(e.getAstab(), Math.max(e.getAslash(), e.getAcrush()));
        String style = "ANY";
        if ("WEAPON".equals(slot))
        {
            style = "MELEE";
            if (e.getRstr() > 0 || e.getArange() > melee)
            {
                style = "RANGED";
            }
            if (e.getMdmg() > 0 || e.getAmagic() > Math.max(melee, e.getArange())
                || lower.contains("staff") || lower.contains("wand") || lower.contains("trident"))
            {
                style = "MAGIC";
            }
        }
        else if (e.getMdmg() > 0 || e.getAmagic() > Math.max(melee, e.getArange()))
        {
            style = "MAGIC";
        }
        else if (e.getRstr() > 0 || e.getArange() > Math.max(melee, e.getAmagic()))
        {
            style = "RANGED";
        }
        else if (e.getStr() > 0 || melee > Math.max(e.getArange(), e.getAmagic()))
        {
            style = "MELEE";
        }
        double defence = (e.getDstab() + e.getDslash() + e.getDcrush() + e.getDmagic() + e.getDrange()) / 5.0;
        return new PlayerSnapshot.ItemStats(id, name, slot, style, usable, e.isTwoHanded(),
            definition.isStackable(), melee, e.getStr(), defence, e.getPrayer(),
            e.getArange(), e.getRstr(), e.getAmagic(), e.getMdmg(), food);
    }

    private boolean isHealingFood(ItemComposition definition)
    {
        if (definition.getNote() != -1 || definition.getPlaceholderTemplateId() != -1)
        {
            return false;
        }
        String[] actions = definition.getInventoryActions();
        boolean edible = false;
        if (actions != null)
        {
            for (String action : actions)
            {
                if ("Eat".equalsIgnoreCase(action)) { edible = true; break; }
            }
        }
        if (!edible) { return false; }
        Effect effect = itemStatChanges.get(definition.getId());
        if (effect == null) { return false; }
        StatsChanges changes = effect.calculate(client);
        if (changes == null || changes.getStatChanges() == null) { return false; }
        boolean healing = false;
        for (StatChange change : changes.getStatChanges())
        {
            if (change == null || change.getStat() != Stats.HITPOINTS) { continue; }
            // Actual healing is zero at full HP. The minimum theoretical effect also
            // excludes foods whose possible outcomes include damage rather than healing.
            int minimum = change instanceof RangeStatChange
                ? ((RangeStatChange) change).getMinTheoretical() : change.getTheoretical();
            if (minimum < 0) { return false; }
            healing |= minimum > 0;
        }
        return healing;
    }

    private static void merge(Map<Integer, Integer> target, Map<Integer, Integer> source)
    {
        source.forEach((id, quantity) -> target.merge(id, quantity, PlayerStateCapture::add));
    }

    private static int add(int first, int second)
    {
        return (int) Math.min(Integer.MAX_VALUE, (long) first + second);
    }

    private static boolean validCounts(Map<Integer, Integer> counts)
    {
        return counts != null && counts.entrySet().stream().allMatch(e -> e.getKey() != null
            && e.getKey() > 0 && e.getValue() != null && e.getValue() >= 0);
    }

    private static final class BankObservation
    {
        private int version;
        private long seenAt;
        private Map<Integer, Integer> items;
        private Map<Integer, Integer> carried;
        private Map<Integer, Integer> pouchContents;
    }
}

package com.danieljglover.allinslayer.bank.advisor;

import com.danieljglover.allinslayer.model.advisor.ChargeObservation;
import com.danieljglover.allinslayer.integration.advisor.WeaponChargesBridge;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Locale;
import java.util.Objects;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.util.Text;

/**
 * Client-thread Check observations with optional, explicitly labelled Weapon Charges estimates.
 * Moving the same item between inventory and equipment preserves its observed balance.
 */
@Singleton
public final class ChargeStateCapture
{
    private static final int CHECK_WINDOW_TICKS = 3;
    private static final Map<String, Rule> FAMILIES = new LinkedHashMap<>();
    private static final Map<Integer, Rule> RULES = rules();
    private static final int SCALES = 12934;
    private static final Map<String, Integer> DARTS = darts();
    private final Client client;
    private final ConfigManager config;
    private final WeaponChargesBridge bridge;
    private final Map<Integer, ChargeObservation> observations = new LinkedHashMap<>();
    private String profile;
    private long accountHash;
    private int pendingItemId = -1;
    private int pendingTick;
    private int suppressThroughTick = -1;
    private boolean sessionSettled;

    public void setSessionSettled(boolean ready)
    {
        syncIdentity();
        sessionSettled = ready;
        if (!ready) { invalidate(); }
    }

    @Inject
    public ChargeStateCapture(Client client, ConfigManager config, WeaponChargesBridge bridge)
    {
        this.client = client;
        this.config = config;
        this.bridge = bridge;
    }

    public void invalidate()
    {
        observations.clear();
        pendingItemId = -1;
        suppressThroughTick = -1;
    }

    public void equipmentUsed()
    {
        ItemContainer worn = client.getItemContainer(InventoryID.WORN);
        if (worn == null) { return; }
        for (Item item : worn.getItems()) { observations.remove(item.getId()); }
        pendingItemId = -1;
    }

    public void providerChanged(ConfigChanged event)
    {
        if (!WeaponChargesBridge.CONFIG_GROUP.equals(event.getGroup()) || !syncIdentity()) { return; }
        observations.entrySet().removeIf(entry -> {
            String family = bridge.familyKey(entry.getKey());
            if (family == null || !(family.equals(event.getKey()) || "blowpipe".equals(family)
                && event.getKey().startsWith("blowpipe"))) { return false; }
            if ("blowpipe".equals(family)) { return blowpipeChanged(event, entry.getValue()); }
            return balanceChanged(event.getNewValue(), entry.getValue().getCharges());
        });
    }

    private static boolean blowpipeChanged(ConfigChanged event, ChargeObservation observation)
    {
        Map<Integer, Integer> resources = observation.getResources();
        if ("blowpipeScales".equals(event.getKey()))
        {
            return balanceChanged(event.getNewValue(), resources.getOrDefault(SCALES, 0));
        }
        int darts = resources.entrySet().stream().filter(e -> DARTS.containsValue(e.getKey()))
            .mapToInt(Map.Entry::getValue).sum();
        if ("blowpipeDarts".equals(event.getKey())) { return balanceChanged(event.getNewValue(), darts); }
        if ("blowpipeDartType".equals(event.getKey()) && darts > 0)
        {
            Integer dartId = event.getNewValue() == null ? null : DARTS.get(event.getNewValue().toLowerCase(Locale.ROOT));
            return dartId == null || !resources.containsKey(dartId);
        }
        return false;
    }

    private static boolean balanceChanged(String raw, int observed)
    {
        try
        {
            double value = Double.parseDouble(raw);
            return !Double.isFinite(value) || value != observed;
        }
        catch (RuntimeException ignored) { return true; }
    }

    public void observe(MenuOptionClicked event)
    {
        if (!syncIdentity() || !sessionSettled) { return; }
        String option = Text.removeTags(event.getMenuOption()).toLowerCase(Locale.ROOT);
        int clickedId = clickedItemId(event);
        if (!"check".equals(option))
        {
            pendingItemId = -1;
            if (option.equals("wear") || option.equals("wield") || option.equals("equip")
                || option.equals("remove") && equipmentSlot(event.getParam1()) >= 0) { return; }
            if (option.contains("charge") || option.equals("use") || option.contains("dismantle")) { invalidate(); }
            else if (event.isItemOp() || equipmentSlot(event.getParam1()) >= 0 && !option.equals("examine")
                || option.contains("deposit") || option.contains("withdraw"))
            {
                if (clickedId <= 0 && option.contains("deposit")) { invalidate(); return; }
                Rule affected = rule(clickedId);
                observations.keySet().removeIf(id -> affected != null && rule(id) == affected);
            }
            return;
        }
        int tick = client.getTickCount();
        if (tick <= suppressThroughTick) { return; }
        if (pendingItemId != -1 && tick - pendingTick <= CHECK_WINDOW_TICKS)
        {
            // Two checks can produce indistinguishable generic messages in either order.
            pendingItemId = -1;
            suppressThroughTick = tick + CHECK_WINDOW_TICKS;
            return;
        }
        pendingItemId = -1;
        int group = event.getParam1() >>> 16;
        if (group != InterfaceID.INVENTORY && group != InterfaceID.BANKSIDE
            && group != InterfaceID.WORNITEMS && group != InterfaceID.EQUIPMENT)
        {
            return;
        }
        int id = clickedId;
        Rule rule = rule(id);
        if (rule == null || !uniquelyCarried(id, rule)) { return; }
        observations.remove(id);
        pendingItemId = id;
        pendingTick = tick;
    }

    private int clickedItemId(MenuOptionClicked event)
    {
        int slot = equipmentSlot(event.getParam1());
        if (slot >= 0)
        {
            // Equipped-item menus belong to a slot layer, which need not carry an item ID.
            // Resolve the clicked slot in WORN, as Weapon Charges does for equipped weapons.
            ItemContainer worn = client.getItemContainer(InventoryID.WORN);
            Item item = worn == null ? null : worn.getItem(slot);
            return item == null ? -1 : item.getId();
        }
        int id = event.getItemId();
        Widget widget = event.getWidget();
        return id > 0 || widget == null ? id : widget.getItemId();
    }

    private static int equipmentSlot(int component)
    {
        switch (component)
        {
            case InterfaceID.Wornitems.SLOT0: case InterfaceID.Equipment.SLOT0: return 0;
            case InterfaceID.Wornitems.SLOT1: case InterfaceID.Equipment.SLOT1: return 1;
            case InterfaceID.Wornitems.SLOT2: case InterfaceID.Equipment.SLOT2: return 2;
            case InterfaceID.Wornitems.SLOT3: case InterfaceID.Equipment.SLOT3: return 3;
            case InterfaceID.Wornitems.SLOT4: case InterfaceID.Equipment.SLOT4: return 4;
            case InterfaceID.Wornitems.SLOT5: case InterfaceID.Equipment.SLOT5: return 5;
            case InterfaceID.Wornitems.SLOT7: case InterfaceID.Equipment.SLOT7: return 7;
            case InterfaceID.Wornitems.SLOT9: case InterfaceID.Equipment.SLOT9: return 9;
            case InterfaceID.Wornitems.SLOT10: case InterfaceID.Equipment.SLOT10: return 10;
            case InterfaceID.Wornitems.SLOT12: case InterfaceID.Equipment.SLOT12: return 12;
            case InterfaceID.Wornitems.SLOT13: case InterfaceID.Equipment.SLOT13: return 13;
            default: return -1;
        }
    }

    public void observe(ChatMessage event)
    {
        if (!syncIdentity() || !sessionSettled
            || event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
        {
            return;
        }
        if (pendingItemId == -1)
        {
            invalidateForChargeMessage(event.getMessage());
            return;
        }
        int tick = client.getTickCount();
        if (tick < pendingTick || tick - pendingTick > CHECK_WINDOW_TICKS)
        {
            invalidateForChargeMessage(event.getMessage());
            pendingItemId = -1;
            return;
        }
        Rule rule = rule(pendingItemId);
        if (rule == null) { pendingItemId = -1; return; }
        String message = Text.removeTags(event.getMessage());
        Matcher match = rule.message.matcher(message);
        boolean full = rule.fullMessage != null && rule.fullMessage.matcher(message).matches();
        if (!match.matches() && !full) { invalidateForChargeMessage(event.getMessage()); return; }
        int id = pendingItemId;
        pendingItemId = -1;
        if (!uniquelyCarried(id, rule)) { return; }
        try
        {
            if (rule == FAMILIES.get("blowpipe"))
            {
                int scales = count(match.group(3));
                if (scales > 16383) { return; }
                Map<Integer, Integer> resources = new LinkedHashMap<>();
                resources.put(SCALES, scales);
                int charges = 0;
                if (match.group(1) != null)
                {
                    Integer dartId = DARTS.get(match.group(1).toLowerCase(Locale.ROOT));
                    if (dartId == null) { return; }
                    int darts = count(match.group(2));
                    if (darts > 16383) { return; }
                    resources.put(dartId, darts);
                    charges = Math.min(darts, scales);
                }
                observations.put(id, new ChargeObservation(id, charges, tick, true, "In-game Check", resources));
                return;
            }
            int charges = full ? rule.maximum : count(match.group(1));
            if (charges >= 0 && charges <= rule.maximum)
            {
                observations.put(id, new ChargeObservation(id, charges, tick, true, "In-game Check",
                    rule == FAMILIES.get("serpentine_helm") ? Collections.singletonMap(SCALES, charges) : Collections.emptyMap()));
            }
        }
        catch (NumberFormatException ignored)
        {
            // An unexpected game message must remain unknown, never become zero.
        }
    }

    public Map<Integer, ChargeObservation> capture()
    {
        if (!syncIdentity() || !sessionSettled) { return Collections.emptyMap(); }
        observations.entrySet().removeIf(entry -> !uniquelyCarried(entry.getKey(), rule(entry.getKey())));
        Map<Integer, ChargeObservation> result = new LinkedHashMap<>();
        bridge.snapshot().forEach((id, reading) -> {
            int charges = reading.getCharges() == null ? resourceCapacity(reading.getResources()) : reading.getCharges();
            result.put(id, new ChargeObservation(id, charges, -1, false,
                reading.getSource() + " estimate (last check unknown)", reading.getResources()));
        });
        result.putAll(observations);
        return Collections.unmodifiableMap(result);
    }

    private void invalidateForChargeMessage(String message)
    {
        String text = Text.removeTags(message).toLowerCase(Locale.ROOT);
        if (text.matches(".*(?:charg|revenant ether|scales|darts?|pages?|blood shard|crystal shard|degrad|disintegrat|shatter).*"))
        {
            observations.clear();
        }
    }

    private static int count(String value)
    {
        return "one".equalsIgnoreCase(value) || "a".equalsIgnoreCase(value) ? 1
            : "no".equalsIgnoreCase(value) ? 0 : Integer.parseInt(value.replace(",", ""));
    }

    private static int resourceCapacity(Map<Integer, Integer> resources)
    {
        Integer scales = resources.get(SCALES);
        Integer darts = resources.entrySet().stream().filter(e -> DARTS.containsValue(e.getKey()))
            .map(Map.Entry::getValue).findFirst().orElse(null);
        return scales == null || darts == null ? -1 : Math.min(scales, darts);
    }

    private Rule rule(int id)
    {
        Rule nativeRule = RULES.get(id);
        return nativeRule != null ? nativeRule : FAMILIES.get(bridge.familyKey(id));
    }

    private boolean syncIdentity()
    {
        String current = client.getGameState() == GameState.LOGGED_IN ? config.getRSProfileKey() : null;
        long hash = current == null ? 0 : client.getAccountHash();
        if (!Objects.equals(profile, current) || accountHash != hash)
        {
            invalidate();
            sessionSettled = false;
            profile = current;
            accountHash = hash;
        }
        return current != null;
    }

    private boolean uniquelyCarried(int itemId, Rule rule)
    {
        if (rule == null) { return false; }
        int count = 0;
        boolean exact = false;
        for (int containerId : new int[]{InventoryID.INV, InventoryID.WORN})
        {
            ItemContainer container = client.getItemContainer(containerId);
            if (container == null) { continue; }
            for (Item item : container.getItems())
            {
                if (rule(item.getId()) == rule && item.getQuantity() > 0)
                {
                    if (item.getQuantity() > 1 || ++count > 1) { return false; }
                    exact |= item.getId() == itemId;
                }
            }
        }
        return count == 1 && exact;
    }

